window.__D("text/maamarim-melukatim/c000",{"p":[[1500360002,"<h3>בס\"ד. יום ב' דראש-השנה ה'תשכ\"ג<sup data-n=\"1\">*</sup></h3>\n<b>יבחר</b> לנו את נחלתינו את גאון יעקב אשר אהב סלה<sup data-n=\"2\">1</sup>, ומביא כ\"ק מו\"ח אדמו\"ר במאמרו ד\"ה זה (שבהמשך ר\"ה תש\"ג)<sup data-n=\"3\">2</sup> פירוש התרגום, ירעי לנא למירת ית אחסנתנא ית בית מקדשא דיעקב דרחים לעלמין, ומדייק בזה, הרי בית המקדש הוא של הקב\"ה כמ\"ש<sup data-n=\"4\">3</sup> ועשו <i>לי</i> מקדש [דישראל הם רק עושים את המקדש, אבל המקדש עצמו הוא של הקב\"ה] ולמה נקרא בית מקדשא <i>דיעקב</i>. גם, מהי השייכות דגאון יעקב שקאי על בית המקדש לנחלתינו. ומבאר בהמאמר<sup data-n=\"5\">4</sup>, דנחלתינו הוא נקודת היהדות השורה בנקודת הלב שהוא הבית מקדשא דיעקב, כמ\"ש<sup data-n=\"4\">3</sup> ועשו לי מקדש ושכנתי בתוכם, בתוכו לא נאמר אלא בתוכם, בתוך כאו\"א מישראל<sup data-n=\"6\">5</sup>. והנה הפירוש הפשוט דיבחר לנו גו' את גאון יעקב הוא, שלעתיד לבוא יחזיר לנו את בית מקדשינו<sup data-n=\"7\">6</sup>. וצריך להבין הקשר דהפירוש (שבהמאמר) שגאון יעקב קאי על בית המקדש שבכאו\"א מישראל עם הפירוש (הפשוט) שגאון יעקב קאי על בית המקדש השלישי שיבנה במהרה בימינו.\nב) <b>והנה</b> פסוק זה הוא בהמזמור שאומרים ז' פעמים קודם תקיעת שופר, והשייכות דמזמור זה לתקיעת שופר (בפשטות) הוא, כי במזמור זה<sup data-n=\"8\">7</sup> נאמר עלה אלקים בתרועה הוי' בקול שופר, ואמרו רז\"ל<sup data-n=\"9\">8</sup>, שבתחלה הקב\"ה יושב (ועולה) על כסא דין, עלה <i>אלקים</i> בתרועה, וע\"י שישראל נוטלין את שופריהן ותוקעין לפני הקב\"ה הוא עומד מכסא דין ויושב בכסא רחמים, <i>הוי'</i> בקול שופר, ומתמלא<sup data-n=\"10\">9</sup> עליהם רחמים ומרחם עליהם והופך עליהם מדת הדין לרחמים. ולכן אומרים מזמור זה קודם תקיעת שופר בכדי להביא ראי' מן התורה<sup data-n=\"11\">10</sup> על ההמשכה (דעומד מכסא דין ויושב בכסא רחמים<sup data-n=\"12\">11</sup>) שע\"י תקיעת שופר.<b>והנה</b> מזה שאומרים לפני תקיעת שופר (לא רק פסוק זה, אלא) את כל המזמור, מובן, שכל הפסוקים דהמזמור שייכים להענין דעומד מכסא דין ויושב בכסא רחמים שע\"י תקיעת שופר<sup data-n=\"13\">12</sup>. ומכ\"ש הפסוק יבחר לנו גו' שהוא בסמיכות להפסוק עלה אלקים בתרועה גו', שזה מורה, שפסוק זה שייך לעלה אלקים בתרועה גו'. וצריך להבין, דענין יבחר לנו הוא שהבחירה דהקב\"ה בישראל היא מצד עצמו (ולא שהעבודה דישראל מעוררת שיבחור בהם), ויתירה מזו, דענין הבחירה הוא<sup data-n=\"14\">13</sup> בהעצמות, שאין שייך שם הענין דאתערותא דלתתא. והיינו, דנוסף לזה שהבחירה <i>בפועל</i> היא מצד עצמו ולא שמתעוררת ע\"י אתעדל\"ת, אלא שבמקום זה (שבו הוא ענין הבחירה) <i>אין שייך כלל</i> לעורר ע\"י אתעדל\"ת. וענין עלה אלקים בתרועה גו' הוא, שתקיעת שופר דישראל מעוררת שיהי' עומד מכסא דין ויושב בכסא רחמים. ומהסמיכות דשני הפסוקים משמע דשני הענינים שייכים זל\"ז. והיינו, דע\"י שישראל נוטלין את שופריהן ותוקעין לפני הקב\"ה הם ממשיכים לא רק הרחמים המתעוררים ע\"י עבודה (אתערותא דלעילא שמתעוררת ע\"י אתערותא דלתתא), אלא שעי\"ז ממשיכים הם גם הרחמים<sup data-n=\"15\">14</sup> שמצד בחירת הקב\"ה בישראל, יבחר לנו.\nג) <b>ויש</b> להוסיף, דענין הנ\"ל (שע\"י שישראל תוקעין בשופר ממשיכים הם גם הענין דבחירת העצמות שאין שייך לעורר שם ע\"י אתעדל\"ת) מובן גם מהידוע<sup data-n=\"16\">15</sup> שעיקר<sup data-n=\"17\">16</sup> ענין ר\"ה הוא בנין המלכות, כמאמר רז\"ל<sup data-n=\"18\">17</sup> אמרו לפני מלכיות כדי שתמליכוני עליכם. ומה שאמרו<sup data-n=\"19\">18</sup> מצות היום בשופר הוא, כי הענין דתמליכוני עליהם הוא ע\"י תקיעת שופר<sup data-n=\"20\">19</sup>, כהמשך מארז\"ל הנ\"ל ובמה בשופר<sup data-n=\"21\">20</sup>. והשייכות דר\"ה לבנין המלכות (בפשטות) היא<sup data-n=\"22\">21</sup>, לפי שבר\"ה הוא חידוש מעשה בראשית. כמו שאומרים<sup data-n=\"23\">22</sup> זה היום תחלת מעשיך, שבכל ר\"ה מתהוים כל העולמות<sup data-n=\"24\">23</sup> מחדש כמו שהי' בפעם הראשונה. והענין הוא, דהתהוות כל העולמות היא ממדת מלכותו ית'. והמשכתהמלכות שבכל ר\"ה (כולל גם ר\"ה הראשון שבתחלת הבריאה) היא רק על שנה אחת<sup data-n=\"25\">24</sup>, ובערב ר\"ה עם חשיכה<sup data-n=\"26\">25</sup> היא חוזרת ועולה ונכללת במקורה<sup data-n=\"25\">24</sup>. אלא שהעלי' והסילוק הוא רק בפנימיות המלכות, שהוא התענוג והרצון שבמלכות. והחיות דהעולם בר\"ה (גם לפני הענין דתמליכוני עליכם) הוא מחיצוניות המלכות<sup data-n=\"27\">26</sup>, בדוגמת אדם שעושה מלאכה כשהוא עיף ורפה ידים ואין לו תענוג בזה<sup data-n=\"28\">27</sup>. וכפתגם הידוע<sup data-n=\"29\">28</sup>, שבליל ר\"ה (לפני הענין דתמליכוני עליכם) העולם הוא במצב דהתעלפות. וזהו אמרו לפני מלכיות כדי שתמליכוני עליכם, שיהי' לו רצון ותענוג במלוכה. והנה ידוע<sup data-n=\"28\">27</sup> שהסילוק שבר\"ה הוא בכל המדריגות (מעשה, דיבור, מחשבה, מדות ושכל), דכל הדברים חוזרין לקדמותן. והמשכת המלכות (רצון ותענוג במלוכה) בר\"ה היא ע\"י שממשיכים מעצמות אוא\"ס. ומזה שהענין דתמליכוני עליכם הוא ע\"י תקיעת שופר כנ\"ל, מובן, שתקיעת שופר מגעת בעצמות אוא\"ס.\n<b>וצריך</b> להבין, הרי תקיעת שופר היא מצוה, וענין הציוויים (מצוות) שייך דוקא לאחרי שהוא ית' נעשה מלך, כמאמר<sup data-n=\"30\">29</sup> קבלו מלכותי תחלה ואח\"כ אגזור עליכם גזירות, ובכדי שיהי' תמליכוני עליכם (שישראל <i>עושים</i> אותו ית' למלך) הוא ע\"י שמגיעים בעצמות אוא\"ס כמו שהוא לפני (למעלה) שנעשה מלך, ואיך אפשר שע\"י תקיעת שופר (קיום מצות וציווי המלך) יעשו אותו ית' למלך<sup data-n=\"31\">30</sup>. ומזה מובן, דבתקיעת שופר שני ענינים, המצוה דתקיעת שופר, וזה שע\"י תקיעת שופר מגיעים בעצמות אוא\"ס שלמעלה מבחינת מלך.\nד) <b>והנה</b> במק\"א<sup data-n=\"32\">31</sup> מבואר הטעם על זה שבכדי שיהי' בנין המלכות הוא ע\"י ההמשכה מעצמות אוא\"ס, כי מלכות ענינה הוא גילוי. וגם המלכות שבכל ספירה ענינה הוא כח הגילוי של הספירה<sup data-n=\"33\">32</sup>. אלא שהגילוי ע\"י המלכות דהספירות הוא באצילות<sup data-n=\"34\">33</sup>, ובכדי שיהי' הגילוי בבי\"ע הוא ע\"י המלכות כמו שהיא פרצוף בפ\"ע. ע\"ד הדיבור שבאדם (מלכות הו\"ע הדיבור, מלכות פה<sup data-n=\"35\">34</sup>) שהוא גילוילזולתו. וענין בנין המלכות שבר\"ה הוא<sup data-n=\"36\">35</sup>, שהגילוי יהי' לא רק בנבראים דבי\"ע הרוחניים אלא גם בעשי' הגשמית, ובזה עצמו – למטה מטה, עד בהדומם, כמו שאומרים בתפלות ר\"ה וידע <i>כל</i> פעול כי אתה פעלתו, שגם הדומם (שבעשי')<sup data-n=\"37\">36</sup> ידע כי אתה פעלתו.\n<b>וזהו</b> אמרו לפני מלכיות כדי שתמליכוני עליכם כו' ובמה בשופר, דמהטעמים על זה שאין מספיק אמירת מלכיות וצריך גם לתקוע בשופר, הוא<sup data-n=\"38\">37</sup>, כי הענין דתמליכוני שבר\"ה הוא שיומשך הגילוי בעשי', וזה נעשה ע\"י תקיעת שופר במעשה. וע\"י שהמעשה דתקיעת שופר הוא שתוקעין בשופר של בהמה, נמשך הגילוי גם בענינים הגשמיים, בהמה שבאדם. ובכדי שיומשך הגילוי למטה יותר עד בהדומם, צריך שקרן השופר שבו תוקעין יהי' תלוש (ולא מחובר להבהמה), דומם.\n<b>והנה</b> כל שההמשכה היא למטה יותר, הוא ע\"י ששורש ההמשכה הוא למעלה יותר. וכמובא<sup data-n=\"39\">38</sup> הדוגמא לזה מכח ההפלאה שבחכמה, שהירידה היא כפי אופן ההפלאה. שבכדי להוריד את השכל ולהלבישו במשל (ושהמשל יהי' מכוון) הוא דוקא כשיודע את עצם הענין. ולהעיר, שבכח הירידה דשכל שני ענינים. שביכלתו <i>לצמצם</i> את השכל שיהי' לפי ערך התלמיד, ושביכלתו <i>להעלים</i> את השכל ע\"י שמלבישו במשל. וגם בכדי לצמצם את השכל צריך לכח עליון יותר. ויש לומר, דהטעם שמביא בהמאמר ענין הירידה דהתלבשות במשל, הוא, כי מדבר כאן בכח <i>ההפלאה</i> (הפשטה) שבחכמה, ובענין זה נוגע יותר הירידה דהתלבשות במשל. דהגם שענין <i>ההתלבשות</i> במשל (משא\"כ הירידה דצמצום) הוא לכאורה <i>היפך</i> ענין ההפלאה, מ\"מ, בזה שמלביש את השכל במשל ניכר ומתגלה כח ההפלאה דחכמה. דזה שהתלבשות במשל הוא היפך ההפלאה הוא כשההפלאה היא מוגדרת ומצויירת בהציור דלמעלה מהתלבשות במשל, אבל מצד אמיתית ענין ההפלאה, אפשר להיות גם התלבשות במשל.\n<b>ויש</b> לומר, דהגילוי שע\"י המלכות כמו שהיא בהספירות דז\"א, גילוי באצילות, הוא ע\"ד הירידה דצמצום, והגילוי שע\"י המלכות כמו שהיא פרצוף בפ\"ע, גילוי בבי\"ע, הוא ע\"ד הירידה דהתלבשות במשלים<sup data-n=\"40\">39</sup>. ומזה מובן גודל העילוי דההמשכה שעל ידה נעשה בנין המלכות (ובפרט בנין המלכות דר\"ה) שאינה מוגדרת בהגדר והציור דלמעלה מהתלבשות, שלכן, ע\"י המשכה זו, נמשך ומתלבש הגילוי גם בבי\"ע, ובבי\"ע עצמם – אפילו בדומם, שגם הדומם ידע כי אתה פעלתו.ה) <b>ויש</b> לומר, דלפי ביאור זה, שהטעם שבכדי שיהי' בנין המלכות הוא ע\"י המשכה מעצמות אוא\"ס הוא כי בכדי שתהי' ירידה למטה מטה (ובאופן דהתלבשות) הוא ע\"י המשכת כח מופלא שאינו מוגדר, הירידה (הגילוי דמלכות) יש לה יחס לגבי כח המופלא. דכיון שההפלאה שלו הוא שאינו מוגדר בהציור דלמעלה דוקא וביכלתו גם לירד למטה, הרי הירידה למטה הוא גילוי ההפלאה שלו. ויתירה מזו, שגילוי ההפלאה שלו הוא גם <i>באופן</i> הירידה. דכל שהוא מופלא יותר ביכלתו לירד למטה יותר. ומזה מובן, דמ\"ש בהדרושים (שמבואר בהם ביאור זה) שבר\"ה צ\"ל ההמשכה מעצמות אוא\"ס, הכוונה בזה היא לההפלאה דאוא\"ס (שאינו מוגדר), ולא להעצמות ממש. משא\"כ להביאור דלעיל (סעיף ג) דהטעם שהמשכת המלכות בר\"ה צריכה להיות מעצמות אוא\"ס הוא לפי שעליית וסילוק המלכות היא בכל הדרגות (ולכן צריכה להיות ההמשכה ממקום נעלה ביותר), ההמשכה היא מעצמות אוא\"ס ממש.\nו) <b>והנה</b> ידוע<sup data-n=\"41\">40</sup> שבר\"ה שני ענינים. עיקר ענין ר\"ה (א' בתשרי) הוא שביום זה נברא האדם, ובכל שנה ביום זה מתחדש הענין דבריאת האדם, אתם<sup data-n=\"42\">41</sup> קרויין אדם<sup data-n=\"43\">42</sup>. ועוד ענין בר\"ה, דכיון שהאדם הוא תכלית הבריאה, לכן, בכל שנה, ביום בריאת האדם, מתחדשת גם כללות הבריאה שנבראה בכ\"ה באלול<sup data-n=\"44\">43</sup>. וי\"ל דזהו מ\"ש זה היום תחלת מעשיך זכרון ליום ראשון, דזה היום תחלת מעשיך קאי על האדם<sup data-n=\"45\">44</sup> (עיקר מעשיך) שנברא ביום זה עצמו, וזכרון ליום ראשון הוא שבר\"ה הוא זכרון ליום ראשון דהבריאה (כ\"ה באלול) שבו נברא העולם. וזה שבר\"ה הוא בנין המלכות הוא בשביל ב' הענינים. בכדי שע\"י המלכות יתהוו העולמות מחדש (כנ\"ל סעיף ג), ועיקר ענין בנין המלכות הוא בשביל תולדת הנשמות (בריאת האדם), דנשמות ומלכות הם ענין אחד<sup data-n=\"46\">45</sup> כמובן גם מזה שהמלכות נקראת כנסת ישראל.\n<b>ועפ\"ז</b><b>,</b> בכדי לפעול שיהי' בנין המלכות צריכים להמשיך ממקום שאין שם (לא רק מציאות העולמות, אלא שאין שם) גם המציאות דנשמות. וצריך להבין, איך שייך שהנשמות ע\"י עבודתם יגיעו למקום שלמעלה ממציאותם.\n<b>ונקודת</b> הביאור בזה, דזה שבעת סילוק המלכות (בהדרגות שלמעלה ממלכות) אין תפיסת מקום לכאורה לנשמות ועבודתם (כי נשמות ומלכות הם ענין אחד), הוא בנוגע <i>להמציאות</i> דנשמות, וענין תמליכוני (שישראל מבקשים ומתחננים להקב\"ה שיהי' מלך) הוא הביטול פנימי שמצד עצם הנשמה<sup data-n=\"47\">46</sup>, שמושרשת בהעצמות. וכשמתגלית עצם הנשמה היא ממשכת את העצמות. ועי\"ז נעשה גם בנין המלכות.ז) <b>וביאור</b> הענין דבנין המלכות שנעשה ע\"י המשכת העצמות שע\"י גילוי עצם הנשמה, יש לומר, ע\"פ המבואר בכ\"מ<sup data-n=\"48\">47</sup> בענין ישראל עלו במחשבה<sup data-n=\"49\">48</sup>, דמחשבה זו היא מחשבה עצמית. דמחשבה בכלל היא מחוץ להחושב [וכמו אדם החושב איזה דבר, דהמחשבה בהדבר היא למטה מהאדם עצמו, ובמילא היא כמו חוץ ממנו], והמחשבה דישראל היא חד עם החושב עצמו. וזהו במי נמלך בנשמותיהן של צדיקים<sup data-n=\"50\">49</sup> (ועמך כולם צדיקים<sup data-n=\"51\">50</sup>), שההמלכה דבמי נמלך היא לא רק על בריאת העולמות (אם לברוא עולמות או לא לברוא), אלא גם על המחשבה להתהוות העולמות (אם תהי' המחשבה להתהוות העולמות או לאו), דמזה מובן, שנשמות ישראל (שבהם נמלך אם תהי' המחשבה דבריאת העולמות) הם למעלה ממחשבה זו. כי המחשבה דבריאת העולמות, גם כמו שהיא בדרגא הכי נעלית, היא דוגמת אדם החושב איזה דבר (מחשבה <i>לברוא עולמות</i>), שהמחשבה היא חוץ ממנו, וישראל עלו במחשבה עצמית. ומבואר שם, דהטעם על זה שההמלכה על המחשבה דבריאת העולמות היתה עם ישראל שעלו במחשבה עצמית (אף שמחשבה עצמית היא למעלה מהמחשבה דבריאת העולמות), הוא, כי במחשבה עצמית שני אופנים. שחושב אודות עצמו, ושחושב בדבר הנבדל ממנו ואעפ\"כ אין המחשבה חוץ ממנו כי <i>הוא עצמו</i> הוא החושב. וזה שישראל עלו במחשבה הוא אופן הב' שבמחשבה עצמית, שהעצמות חושב כביכול בדבר הזולת [וזהו בנים אתם להוי' אלקיכם<sup data-n=\"52\">51</sup>, דכיון ששורש הנשמות הוא במחשבה העצמית, <i>שהעצמות</i> חושב כביכול <i>בדבר הזולת</i>, לכן, גם לאחרי שבאו בהמשכה הם כמו בנים, שבבן (דוגמת) שני ענינים הנ\"ל. שהבן הוא נבדל מהאב ואעפ\"כ יש בו מעצמיות האב]. ולכן ההמלכה על המחשבה דעולמות היתה עם ישראל. כי הכוונה דבריאת העולם [<i>שהתחתונים</i> יהיו <i>דירה לו ית'</i>] נשלמת ע\"י הנשמות.\n<b>ויש</b> לומר, שהשייכות דנשמות למלכות כמו שהם בשרשם במחשבה העצמית, היא, דזה שהעצמות חושב כביכול בדבר הזולת הוא דוגמת המלכות, דענין המלכות הוא על זולת דוקא, אין מלך בלא עם<sup data-n=\"53\">52</sup>. ועפ\"ז יש לבאר הטעם על זה שע\"י גילוי עצם הנשמה (שע\"י תקיעת שופר) נעשה בנין המלכות, כי ע\"י שמתגלה שרש הנשמה כמו שהיא במחשבה העצמית, נעשה עי\"ז המשכת המלכות משרשה האמיתי כמו שהיא במחשבה העצמית.\nח) <b>וצריך</b> להבין, דלפי הנ\"ל זה שע\"י תקיעת שופר נעשה הענין דתמליכוני עליכם הוא לפי שע\"י תקיעת שופר מתגלית שורש הנשמה כמו שהיא מושרשת בהעצמות שלמעלה מענין המצוות, ומזה שתקיעת שופר היא מצוה, מובן, שהענין דתמליכוני עליכם שייך גם להמצוה דתקיעת שופר.<b>ויובן</b> זה ע\"פ מה שמבאר כ\"ק מו\"ח אדמו\"ר בהמשך ר\"ה הנ\"ל<sup data-n=\"54\">53</sup>, שבהרצון דאנא אמלוך, ג' מדריגות. רצון גלוי, רצון נעלם ורצון המוחלט בעצמותו. וג' מדריגות אלו נחלקות לב' סוגים. דרצון הגלוי והנעלם, שניהם הם בגילוי בו בעצמו, והחילוק שביניהם הוא בנוגע להפועל, דרצון הגלוי הוא בהתעוררות ששייך לפועל, ורצון הנעלם הוא רק הסכם שאינו שייך לפועל (ולכן נק' בשם נעלם, כי הוא נעלם ורחוק מהפועל). ורצון המוחלט בעצמותו הוא נעלם לגמרי, היינו שהוא נעלם גם לגבי עצמו. [וע\"ד הרצון לבית, דכל אדם יש לו (מצד עצם נפשו, גם כשאינו יודע מזה) יש לו רצון לבית, כי זה נוגע לעצם מציאותו]. ועוד חילוק בין רצון הגלוי לרצון הנעלם, שההתעוררות דרצון הגלוי הוא ע\"י אתערותא דלתתא, ע\"י שישראל מקבלים עליהם עול מלכותו ית' ומבקשים מלוך על העולם כולו בכבודך. וענין זה (שהתעוררות רצון הגלוי הוא ע\"י אתעדל\"ת) הי' גם בתחילת הבריאה, אלא שהתעוררות הרצון אז הי' ע\"י העלאת מ\"ן מיני' ובי'<sup data-n=\"55\">54</sup>. כמאמר במי נמלך בנשמותיהן של צדיקים, דע\"י שעלה לפניו ית' התענוג שיתענג בעבודת הצדיקים, ועמך כולם צדיקים, עי\"ז נתעורר ברצון גלוי למלוכה. [בדוגמת מלך בו\"ד, שהרצון (הגלוי) למלוכה מתעורר ע\"י הכתרת העם]. וההתעוררות דרצון הנעלם הוא לא ע\"י אתערותא דלתתא אלא שמתעורר מעצמו. ומבאר שם<sup data-n=\"56\">55</sup>, דזה שע\"י אתערותא דלתתא מתעורר הרצון גלוי, אין זה מצד מעלת האתעדל\"ת מצד עצמה, כי נברא הוא באין ערוך לגבי בורא (גם לגבי הדרגא דרצון הגלוי, ובפרט שגם רצון הגלוי הוא באוא\"ס שלפני הצמצום), אלא לפי שכן עלה ברצונו ית' ברצון הנעלם, ולמעלה יותר לפי שכן הוחלט ברצון המוחלט בעצמותו, שאתעדל\"ת תעורר את רצון הגלוי.\n<b>ויש</b> לומר, דזה שהוחלט ברצון המוחלט שהתעוררות רצון הגלוי תהי' ע\"י אתעדל\"ת דוקא, הוא, בכדי שמלכותו ית' על העולמות תהי' (גם) מצד העולמות. [וע\"ד כמו שהוא במלכותא דארעא<sup data-n=\"57\">56</sup>, דע\"י שהמלכות נעשית ע\"י הכתרת העם, שום תשים עליך מלך<sup data-n=\"58\">57</sup>, ביטול העם להמלך הוא מצד המציאות <i>שלהם</i><sup data-n=\"59\">58</sup>]. ועפ\"ז יובן השייכות דתמליכוני עליכם (גם) להמצוה דתקיעת שופר, כי קיום המצוה דתקיעת שופר הוא האתערותא דלתתא שמעוררת את רצון הגלוי. דהביטול שמצד עצם הנשמה שבתקיעת שופר, אינו אתערותא דלתתא לעורר את רצון הגלוי, כי ענין אתערותא דלתתא הוא שעבודת <i>התחתון</i> (מציאות) מעוררת את ההמשכה. ולכן צריך לשני הענינים. שהאתערותא דלתתא המעוררת את רצון הגלוי הוא קיום המצוה דתקיעת שופר. והמשכת רצון המוחלט [דזה שע\"י אתערותא דלתתא מתעורר הרצוןגלוי הוא לפי שכך הוחלט ברצון המוחלט] הוא ע\"י הביטול שמצד עצם הנשמה שבתקיעת שופר.\nט) <b>והנה</b> גם ברצון המוחלט שני ענינים. כמו שהוא בשייכות לרצון הגלוי, שע\"י המשכת רצון המוחלט מתעורר הרצון גלוי ע\"י אתעדל\"ת אף שהאתעדל\"ת היא באין ערוך, דענין זה הוא ההפלאה דעצמות אוא\"ס שאינו מוגדר בשום גדר וביכלתו ית' שתהי' ההתעוררות גם ע\"י ענין שבאין ערוך [וע\"ד המבואר לעיל (סעיף ה) בענין ההפלאה, שההפלאה היא זה שאינו מוגדר וביכלתו לירד למטה]. ורצון המוחלט עצמו, שהוא מצד בחירת העצמות. דזה שהוחלט אצלו לרצות כך הוא לא מפני שעי\"ז מתגלה ההפלאה שלו, אלא שכן בחר בבחירתו החפשית.\n<b>ויש</b> לומר, דזהו שבתקיעת שופר ג' ענינים (בכללות). המצוה שבה, ענין התשובה<sup data-n=\"60\">59</sup>, והביטול פנימי שמצד עצם הנשמה. שקיום המצוה דתקיעת שופר הוא האתעדל\"ת המעוררת את הרצון גלוי (כנ\"ל). וע\"י התשובה דתקיעת שופר, דענין התשובה הוא שיוצא מההגבלות שלו, נמשך ההפלאה (בל\"ג) שבעצמות אוא\"ס, שההתעוררות (דרצון הגלוי) הוא ע\"י ענין שבאין ערוך, רצון המוחלט שבנוגע לרצון הגלוי. וע\"י גילוי עצם הנשמה שע\"י תקיעת שופר נמשך רצון המוחלט עצמו, בחירת העצמות.\nיו\"ד) <b>ויש</b> לומר, דהטעם הפנימי על זה שבכל ר\"ה חוזרים כל הדברים לקדמותם, הוא, כי ע\"י שהמשכת המלכות (גם המשכת המלכות שבשביל העולמות) היא ע\"י אמרו לפני מלכיות, הביטול שמצד עצם הנשמה שמגיע וממשיך את רצון המוחלט עצמו, עי\"ז נמשך גילוי נעלה יותר גם בעולם. דהגם שבנוגע לעולמות הוא (בעיקר) המשכת הרצון גלוי, מ\"מ, כיון שהתעוררות והמשכת רצון הגלוי (ע\"י אתעדל\"ת) הוא ע\"י המשכת רצון המוחלט שע\"י הביטול שמצד עצם הנשמה, נמשך מעין זה גם בעולם. ועי\"ז נשלמת הכוונה דבריאת העולמות, שיהי' דירה לו ית' בתחתונים<sup data-n=\"61\">60</sup>.\nיא) <b>וזהו</b> יבחר לנו את נחלתינו את גאון יעקב, שהבקשה דפסוק זה (ועד\"ז בכללות המזמור) שאומרים קודם תקיעת שופר היא, שע\"י העבודה דתקיעת שופר תהי' (נוסף על קיום המצוה דתקיעת שופר, וענין התשובה דתקיעת שופר) גם גילוי עצם הנשמה כמו שהיא מושרשת בהעצמות, דזה שהנשמות מושרשות בהעצמות הוא לפי שכן בחר בבחירתו החפשית, יבחר לנו. וממשיך את נחלתינו את גאון יעקב, דגילוי ענין זה הוא בנקודת היהדות, נחלתינו, השורה בנקודת הלב שבכ\"א מישראל, בית מקדשא דיעקב. וע\"פ המבואר לעיל (סעיף יו\"ד) שע\"י גילוי שרש הנשמות נמשך מעין גילוי זה גם בעולם שעי\"ז נשלמת הכוונה דדירה בתחתונים, יש לבארהקשר דהפירוש שגאון יעקב קאי על בית המקדש שבכ\"א מישראל עם הפירוש שקאי על ביהמ\"ק השלישי, כי עיקר הענין דדירה בתחתונים יהי' בביהמ\"ק השלישי<sup data-n=\"62\">61</sup> שיבנה במהרה בימינו ע\"י משיח צדקנו.\n<b>ויש</b> לומר, שנוסף על השייכות דהפסוק יבחר לנו גו' לכללות הענין דתקיעת שופר, יש לו שייכות מיוחדת להפסוק (שלאחריו) עלה אלקים בתרועה הוי' בקול שופר, שדרשו חז\"ל דע\"י שישראל נוטלין את שופריהן ותוקעין לפני הקב\"ה הוא עומד מכסא דין ויושב בכסא רחמים<sup data-n=\"63\">62</sup>. והענין הוא, דהרחמים הנמשכים ע\"י אתעדל\"ת הם בהגבלה כפי האתעדל\"ת. והקשר דשני הפסוקים הוא, דזה שישראל נוטלין את שופריהן ותוקעין הוא לא רק אתעדל\"ת אלא שעי\"ז מתגלה בחירת העצמות בישראל, ולכן הרחמים הנמשכים עי\"ז הם רחמים בלי גבול. ונמשך מהקב\"ה עצמו (מהעצמות) לכאו\"א מישראל כתיבה וחתימה טובה לשנה טובה ומתוקה בטוב הנראה והנגלה.\n**********",[["1","*","יצא לאור ב<b>קונטרס ראש השנה – תנש\"א</b>, \"לקראת ראש השנה . . <i>ג' דסליחות</i>,<i> שנת ה'תש\"נ</i>\"."],["2","1","תהלים מז, ה."],["3","2","סה\"מ ה'תש\"ג ס\"ע 26 ואילך."],["4","3","תרומה כה, ח."],["5","4","בסיומו (סה\"מ שם ע' 35)."],["6","5","ראשית חכמה שער האהבה פ\"ו קרוב לתחילתו (ד\"ה ושני פסוקים – סט, ב). אלשיך עה\"פ תרומה שם קרוב לסופו (ד\"ה עוד יתכן – פט, א בדפוס ווארשא תרל\"ה). של\"ה סט, א. רא, א. שכה, ב. שכו, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380389\" data-slug=\"likkutei-torah\" data-id=\"4001380389\">לקו\"ת ר\"פ נשא (כ, סע\"ב</a>). ובכ\"מ."],["7","6","מפרשים לתהלים שם."],["8","7","פסוק ו'."],["9","8","ויק\"ר פכ\"ט, ג. וראה עד\"ז במדרש תהלים עה\"פ."],["10","9","כ\"ה בויק\"ר שם, דענין \"מתמלא עליהם רחמים וכו'\" הוא <i>לאחרי</i> שמביא הפסוק הוי' בקול שופר."],["11","10","סידור (עם דא\"ח) רלח, ב. המשך וככה תרל\"ז פרק פב-פג. סה\"מ תרצ\"ט ע' 28. ובכ\"מ. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380945\" data-slug=\"likkutei-torah\" data-id=\"4001380945\">לקו\"ת</a> דרושים לר\"ה נו, ג."],["12","11","והראי' מן התורה על שאר הענינים שנמשכים ע\"י תק\"ש היא בפסוקי שופרות, כבס' שבהערה הקודמת."],["13","12","להעיר מסידור האריז\"ל במקומו, שע\"י אמירת מזמור זה מהפכים מדה\"ד למדה\"ר. ולהעיר, שבסידור האריז\"ל שם, שענין זה נעשה ע\"י אמירת המזמור עצמו (ולא שעי\"ז ממשיכים (מביאים ראי') שזה יהי' ע\"י תק\"ש). וראה לקמן הערה 62."],["14","13","כמבואר בארוכה בהמשך ר\"ה הנ\"ל – סה\"מ ה'תש\"ג ע' 24."],["15","14","ראה בהמאמר שם (ריש ע' 27) \"דענינה הפנימי (של האהבה אשר אהב סלה) הוא <i>הרחמים</i>\". ואולי יש לומר, דבהמאמר מפרש, דמ\"ש בתרגום \"<i>דרחים</i> לעלמין\" הכוונה בזה היא גם לרחמים."],["16","15","המשך ר\"ה הנ\"ל בתחלתו. וראה פע\"ח שער ר\"ה. שער הכוונות שם. ובכ\"מ."],["17","16","כ\"ה הלשון בהמשך ר\"ה הנ\"ל שם. ולכאורה הכוונה, דבר\"ה יש גם הענין דזכרונות ושופרות, אבל העיקר הוא מלכיות. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300041353\" data-slug=\"likkutei-sichot\" data-id=\"1300041353\">לקו\"ש ח\"ד ע' 1354</a>, ובהערות שם."],["18","17","ר\"ה טז, א. שם לד, ב."],["19","18","שם כו, ב (במשנה). שם כז, א."],["20","19","וראה רס\"ג, הובא באבודרהם טעמי התקיעות, אשר \"<i>הענין הראשון</i>\" בתק\"ש הוא, שאז \"אנו ממליכין עלינו את הבורא\"."],["21","20","שקאי על <i>תקיעת</i> שופר (אלא שנכלל בזה גם אמירת פסוקי שופרות) – ראה לקמן ע' כד; ע' כו, ובהערות שם."],["22","21","כ\"ה ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380952\" data-slug=\"likkutei-torah\" data-id=\"4001380952\">לקו\"ת</a> דרושים לר\"ה נח, ב. ובכ\"מ. וראה לקמן ע' לה ואילך."],["23","22","בתפלת מוסף דר\"ה, מר\"ה כז, א."],["24","23","כ\"ה בלקו\"ת ובאוה\"ת שבהערה הבאה. ובכ\"מ. וראה לקמן ס\"ו עוד פירוש ב\"תחילת מעשיך\" שקאי על ישראל."],["25","24","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380952\" data-slug=\"likkutei-torah\" data-id=\"4001380952\">לקו\"ת שם נח, ב</a>-ג. אוה\"ת ר\"ה כרך ה ע' ב'כא ב'עט."],["26","25","כ\"ה בהמשך ר\"ה ה'תש\"ג הנ\"ל (ע' 19). ובכ\"מ. ובאגה\"ק סי\"ד (קכ, ב) \"מסתלק לשרשו בכל <i>ערב</i> ר\"ה\"; \"<i>בערב</i> ר\"ה\". אבל לקמן שם (קכא, רע\"א) \"שמסתלק <i>בליל</i> ר\"ה\"."],["27","26","המשך ר\"ה הנ\"ל (ע' 38). ובכ\"מ."],["28","27","סידור (עם דא\"ח) שער התקיעות רמו, ב ואילך."],["29","28","ראה לקו\"ד כרך א ה, סע\"א."],["30","29","ראה מכילתא (ויל\"ש) עה\"פ יתרו כ, ג. תו\"כ ופרש\"י עה\"פ אחרי יח, ב. וראה המשך ר\"ה הנ\"ל פכ\"ו (ע' 69). ולהעיר מברכות יג, א (במשנה): שיקבל עליו עול מלכות שמים תחלה ואח\"כ מקבל עליו עול מצוות."],["31","30","ברמב\"ם הל' תשובה פ\"ג ה\"ד \"אע\"פ שתק\"ש בר\"ה גזירת הכתוב, רמז יש בו כו' וחזרו בתשובה\". אבל ראה לקו\"ש ח\"ד ע' 1145 ואילך (וראה גם לקמן ס\"ט), שגם ע\"י התשובה א\"א להגיע לדרגא זו."],["32","31","סד\"ה שה\"מ ממעמקים עדר\"ת (המשך תער\"ב ח\"א ע' תד)."],["33","32","המשך תער\"ב שם. וראה בארוכה המשך תער\"ב ח\"ב פשפ\"ח ואילך (ע' תשצז ואילך). סה\"מ תרפ\"ז ע' כד ואילך. ובכ\"מ."],["34","33","כ\"ה בהמשך תער\"ב שם פשפ\"ט (ע' תת) לאופן השני."],["35","34","תקו\"ז בהקדמה (\"פתח אליהו\") – יז, א."],["36","35","ראה ד\"ה שה\"מ שבהערה 31 \"שהכוונה בהמשכת המלכות בר\"ה הוא להיות גילוי המלוכה למטה\". וראה לקמן ע' קז."],["37","36","ד\"פעול\" קאי על עשי' (סידור האריז\"ל במקומו. משנת חסידים מסכת ליל ר\"ה פ\"ח מ\"ב. הובאו ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380500\" data-slug=\"likkutei-torah\" data-id=\"4001380500\">לקו\"ת שלח מז, א</a>), ו\"<i>כל</i> פעול\" הוא גם הדומם שבעשי'."],["38","37","ראה לקמן ע' קז. וראה עד\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380958\" data-slug=\"likkutei-torah\" data-id=\"4001380958\">לקו\"ת</a> דרושים לר\"ה נט, ד. עט\"ר שער ר\"ה ספי\"ט."],["39","38","בסד\"ה שה\"מ עדר\"ת דלעיל הערה 31. וראה בהמאמר שם פקצ\"ז (המשך תער\"ב שם ע' תא)."],["40","39","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370064\" data-slug=\"torah-or\" data-id=\"3901370064\">תו\"א וירא יד, סע\"ב</a> ואילך."],["41","40","ראה סידור (עם דא\"ח) שם רמה, סע\"ג ואילך."],["42","41","יבמות סא, רע\"א."],["43","42","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380908\" data-slug=\"likkutei-torah\" data-id=\"4001380908\">לקו\"ת נצבים מז, ב</a>."],["44","43","ויק\"ר רפכ\"ט. ועוד. – נסמן לקמן ע' מא הערה 7."],["45","44","ראה ר\"ן לר\"ה טז, א ד\"זה היום תחלת מעשיך כו'\" \"על יצירת אדם קאמרינן\"."],["46","45","כ\"ה בד\"ה זה בהמשך ר\"ה תש\"ג (ע' 35)."],["47","46","ורמז בחינה זו בשופר הוא המיצר שבו – לא מיצר דעוונות, כ\"א זה שהוא \"עם\" ולא במרחב העצמות ששם מושרש. ולכן זה נוגע בהעצמות (עיין ד\"ה שה\"מ בהמשך ר\"ה הנ\"ל. המשך ר\"ה תרצ\"ה בסופו)."],["48","47","סה\"מ עטר\"ת ע' שב ואילך. ה'ש\"ת ע' 18. ובכ\"מ."],["49","48","ב\"ר פ\"א, ד."],["50","49","ב\"ר פ\"ח, ז. רות רבא פ\"ב, א (ג)."],["51","50","ישעי' ס, כא."],["52","51","ראה יד, א."],["53","52","רבינו בחיי עה\"פ וישב לח, ל. שעהיוה\"א רפ\"ז (פא, ב). ועוד. – נסמן לקמן ע' רלד הערה 86."],["54","53","סה\"מ ה'תש\"ג ע' 6 ואילך."],["55","54","ראה ע\"ח שער כח (שער העיבורים) פ\"ב. שער לט (שער מ\"ן ומ\"ד) דרוש ב. ועוד."],["56","55","סה\"מ שם ע' 15 ואילך."],["57","56","שהיא כעין מלכותא דרקיע (ברכות נח, א), שלכן \"ממלכותא דארעא יש לבאר ולהסביר ענין מלכותא דרקיע\" (המשך ר\"ה הנ\"ל רפ\"ב – ע' 6)."],["58","57","שופטים יז, טו."],["59","58","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081026\" data-slug=\"likkutei-sichot\" data-id=\"1300081026\">לקו\"ש ח\"ח ע' 26</a>."],["60","59","רמב\"ם דלעיל הערה 30."],["61","60","וע\"ד המובא לעיל ס\"ז, שההחלטה על ההמשכה דבריאת העולמות היתה ע\"י ישראל שעלו במחשבה העצמית, כי ע\"י ישראל דוקא נשלמת הכוונה דבריאת העולמות."],["62","61","להעיר מסד\"ה גדול יהי' כבוד הבית הזה ה'תשכ\"ב (לקמן ח\"ד ע' קיט ואילך)."],["63","62","ויש לומר, דבפסוקי שופרות מדובר (גם) בענין ההמשכה בעולם (בנין המלכות) שע\"י תק\"ש דישראל – רצון המוחלט כמו ששייך לרצון הגלוי; ובהמזמור שקודם תק\"ש מדובר בענין רצון המוחלט עצמו, שנמשך רק לישראל. ולכן במזמור זה דוקא מודגש הענין דבחירת הקב\"ה בישראל, ובהמשך לזה – הרחמים שהקב\"ה מרחם על ישראל.\nוע\"פ המבואר לעיל (ס\"ח) דהמשכת רצון המוחלט הוא ע\"י הביטול שמצד עצם הנשמה וענין <i>המצוה</i> דתק\"ש הוא בכדי לעורר הרצון גלוי – אולי יש לומר, שהמשכת הענינים דמזמור זה (יבחר לנו, הפיכת מדה\"ד לרחמים) הם גם ע\"י ההכנה לתק\"ש (לפני קיום המצוה)*, כי גם בההכנה לתק\"ש מתגלה הביטול שמצד עצם הנשמה. וראה לעיל הערה 12 מסידור האריז\"ל, דהפיכת מדה\"ד לרחמים היא ע\"י <i>אמירת המזמור</i>.\n*) <i>ולהעיר מלשון המדרש </i>\"<i>נוטלין את שופריהן ותוקעין</i>\"<i> – דלכאורה הול\"ל </i>\"<i>שתוקעין</i>\",<i> ומה נוגע שנוטלין את שופריהן</i>?<i> וי\"ל</i>,<i> שהכוונה ב</i>\"<i>נוטלין כו' ותוקעין</i>\",<i> שנוטלים השופר בכדי לתקוע</i>,<i> ועי\"ז עצמו מהפכים מדה\"ד לרחמים</i>."]]],[1500360003,"<h3>בס\"ד. יום ב' דראש השנה ה'תשכ\"ח<sup data-n=\"64\">*</sup></h3>\n<b>והי'</b><sup data-n=\"65\">1</sup> ביום ההוא יתקע בשופר גדול ובאו האובדים בארץ אשור והנדחים בארץ מצרים והשתחוו לה' בהר הקדש בירושלים, ומדייק אדמו\"ר הזקן (בהמאמר ד\"ה זה שבלקו\"ת<sup data-n=\"66\">2</sup>) מ\"ש בשופר גדול, מהי המעלה דשופר גדול. גם צריך להבין (כמו שמדייק בהמשך המאמר<sup data-n=\"67\">3</sup>) מ\"ש יתקע סתם ולא נאמר מי הוא התוקע. ואדמו\"ר האמצעי<sup data-n=\"68\">4</sup> מוסיף עוד דיוק בזה שנאמר יתקע, דלשון יתקע (תי\"ו בקמ\"ץ) מורה שיתקע מעצמו. ונקודת הביאור (בהדרושים<sup data-n=\"69\">5</sup>) היא, דההתעוררות שעל ידי שופר סתם הוא רק לאלה שהם בקירוב קצת, ובכדי לעורר את האובדים בארץ אשור והנדחים בארץ מצרים שגם הם יתעוררו לבוא לירושלים ולהשתחוות לה', הוא על ידי שופר גדול.\n<b>ובכדי</b> לבאר העילוי דשופר גדול שיהי' לע\"ל, מקדים בהמאמר<sup data-n=\"70\">6</sup> ביאור ענין שופר דראש השנה (עכשיו), דעל ידי שישראל תוקעין בשופר, שהיא הצעקה דפנימיות הלב שלמעלה מהשכל, עי\"ז נמשך פנימיות הלב דלמעלה כביכול, רצון העליון שלמעלה מהחכמה. ועל זה נאמר<sup data-n=\"71\">7</sup> ואד' הוי' בשופר יתקע, דכמו שתקיעת שופר דהאדם היא הצעקה דפנימיות הלב, עד\"ז הוא למעלה, דענין תקיעת שופר הוא המשכת וגילוי הפנימיות. והחילוק בין שופר סתם לשופר גדול הוא, דשופר סתם הוא המשכת וגילוי הפנימיות דאלקות שלמעלה מעולמות אבל שייך לעולמות, סובב כל עלמין, ושופר גדול הוא המשכת וגילוי הפנימיות דאלקות שלמעלה משייכות לעולמות, למעלה גם מסובב. וזהו שבשופר סתם כתיב ואד' הוי' בשופר יתקע, דאד' הוי' הם שמות, אלא ששמות אלה (אד' הוי' בניקוד אלקים) הם נעלים ביותר<sup data-n=\"72\">8</sup>, ובשופר גדול כתיב יתקע סתם ולא נאמר מי הוא התוקע, כי תקיעה זו היא המשכה וגילוי מבחינת סתימא דכל סתימין, שלמעלה משמות.\nב) <b>ובכדי</b> לבאר העילוי דשופר גדול עוד יותר, מביא הצ\"צ<sup data-n=\"73\">9</sup> (בהביאור שלו<sup data-n=\"74\">10</sup> להמאמר ד\"ה והי' ביום ההוא יתקע בשופר גדול שבלקו\"ת) מ\"שבלקו\"ת בד\"ה להבין המשנה<sup data-n=\"75\">11</sup> יו\"ט של ראש השנה שחל להיות בשבת במקדש היו תוקעין אבל לא במדינה<sup data-n=\"76\">12</sup>, דזה שבראש השנה צריך לתקוע בשופר הוא בכדי לעורר עי\"ז למעלה התענוג בבריאת העולמות, וכיון שבשבת מצד עצמו ישנו התענוג, לכן בראש השנה שחל להיות בשבת אין צריך [כ\"כ<sup data-n=\"77\">13</sup>] לתקיעת שופר. וזה שבמקדש היו תוקעין גם בראש השנה שחל בשבת הוא, כי בתענוג כמה מדריגות, ודרגת התענוג שממשיכים על ידי תקיעת שופר במקדש היא נעלית יותר מדרגת התענוג דשבת. שהתענוג דשבת הוא מבחינת חיצוניות הכתר, שרש הנאצלים, והתענוג שהמשיכו על ידי תקיעת שופר במקדש הוא מבחינת פנימיות הכתר, בחינה תחתונה שבמאציל<sup data-n=\"78\">14</sup>. ומוסיף הצ\"צ, שגם בהתענוג דבחינה תחתונה שבמאציל, ישנם כמה מדריגות. והתענוג שנמשך בבית ראשון על ידי תקיעת שופר הוא נעלה יותר מהתענוג שנמשך בבית שני. ובבית ראשון עצמו, השופר דיוהכ\"פ דשנת היובל [שמצות יובל היתה רק בבית ראשון<sup data-n=\"79\">15</sup>] הוא נעלה יותר מהשופר דראש השנה. ואעפ\"כ גם בשופר דיובל נאמר<sup data-n=\"80\">16</sup> והעברת שופר תרועה, שופר סתם<sup data-n=\"81\">17</sup>. ומזה מובן, ששופר גדול הוא למעלה גם מהגילוי שנמשך על ידי שופר דיובל.\nג) <b>ולהוסיף</b><b>,</b> דשופר גדול שיהי' לע\"ל הוא למעלה יותר גם משופר דמתן תורה, שהרי גם בשופר דמ\"ת נאמר<sup data-n=\"82\">18</sup> ויהי קול השופר, שופר סתם. דזה שממשיך בכתוב ויהי קול השופר הולך וחזק מאד הוא <i>שקול</i> השופר היה חזק מאד, קול גדול<sup data-n=\"83\">19</sup>, אבל בנוגע השופר שממנו נמשך הקול<sup data-n=\"84\">20</sup> לא נאמר שהי' שופר גדול, ומזה מובן דשופר גדול שיהי' לעתיד הוא למעלה גם מהשופר דמתן תורה. וכדאיתא בפרקי דר\"א<sup data-n=\"85\">21</sup> בענין ב' קרניו של אילו של יצחק, דקרן של שמאל נשמע קולו על הר סיני שנאמר ויהי קול השופר, וקרן של ימין שהוא גדול מהשמאל עתיד לתקוע בו לע\"ל, שנאמר והי' ביום ההוא יתקע בשופר גדול. והטעם על זה שהשופר דמתן תורה הי' שופר סתם והשופר דלע\"ל יהי' שופר גדול, מבאר אדמו\"ר האמצעי<sup data-n=\"86\">22</sup>, כיבמתן תורה היו כולם בקירוב לאלקות (גם לפני קול השופר), ולכן גם ע\"י שופר סתם הי' אפשר לעוררם. אבל בכדי לעורר את האובדים והנדחים הוא דוקא ע\"י שופר גדול. ועפ\"ז מבאר מ\"ש יתקע בשופר גדול, דלשון יתקע (תי\"ו בקמ\"ץ) מורה שיתקע מעצמו, כי הגילוי דבחינת שופר גדול לעורר את האובדים והנדחים יהי' מעצמו, בלי אתערותא דלתתא כלל<sup data-n=\"87\">23</sup>.\nד) <b>והנה</b> מבואר בתחלת המאמר<sup data-n=\"88\">24</sup> (לאחרי הדיוק בהפסוק והי' ביום ההוא יתקע בשופר גדול) דזה שאומרים<sup data-n=\"89\">25</sup> בראש השנה זה היום תחלת מעשיך הוא כי בכל ראש השנה הוא התהוות כל העולמות מחדש כמו שהי' בפעם הראשונה. ומ\"ש זכרון ליום ראשון (שראש השנה הוא רק זכרון ליום ראשון) הוא, כי בתחלת הבריאה, המשכת הרצון והתענוג בבריאת העולמות היתה מצד עצמו, כי חפץ חסד הוא<sup data-n=\"90\">26</sup>, ועכשיו באתערותא דלתתא תליא מילתא. ומבאר<sup data-n=\"91\">27</sup> שהעבודה (אתערותא דלתתא) שעל ידה ממשיכים הרצון והתענוג בבריאת העולמות היא כמאמר רז\"ל<sup data-n=\"92\">28</sup> אמרו לפני מלכיות כו' זכרונות כו' ובמה בשופר. והטעם על זה שההמשכה עכשיו היא על ידי עבודת האדם הוא<sup data-n=\"93\">29</sup> כי ע\"י שההמשכה (עכשיו) היא ע\"י עבודתם של ישראל, דשורש ישראל הוא בהעצמות, הרצון והתענוג שנמשכים עכשיו הם נעלים יותר מהרצון והתענוג שנמשכו מצד עצמם (בתחלת הבריאה). ועפ\"ז צריך להבין, שהשופר דלמעלה (פנימיות רצון העליון<sup data-n=\"94\">30</sup>) שנמשך עכשיו, שהוא שופר סתם, המשכתו היא ע\"י עבודת האדם, והשופר דלע\"ל שהוא שופר גדול, יומשך מעצמו בלי אתערותא דלתתא כלל.\n<b>והנה</b> מבאר בהמאמר<sup data-n=\"95\">31</sup> דזה שלע\"ל יתקע בשופר גדול הוא ע\"ד שופר דראש השנה עכשיו, כי מצות אינן בטילות לע\"ל [אלא שאז יהי' השופר במדריגה נעלית יותר, שופר גדול]. ויש לומר, שהמקור לזה (שיתקע בשופר גדול שייך לתקיעת שופר דראש השנה) הוא מה דאיתא בגמרא<sup data-n=\"96\">32</sup>, דטעמו של המ\"ד בתשרי עתידין להגאל הוא אתיא שופר שופר, כתיב<sup data-n=\"97\">33</sup> הכא תקעו בחודש שופר וכתיב התם ביום ההוא יתקע בשופר גדול. ועפ\"ז צריך להבין עוד יותר מה שהובא לעיל מהדרושים, דפירוש יתקע (תי\"ו בקמ\"ץ) בשופר גדול הוא יתקע בעצמו בלי אתערותא דלתתא כלל, הרי מענינים העקריים דראש השנה הוא עבודת האדם [וכמבואר בכ\"מ<sup data-n=\"98\">34</sup> דהטעם על זהשראש השנה הוא באחד בתשרי, אף שבכ\"ה באלול נברא העולם<sup data-n=\"99\">35</sup> ואחד בתשרי הוא יום הששי למעשה בראשית, הוא, כי ביום זה נברא האדם], וכיון דענין יתקע בשופר גדול הוא ע\"ד תקעו בחודש שופר דראש השנה (תשרי<sup data-n=\"100\">36</sup>), הי' ראוי לכאורה שהמשכת ענין זה תהי' על ידי עבודת האדם, ואעפ\"כ מבואר בהדרושים, דפירוש יתקע הוא יתקע מעצמו בלי אתערותא דלתתא <i>כלל</i>. גם צריך להבין, דכל הענינים שבתורה (מלשון הוראה), הם הוראה בעבודת האדם, וכיון דזה שיתקע בשופר גדול יהי' מלמעלה בלי אתערותא דלתתא, מהי ההוראה מזה בעבודת האדם.\nה) <b>ויובן</b> זה ע\"פ המבואר בדרושי אדמו\"ר מהר\"ש<sup data-n=\"101\">37</sup>, דזה ששופר צדו אחד קצר וצדו השני רחב הוא על שם מן המיצר קראתי י-ה ענני במרחב י-ה<sup data-n=\"102\">38</sup>. דכמו שקול השופר, ע\"י שיוצא מן המיצר מצדו הקצר עי\"ז דוקא הוא במרחב ובהתפשטות בצדו הרחב, כמו\"כ הוא ברוחניות, שע\"י הצעקה מן המיצר והדוחק, מן המיצר קראתי י-ה, עי\"ז דוקא ענני במרחב י-ה. ומבאר שם, דזהו שאמרו רז\"ל<sup data-n=\"103\">39</sup> כל שנה שרשה בתחלתה מתעשרת בסופה, דרשה בתחלתה [שישראל עושין עצמן רשין בראש השנה לדבר תחנונים ותפלה כענין שנאמר<sup data-n=\"104\">40</sup> תחנונים ידבר רש<sup data-n=\"105\">41</sup>] היא הקריאה מן המיצר, ועי\"ז מתעשרת – ענני במרחב. וכמבואר במאמר הנ\"ל של אדמו\"ר מהר\"ש<sup data-n=\"106\">42</sup> המעלה דתפלת עני על תפלת עשיר. ויש לומר, שהמעלה בתפלת עני היא בשני ענינים. בהתפלה עצמה, כתורת הבעל שם טוב<sup data-n=\"107\">43</sup> על הפסוק<sup data-n=\"108\">44</sup> תפלה לעני כי יעטוף ולפני הוי' ישפוך שיחו, דתפלת העני היא שלפני הוי' ישפוך שיחו, וגם שתפלת העני מתקבלת יותר. ועוד ענין, שגם התענוג דהאדם מההשפעה שנמשכה לו ע\"י תפלתו, התענוג של העני הוא תענוג גדול יותר, כתורת הה\"מ שהובאה במאמר הנ\"ל<sup data-n=\"109\">45</sup>.\n<b>ועפ\"ז</b> יש לבאר השייכות דיתקע בשופר גדול לראש השנה, כי זה שלע\"ל יתקע בשופר גדול בכדי לעורר את האובדים והנדחים, הוא, כי האובדים והנדחים הם בתכלית המיצר, וזה מעורר וממשיך התקיעה דשופר גדול (ההמשכה מבחינת סתימא דכל סתימין), תכלית המרחב. וזוהי השייכות דיתקע בשופר גדול לראשהשנה (תקעו בחודש שופר), כי ענין ראש השנה הוא דע\"י שהיא רשה בתחלתה (מרשית השנה, רשית חסר<sup data-n=\"110\">46</sup>), היא מתעשרת.\nו) <b>ויש</b> לומר, דעל ידי התקיעה בשופר גדול בכדי לעורר את האובדים בארץ אשור והנדחים בארץ מצרים נעשה עילוי גם בארץ אשור וארץ מצרים. כי הכוונה בזה שישראל גלו לארץ אשור ולארץ מצרים, ועד שעי\"ז נעשו אובדים ונדחים, היא, בכדי שע\"י מיצר הגלות, ובפרט מיצר הגלות של אלה שע\"י הגלות נעשו במצב דאובדים ונדחים, יתעורר ויומשך השופר גדול, שעי\"ז יתעלו ישראל למדריגה נעלית יותר מהמדריגה שהיו קודם שגלו. ולכן, כשיתקע בשופר גדול ותושלם הכוונה שבשבילה נבראה ארץ אשור וארץ מצרים, תהי' עלי' גם בהם.\n<b>ועפ\"ז</b> יש להוסיף עוד ענין בהשייכות דיתקע בשופר גדול לראש השנה, כי בראש השנה שני ענינים. שהוא יום בריאת האדם, ושעי\"ז נעשה עילוי גם בכללות הבריאה (כדלקמן). והענין הוא כמ\"ש אדמו\"ר (מהורש\"ב) נ\"ע בהמאמר ד\"ה זה היום תחלת מעשיך זכרון ליום ראשון<sup data-n=\"111\">47</sup>, דצריך להבין, הרי ראש השנה (זה היום) הוא באחד בתשרי שהוא יום הששי למעשה בראשית, ואיך הוא זכרון ליום ראשון. ומבאר<sup data-n=\"112\">48</sup>, דהרצון לבריאת העולם הוא חיצוניות הרצון, ופנימיות הרצון הוא בישראל. ושני ענינים אלה בזמני השנה הם בכ\"ה אלול ובראש השנה. דבכ\"ה אלול שבו נברא העולם הוא חיצוניות הרצון, ובראש השנה (אחד בתשרי) שבו נברא האדם, אתם קרויין אדם<sup data-n=\"113\">49</sup>, הוא פנימיות הרצון. וזהו זה היום תחלת מעשיך זכרון ליום ראשון, דבראש השנה שני ענינים<sup data-n=\"114\">50</sup>. ענין העיקרי דראש השנה הוא שהוא תחלת מעשיך, המשכת עצמות אוא\"ס (שלמעלה מרצון לעולמות) ע\"י עבודת האדם, ועוד ענין בראש השנה שהוא זכרון ליום ראשון, שההמשכה דעצמות אוא\"ס נמשכת גם בהרצון לבריאת העולמות, ועי\"ז בהעולמות<sup data-n=\"115\">51</sup>. ועפ\"ז, השייכות דיתקע בשופר גדול לראש השנה היא בשני הענינים שבו, המשכת הגילוי דשופר גדול לישראל שייכת לתחילת מעשיך, והעילוי שיהי' עי\"ז בארץ אשור וארץ מצרים שייך לזכרון ליום ראשון.\nז) <b>והנה</b> ע\"פ המובא לעיל (ס\"ה) מהדרוש דאדמו\"ר מהר\"ש שהמיצר דשופר הו\"ע שנה שרשה בתחלתה, דענין רשה בתחלתה הוא זה שישראל <i>עושין</i> עצמןרשין בראש השנה, מובן, דענין המיצר שעל ידו הוא המשכת המרחב הוא גם כשהמיצר הוא מצד הביטול, שעבודתו היא בשלימות אלא שמצד הביטול שלו הוא מרגיש שהוא נמצא במיצר, גם ע\"י מיצר זה הוא המשכת המרחב. ועד\"ז הוא בנוגע הגילוי דשופר גדול שמתעורר ונמשך ע\"י המיצר דהאובדים והנדחים, דגם כשעבודתו היא בשלימות אלא שמתבונן שלגבי הרוממות דאוא\"ס גם העבודה האמיתית לחטא יחשב<sup data-n=\"116\">52</sup> ולכן הוא מרגיש את עצמו לאובד ונדח, שעי\"ז נתעורר ונמשך הגילוי דשופר גדול. ויש לומר שגם אז (כשהמשכת הגילוי דשופר גדול היא ע\"י הביטול שלו) שייך לשון יתקע (תי\"ו בקמ\"ץ), יתקע מעצמו, כי כשעושה עצמו עני ורש, דענין העני הוא שאין לו משל עצמו כלום והוא רק מקבל זה שנותנים לו בדרך צדקה, הוא מכיר ומרגיש דזה שע\"י עבודתו נמשך הגילוי הוא לא מצד העילוי שלו (שבכחו להמשיך), אלא מצד חסד הקב\"ה<sup data-n=\"117\">53</sup>, יתקע מעצמו, וכאילו שההמשכה היא בלי אתערותא דלתתא כלל.\n<b>ולהוסיף</b><b>,</b> דע\"פ מ\"ש כ\"ק מו\"ח אדמו\"ר (בהמאמר ד\"ה והי' ביום ההוא יתקע בשופר גדול<sup data-n=\"118\">54</sup>) שהשופר גדול יעורר את נקודת היהדות שבכל אחד מישראל, מובן, דזה שכל ישראל (גם וכולל האובדים והנדחים) ירצו לצאת מהגלות וללכת לירושלים ולהשתחוות לה' הוא שע\"י הגילוי דשופר גדול יתעורר הרצון האמיתי<sup data-n=\"119\">55</sup> <i>דישראל</i>. דזהו החילוק שבין הגאולה דיציאת מצרים וגאולה העתידה, שביציאת מצרים, חפצם של ישראל לצאת מטומאת מצרים ולדבקה בו ית'<sup data-n=\"120\">56</sup> היתה מצד הגילוי דלמעלה<sup data-n=\"121\">57</sup>, משכני<sup data-n=\"122\">58</sup>, ובגאולה העתידה, הרצון לצאת מהגלות ולבוא לירושלים יהי' הרצון דישראל, והגילוי דלמעלה (שופר גדול) הוא רק סיבה שעל ידו יתגלה הרצון דישראל. והעבודה שלהם תהי' מצד עצמם – המעלה דראש השנה, עבודת <i>האדם</i><sup data-n=\"123\">59</sup>. אלא שבהאובדים והנדחים כפשוטם, המעלה דעבודת האדם היא <i>לאחרי</i> הגילוי דשופר גדול שעל ידו מתעורר רצונו האמיתי דהאדם, אבל <i>המשכת</i> הגילוי דשופר גדול הוא מצד מלמעלה. ועוד אופן ביתקע בשופר גדול, שגם המשכת הגילוי דשופר גדול היא ע\"י עבודה, כנ\"ל.\nח) <b>וזהו</b> והי' ביום ההוא יתקע בשופר גדול, דההוראה מזה שביום ההוא יתקע בשופר גדול, יתקע מעצמו, היא, שבסוף זמן הגלות שנשארו רק כמה רגעים שקודם ליום ההוא שיתקע בשופר גדול [ויתירה מזה שבנוגע לכמה ענינים התחיל כבר הענין דיתקע בשופר גדול, כמובן ממאמר הנ\"ל דכ\"ק מו\"ח אדמו\"ר<sup data-n=\"124\">60</sup>,ובפרט שמעת כתיבת המאמר עד עכשיו כבר עברו כו\"כ שנים, ועאכו\"כ בזמן האחרון שראו במוחש שכו\"כ שהיו תחלה במצב של אובדים ונדחים רח\"ל התעוררו בתשובה ע\"י התקיעה בשופר גדול<sup data-n=\"125\">61</sup>] צריכה להיות העבודה בביטול, ההכרה והרגשה שכל הענינים שנפעלו ע\"י עבודתו, הן בנוגע לעצמו והן בנוגע לזולתו, היא לא מצד המעלות שלו אלא מצד הנתינת כח מלמעלה. ולהעיר, שהרגש זה אינו פועל חלישות בעבודתו, ואדרבה, ע\"י הרגש זה, עבודתו היא ביתר שאת. דכשהעבודה שלו קשורה עם מציאותו, העבודה היא במדידה והגבלה. וגם כשהעבודה שלו היא באופן דבכל מאודך, הרי היא מאדך, מאד שלך<sup data-n=\"126\">62</sup>, וע\"י ההרגש שהענינים שנעשים ע\"י עבודתו הם לא מצד הכחות שיש לו אלא מצד האלקות, עי\"ז הוא יוצא מהמציאות וההגבלות שלו, והעבודה שלו היא למעלה ממדידה והגבלה<sup data-n=\"127\">63</sup>.\nט) <b>והנה</b> מבואר בהמאמר ד\"ה והי' ביום ההוא יתקע בשופר גדול<sup data-n=\"128\">64</sup> בענין שופר דראש השנה, דהגם שעיקר ההמשכה היא ע\"י הצעקה דפנימיות הלב מ\"מ צ\"ל התקיעה בשופר גשמי דוקא, כי עשי' היא לעילא, וגם בכדי שהגילוי דפנימיות רצון העליון [בחינת שופר דלמעלה<sup data-n=\"129\">65</sup>] יומשך למטה בגשמיות. ומזה מובן, דכמו\"כ הוא בנוגע להתקיעה דשופר גדול ביום ההוא, שאין מספיק הענינים שהיו עד עכשיו, והתקיעה בשופר גדול צריכה להיות באופן שכל ישראל, גם וכולל האובדים והנדחים, יבואו וישתחוו לה' בהר הקודש בירושלים, בירושלים כפשוטה, ע\"י משיח צדקנו שיוליכנו קוממיות לארצנו, בעגלא דידן בקרוב ממש.\n**********",[["64","*","יצא לאור ב<b>קונטרס ראש השנה – תשנ\"ב</b>, \"לקראת ראש השנה . . <i>כ\"ה אלול</i>,<i> שנת ה'תנש\"א</i>\"."],["65","1","ישעי' כז, יג. והוא מפסוקי שופרות דר\"ה."],["66","2","דרושים לר\"ה נח, א ואילך. וראה גם מאמר זה (בשינויים קלים) באוה\"ת דברים כרך ה' דרושי ר\"ה ע' ב'עז ואילך. וראה ביאור למאמר זה באוה\"ת ר\"ה ע' א'תה ואילך. שם א'תח ואילך."],["67","3","נט, ד."],["68","4","עטרת ראש שער ר\"ה פכ\"ב."],["69","5","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380959\" data-slug=\"likkutei-torah\" data-id=\"4001380959\">לקו\"ת שם ס, א</a>. עט\"ר שם."],["70","6","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380954\" data-slug=\"likkutei-torah\" data-id=\"4001380954\">לקו\"ת שם נח, ד</a> ואילך. עט\"ר שם פי\"ח ואילך."],["71","7","זכרי' ט, יד. וגם פסוק זה הוא מפסוקי שופרות דר\"ה."],["72","8","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380925\" data-slug=\"likkutei-torah\" data-id=\"4001380925\">לקו\"ת נצבים נא, ג</a>."],["73","9","שיום ההולדת שלו הוא בערב ר\"ה – נולד כ\"ט אלול תקמ\"ט (\"היום יום\" כט אלול. ועוד)."],["74","10","ר\"ה ע' א' תה ואילך. וראה שם ע' א'תח."],["75","11","ר\"ה רפ\"ד (כט, ב)."],["76","12","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380943\" data-slug=\"likkutei-torah\" data-id=\"4001380943\">לקו\"ת דרושי ר\"ה נו, א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380947\" data-slug=\"likkutei-torah\" data-id=\"4001380947\">וראה שם נז, א</a> ואילך."],["77","13","בלקו\"ת שם (נז, ריש ע\"ב) שבשבת \"אינו נצרך לשופר\". אבל באוה\"ת ר\"ה ע' א'תלח \"בשבת אין צריך <i>כ\"כ</i> לתקיעת שופר\". ולהעיר, דעפ\"ז מובן זה שגם בר\"ה שחל בשבת ישנה המצוה דתק\"ש, אלא שאינה בתוקף כ\"כ כבר\"ה שחל בימי השבוע (לפי שבשבת אין צריך כ\"כ לתק\"ש), ולכן היא נדחית מפני החשש שמא יעבירנו ד' אמות ברה\"ר."],["78","14","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380950\" data-slug=\"likkutei-torah\" data-id=\"4001380950\">לקו\"ת שם נז, ד</a>."],["79","15","ראה ערכין לב, ב. רמב\"ם הל' שמיטה ויובל פ\"י ה\"ח."],["80","16","בהר כה, כט."],["81","17","ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380961\" data-slug=\"likkutei-torah\" data-id=\"4001380961\">לקו\"ת ר\"ה ס, רע\"ג</a> \"תקיעות דר\"ה זהו בחינת שופר סתם . . אבל ביוהכ\"פ . . התגלות זו בשופר גדול\". ומבאר בסיום הענין שם \"הוא רק הארה מבחי' שופר גדול\"."],["82","18","יתרו יט, יט."],["83","19","בעט\"ר שער ר\"ה פכ\"א (כב, ב) מובא לשון הפסוק (ואתחנן ה, יט) קול גדול ולא יסף. וראה זח\"ב פא, ב ד\"קול גדול ולא יסף\" קאי על קול השופר."],["84","20","ויש לומר, דקול גדול הוא הגילוי ושופר הוא העצם שממנו נמשך הגילוי, כמ\"ש בזהר שם \"אתרא דקלא נפיק מיני' אקרי שופר\". וזהו שלע\"ל יהי' <i>שופר</i> גדול, שאז יהי' בגילוי העצם שלמעלה מגילוי."],["85","21","פל\"א."],["86","22","עט\"ר שם פכ\"ב."],["87","23","כ\"ה הלשון (בלי אתעדל\"ת <i>כלל</i>) בעט\"ר שם בתחלת הפרק ובסופו."],["88","24","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380951\" data-slug=\"likkutei-torah\" data-id=\"4001380951\">לקו\"ת ר\"ה נח, א</a>-ב. וראה גם עט\"ר שם פ\"י (ט, ב)."],["89","25","בתפלת מוסף דר\"ה."],["90","26","מיכה ז, יח."],["91","27","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380952\" data-slug=\"likkutei-torah\" data-id=\"4001380952\">לקו\"ת שם נח, ב</a> ואילך. עט\"ר שם פי\"א ואילך."],["92","28","ר\"ה טז, א. לד, ב."],["93","29","ראה עט\"ר שם פי\"ב (יב, א). וראה לקמן ע' יז ואילך. ע' כט ואילך. ע' מא ואילך. <i>וש\"נ</i>."],["94","30","ראה לעיל ס\"א."],["95","31","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380956\" data-slug=\"likkutei-torah\" data-id=\"4001380956\">לקו\"ת שם נט, סע\"ב</a> ואילך."],["96","32","ר\"ה יא, ב."],["97","33","תהלים פא, ד."],["98","34","ראה לקמן ע' מא ואילך ובהנסמן שם."],["99","35","ויק\"ר רפכ\"ט. ובכ\"מ – נסמן לקמן שם הערה 7."],["100","36","ראה סה\"מ תרנ\"ד ע' קלח (ועד\"ז באוה\"ת בא ע' רס) דהטעם של המ\"ד בתשרי עתידין להגאל כי תשרי הוא \"זמן התעוררות תשובה מלמטה\". וצריך ביאור, שהילפותא שבתשרי עתידין להגאל (לפי שתשרי הוא מלמטה) הוא מהכתוב יתקע בשופר גדול (אתיא שופר שופר) דפירוש יתקע הוא יתקע מעצמו."],["101","37","ראה סה\"מ תרכ\"ז ע' תא. ושם ע' שצח."],["102","38","תהלים קיח, ה. וראה זח\"ב ס, רע\"א."],["103","39","ר\"ה טז, ב."],["104","40","משלי יח, כג."],["105","41","פרש\"י ר\"ה שם."],["106","42","סה\"מ תרכ\"ז ע' שצט ואילך."],["107","43","כתר שם טוב (הוצאת קה\"ת) סי' צו (יג, ג)."],["108","44","תהלים קב, א."],["109","45","סה\"מ שם ס\"ע תו ואילך."],["110","46","עקב יא, יב. וראה ר\"ה שם."],["111","47","דשנת תרע\"ג (נדפס בהמשך תער\"ב ח\"א ע' קכז) ודשנת תרע\"ו (נדפס בהמשך הנ\"ל ח\"ב ע' א'קמ)."],["112","48","המשך תער\"ב ח\"א ע' קלד. ועד\"ז שם ח\"ב ע' א'קמו."],["113","49","יבמות סא, א."],["114","50","ראה גם ד\"ה יבחר לנו דיום ב' דראש-השנה תשכ\"ג סעיף ו (לעיל ע' ה). אלא שהביאור שם הוא ד\"תחלת מעשיך\" קאי על <i>האדם</i> ו\"זכרון ליום ראשון\" קאי על כללות הבריאה. ובהמשך תער\"ב שם, שגם \"תחלת מעשיך\" קאי על ההמשכה <i>בעולם</i> (המשכת הרצון <i>למלוכה</i>), ו\"זכרון ליום ראשון\" הוא \"דע\"י הרצון למלוכה נמשך הרצון לעולמות ושיהי' בבחינת גילוי אור\". וראה הערה הבאה."],["115","51","דהעולמות כמו שהם מצד פנימיות הרצון, ענינם הוא לא <i>עולמות</i> אלא זה שעל ידם נשלמת הכוונה (שלמעלה מרצון לעולמות). וזה שענינם הוא עולמות הוא ע\"י שהתהוותם היא מהרצון לברוא עולמות (מצד כי חפץ חסד הוא), וע\"י שהרצון לעולמות נמשך מפנימיות הרצון (ראה הערה הקודמת), ההמשכה דאוא\"ס היא (גם) בהעולמות שענינם הוא עולם."],["116","52","סה\"מ תרנ\"ט ע' סד. וראה גם סה\"מ תרנ\"א ע' עה ואילך. ע' ריב ואילך."],["117","53","וזה שההמשכה היא ע\"י עבודה, גם זה הוא חסד הקב\"ה שההמשכה לא תהי' נהמא דכסופא."],["118","54","נדפס ב\"הקריאה והקדושה\" תשרי תש\"ג ובסה\"מ אידיש ע' 78 ואילך."],["119","55","ראה רמב\"ם הל' גירושין ספ\"ב."],["120","56","לשון אדמו\"ר הזקן ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310036\" data-slug=\"tanya\" data-id=\"3401310036\">תניא פל\"א (מ, ב</a>)."],["121","57","ולכן יציאתם ממצרים היתה באופן דכי ברח העם (תניא שם. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380086\" data-slug=\"likkutei-torah\" data-id=\"4001380086\">לקו\"ת ויקרא ג, א</a>)."],["122","58","שה\"ש א, ד. וראה אוה\"ת שה\"ש עה\"פ (ע' נט. עה). ובכ\"מ."],["123","59","ועפ\"ז מתורץ הדיוק שבהערה 36."],["124","60","ראה בארוכה שיחת ש\"פ בראשית (ב) שנה זו (תשכ\"ח)."],["125","61","להעיר, שמאמר זה נאמר לאחרי ההתעוררות שלאחרי מלחמת ששת הימים (<i>המו\"ל</i>)."],["126","62","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370180\" data-slug=\"torah-or\" data-id=\"3901370180\">תו\"א מקץ לט, ד</a>. ספהמ\"צ להצ\"צ קכג, ב. ובכ\"מ."],["127","63","ראה עד\"ז לקמן ח\"ג ע' ק."],["128","64","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380958\" data-slug=\"likkutei-torah\" data-id=\"4001380958\">לקו\"ת ר\"ה נט, ד</a>."],["129","65","ראה לעיל ס\"א."]]],[1500360004,"<h3>בס\"ד. כ\"ט אלול ה'תשל\"ב, ליל ערב ראש השנה ה'תשל\"ג<sup data-n=\"130\">*</sup></h3>\n<b>יום</b> טוב של ראש השנה שחל להיות בשבת במקדש היו תוקעין אבל לא במדינה<sup data-n=\"131\">1</sup>, ומפרש בגמרא<sup data-n=\"132\">2</sup> דרבנן הוא דגזור בי', דהכל חייבין בתקיעת שופר ואין הכל בקיאין בתקיעת שופר, גזירה שמא יטלנו בידו וילך אצל הבקי ללמוד ויעבירנו ד' אמות ברשות הרבים. וידוע הדיוק בזה<sup data-n=\"133\">3</sup>, מה ראו חז\"ל לדחות מ\"ע דאורייתא, ובפרט מצות שופר שהיא מצוה רמה ונישאה מאד<sup data-n=\"134\">4</sup>, משום גזירה בעלמא [ובפרט עכשיו, שאין מצוי שיהי' רה\"ר מה\"ת<sup data-n=\"135\">5</sup>, והגזירה שמא יעבירנו הוא רק שלא יבוא לאיסור דרבנן]. וגם<sup data-n=\"136\">6</sup>, הרי החשש הוא להדיוטים וקלי הדעת<sup data-n=\"137\">7</sup>, ואיך מנעו בשביל זה המצוה מכמה צדיקים גדולים וטובים. וידוע הביאור בזה<sup data-n=\"138\">8</sup>, דזה שבראש השנה צריך לתקוע בשופר הוא בכדי לעורר עי\"ז למעלה התענוג בבריאת העולמות, וכיון שבשבת מצד עצמו ישנו התענוג, לכן, בראש השנה שחל להיות בשבת המצוה דתקיעת שופר אינה בתוקף כ\"כ (עם כל השטורעם) כמו בראש השנה שחל בימות השבוע<sup data-n=\"139\">9</sup>, ולכן היא נדחית מפני החשש שמא יעבירנו ד' אמות ברשות הרבים. וזה שבמקדש היו תוקעין גם בראש השנה שחל בשבת, הוא, כי בתענוג כמה מדריגות, ודרגת התענוג שהמשיכו ע\"י תקיעת שופר במקדש היא נעלית יותר מדרגת התענוג דשבת.\nב) <b>וצריך</b> להבין, הרי ידוע<sup data-n=\"140\">10</sup> דזה שבראש השנה צריך לעורר התענוג ע\"י עבודת האדם (תקיעת שופר), אף שבתחלת הבריאה היתה ההמשכה מעצמה, הוא, כי ע\"י שהתעוררות התענוג דלמעלה (עכשיו) היא ע\"י עבודתם של ישראל,שהשרש דישראל הוא בהעצמות, התענוג שנמשך עכשיו הוא נעלה יותר מהתענוג שנמשך מצד עצמו (בתחלת הבריאה). ועפ\"ז, בראש השנה שחל להיות בשבת, שהתענוג הוא מצד הזמן דשבת (שבת מיקדשא וקיימא<sup data-n=\"141\">11</sup>), חסר לכאורה מעלת התענוג שמתעורר ע\"י עבודת האדם. ואף שגם בראש השנה שחל להיות בשבת ישנה העבודה דאמירת פסוקי שופרות, הרי אמירת הפסוקים היא בכדי שההמשכה תהי' בגילוי. וכמבואר בהמשך יום טוב של ראש השנה תרס\"ו<sup data-n=\"142\">12</sup>, דההמשכה שע\"י המצוות אינה בגילוי כ\"כ, והגילוי הוא ע\"י התורה, תורה אור<sup data-n=\"143\">13</sup>. ולכן, בכדי שהמשכת התענוג שע\"י קיום מצות תקיעת שופר תהי' בגילוי הוא ע\"י אמירת פסוקי שופרות. וזהו הטעם שגם בראש השנה שחל להיות בשבת אומרים פסוקי שופרות, אף שהמשכת התענוג אז הוא מצד עצמו, כי ההמשכה שמצד השבת עצמו היא למעלה, ובכדי שיהי' הגילוי למטה הוא ע\"י אמירת פסוקי שופרות. וכיון שע\"י אמירת הפסוקים הוא רק גילוי ההמשכה, וההמשכה עצמה היא מצד השבת עצמו, הרי בראש השנה שחל להיות בשבת חסר לכאורה העילוי שנעשה ע\"י עבודה.\nג) <b>ויובן</b> זה בהקדים מה שארז\"ל<sup data-n=\"144\">14</sup> משביעין אותו תהי צדיק כו', ואמר כ\"ק מו\"ח אדמו\"ר<sup data-n=\"145\">15</sup> בשם הצ\"צ, אשר בראש השנה הראשונה לחייו (שנת תק\"ן<sup data-n=\"146\">16</sup>) אמר אדמו\"ר הזקן דרוש משביעין אותו תהי צדיק כו', והוא השלשת פרקים הראשונים של ספר התניא<sup data-n=\"147\">17</sup>. ויש לבאר השייכות דענין משביעין אותו לראש השנה ע\"פ המבואר בלקו\"ת<sup data-n=\"148\">18</sup>, דזה שכל אחד מישראל נק' אדם (אתם קרויין אדם<sup data-n=\"149\">19</sup>), הוא, לפי שבנשמת כל אחד מישראל יש חלק מנשמת אדם הראשון. ומזה מובן, דבראש השנה (יום ברוא אדם הראשון) שאז מתחדש (בכל שנה) הענין דהמשכת נשמת אדם הראשון בגופו (ויפח<sup data-n=\"150\">20</sup> באפיו נשמת חיים)<sup data-n=\"151\">21</sup>, הרי זה גם יום ההולדת של כל אחד מישראל. וי\"ל שזהו הקשר דמשביעין אותו לראש השנה.\n<b>ויש</b> לקשר זה עם פירוש המדרש<sup data-n=\"152\">22</sup> עה\"פ<sup data-n=\"153\">23</sup> בחודש השביעי שהוא ירחא דשבועתא (שביעי מלשון שבועה), וכמבואר בדרושי הצ\"צ<sup data-n=\"154\">24</sup> השייכות דירחא דשבועתאלמשביעין אותו תהי צדיק. ואולי יש להוסיף, דבחודש השביעי ג' פירושים, שביעי כפשוטו, שביעי מלשון שבועה (ירחא דשבועתא כנ\"ל), ושביעי מלשון שובע, כדאיתא במדרש<sup data-n=\"155\">25</sup> דפירוש בחודש השביעי הוא, שהוא משובע בכל (גיתות בתוכו, ברכות בתוכו, וכו'). ועד\"ז הוא במשביעין אותו תהי צדיק כו', שמבואר בכ\"מ<sup data-n=\"156\">26</sup> וגם בדרושי הצ\"צ<sup data-n=\"157\">27</sup> דבמשביעין ג' פירושים. משביעין כפשוטו, וגם מלשון שובע ומלשון שבעה, כדלקמן.\nד) <b>והנה</b> השייכות דג' ענינים אלה (שבועה, שובע, שבעה) היא, דענין השבועה הוא שמקשר את עצמותו. וכמו בשבועה כפשוטה, דזה שהאדם נשבע לעשות איזה דבר (הגם שעכשיו בעת שנשבע הוא רוצה בזה, ולמה צריך להשבועה), הוא, בכדי שגם כשיהי' איזה דבר שיגרום שלא ירצה בהדבר, הנה ע\"י שנשבע לעשות הדבר, יעשה את הדבר גם נגד רצונו<sup data-n=\"158\">28</sup>. והטעם על זה הוא כי ענין השבועה הוא שמקשר את עצמותו בזה, עצם הנפש שלמעלה מרצון. ועד\"ז הוא למעלה, דענין השבועה הוא כמ\"ש<sup data-n=\"159\">29</sup> בי נשבעתי, בי בעצמותי. וכמבואר בהדרושים<sup data-n=\"160\">30</sup>, דבי קאי על עתיק, וידוע<sup data-n=\"161\">31</sup> שעתיק הוא בחינה תחתונה שבמאציל שלמעלה משרש הנאצלים.\n<b>וזהו</b><sup data-n=\"162\">32</sup> משביעין אותו תהי צדיק, דזה שצריך להשביע את הנשמה תהי צדיק, הגם שזה (להיות צדיק) הוא רצון הנשמה, כי ע\"י התלבשותה בגוף ונפש הבהמית, אפשר שהגוף ונה\"ב יעלימו ויסתירו על הנשמה. ובפרט ששרש נה\"א הוא בתיקון ושרש נה\"ב הוא בתוהו שקדם לתיקון. ולכן משביעין את הנשמה תהי צדיק, דענין השבועה הוא המשכת שרש הנשמה כמו שהיא מושרשת בעצמות אוא\"ס (למעלה מהענין דתוהו ותיקון), ועי\"ז תוכל להתגבר על נה\"ב. וזהו שמשביעין אותו הוא גם מלשון שובע, דשובע הוא נתינת כח. וע\"י השבועה, המשכת שרש הנשמה כמו שהיא מושרשת בעצמות אוא\"ס [שהוא בדוגמת שרש הבן כמו שהוא במוח האב עצמו טרם שנמשך<sup data-n=\"163\">33</sup>], נותנים כח להנשמה כמו שהיא בגילוי למעלה [שהוא בדוגמת הבן כמו <i>שנמשך</i> ממוח האב<sup data-n=\"163\">33</sup>], וגם להנשמה כמו שהיא מלובשת בגוף ונה\"ב, לעבוד עבודתה בסור מרע (אל תהי רשע) ובועשה טוב (תהי צדיק).ה) <b>והנה</b> מדייק הצ\"צ<sup data-n=\"164\">34</sup> במ\"ש משביעין אותו תהי צדיק, איך מהני השבועה לנשמה על הגוף ונה\"ב, שזהו דבר שאינו ברשותה, והלא אין אדם מקנה דבר שאינו ברשותו. ומבאר, דזה שמשביעין אותו תהי צדיק למדו רז\"ל ממ\"ש<sup data-n=\"165\">35</sup> כי לי תכרע כל ברך תשבע כל לשון, כי לי תכרע כל ברך זה יום המיתה, תשבע כל לשון זה יום הלידה. והתחלת כתוב זה הוא בי נשבעתי, דבי קאי על עתיק<sup data-n=\"166\">36</sup> (כנ\"ל). וזה שתשבע כל לשון בא בהמשך לבי נשבעתי, הוא, כי בהשבועה שמשביעין אותו תהי צדיק נמשך כח מבחינת בי נשבעתי. ובכח זה, ביכולת הנשמה לשלוט על נה\"ב<sup data-n=\"167\">37</sup>. ויש לומר, דהביאור איך מהני השבועה לנשמה על הגוף ונה\"ב שזה דבר שאינו ברשותה, הוא, כי מצד הדרגא דבי נשבעתי, גם הגוף ונה\"ב הם ברשות הנשמה. דבבחינת הגילויים, הנשמה והגוף ונה\"ב הם שני ענינים. דשרש הנשמה הוא בתיקון ושרש הגוף ונה\"ב הוא בתוהו. אבל באוא\"ס שלמעלה מתוהו ותיקון, מכיון שהכוונה מלכתחילה בבנין וסתירת התוהו היתה שיהי' בירור התוהו (שרש הגוף ונה\"ב) ע\"י התיקון (שרש נה\"א)<sup data-n=\"168\">38</sup>, לכן ע\"י גילוי אוא\"ס, גם הגוף ונה\"ב נעשים ברשותה של הנשמה, כי כוונת התהוותם מלכתחילה היא שיתבררו ע\"י הנשמה.\nו) <b>ויש</b> לומר, שהחילוק בין שני הענינים דמשביעין אותו, משביעין מלשון שבועה ומשביעין מלשון שובע, הוא, שמשביעין מלשון שבועה הוא המשכת שרש הנשמה, ומשביעין מלשון שובע הוא שהמשכה זו תהי' בגילוי בהנשמה כמו שבאה בהמשכה (כולל הנשמה כמו שהיא מלובשת בגוף ונה\"ב), בדוגמת שביעה כפשוטה, שהמאכל משביע את <i>האדם</i>. וזהו דמשביעין אותו מלשון שובע הוא נתינת כח (כמבואר בכ\"מ<sup data-n=\"169\">39</sup>), דע\"י שההמשכה דהשבועה היא בגילוי בהנשמה שבהגוף, יש לה הכח להתגבר על נפש הבהמית (כנ\"ל סעיף ד), וגם לפעול בו הבירור והזיכוך (כנ\"ל סעיף ה), שבשביל זה ירדה למטה. וכמבואר בתניא<sup data-n=\"170\">40</sup>, דתכלית הכוונה בירידת הנשמה למטה הוא (לא בשביל הנשמה, אלא) בכדי לברר ולזכך את הגוף ונה\"ב וחלקו בעולם.\n<b>ויש</b> לקשר זה עם מ\"ש הצ\"צ<sup data-n=\"171\">41</sup> דשבועה היא בבינה ביסוד ובמלכות, דזה ששבועה היא בבינה שייך להשבועה עצמה, המשכת עתיק [ועד\"ז המשכת שרש הנשמה], דבבינה הוא גילוי עתיק<sup data-n=\"172\">42</sup>. כמ\"ש<sup data-n=\"173\">43</sup> ונהר יוצא מעדן, דנהר הוא בינה ועדן הוא עתיק, ופירוש נהר יוצא מעדן הוא שבבינה הוא גילוי עתיק. וזה ששבועה היאבמלכות שייך להשובע דשבועה, דזה שהשבועה משפעת ונותנת כח בהנשמה שבהגוף הוא ע\"י שההמשכה היא במלכות, וזה ששבועה היא ביסוד, הוא, שהמשכת הבינה (ועתיק שבה) במלכות היא ע\"י היסוד. וזהו גם הקשר עם הפירוש השלישי במשביעין אותו שהוא מלשון שבע, דלפי ביאור אחד קאי זה על היסוד, שהוא שביעי מהבינה<sup data-n=\"174\">44</sup>.\nז) <b>ועפ\"ז</b> יובן הקשר של השבועה שמשביעין אותו תהי צדיק עם חודש השביעי, ירחא דשבועתא, כי זה שבריאת האדם היתה ביום הששי למעשה בראשית, יום הראשון דחודש השביעי, הוא מפני שני טעמים<sup data-n=\"175\">45</sup>. להיותו אחור למעשה בראשית<sup data-n=\"176\">46</sup>, דשרש הדצ\"ח הוא מתוהו ושרש האדם הוא מתיקון שלמטה מתוהו. ולהיותו קודם למעשה בראשית<sup data-n=\"176\">46</sup> (קדום במעלה), כדאיתא בגמרא<sup data-n=\"177\">47</sup>, דזה שהאדם נברא בסוף הוא כדי שיכנס לסעודה מיד, שזה מורה על מעלת האדם, שכל הבריאה היא בשביל האדם. דגם התהוות התוהו שקדם לתיקון הוא בכדי שיהי' בירור התוהו ע\"י עבודת האדם, כנ\"ל. וזהו מה שאומרים על היום דראש השנה זה היום תחלת מעשיך<sup data-n=\"178\">48</sup>, אף שבריאת העולם היתה בכ\"ה באלול<sup data-n=\"179\">49</sup>, כי<sup data-n=\"180\">50</sup> הכוונה בבריאת העולם היא שהאדם ע\"י עבודתו יעשה את העולם דירה לו ית', וענין זה הותחל ביום ברוא האדם. דנוסף לזה שאז דוקא נעשית האפשרות להשלים כוונה זו, נעשה אז כן גם בפועל, כמארז\"ל<sup data-n=\"181\">51</sup> שאדם הראשון (ביום שנברא) הכריז לכל הברואים בואו<sup data-n=\"182\">52</sup> נשתחוה ונכרעה נברכה לפני ה' עושנו, וכולם ענו ואמרו ה'<sup data-n=\"183\">53</sup> מלך גאות לבש. וזהו שחודש השביעי (שבו נברא האדם) הוא ירחא דשבועתא, כי הכח שיש באדם לפעול בהעולם, אף שבגילוי האדם הוא אחור למעשה בראשית, הוא ע\"י גילוי שרשו האמיתי של האדם, שהוא קדם למעשה בראשית, וגילוי זה הוא ע\"י השבועה (כנ\"ל בארוכה), ירחא דשבועתא.\n<b>ועד\"ז</b> הוא בראש השנה שבכל שנה ושנה, שאז מכתירין ישראל [שקרויין אדם, לפי שבכ\"א מישראל יש ניצוץ מנשמת אדם הראשון, כנ\"ל סעיף ג] את הקב\"ה למלך עליהם ועל כל העולם, שעי\"ז עושים את העולם דירה לו ית', ובכל שנה ושנה ההכתרה ועשיית הדירה שעי\"ז הם באופן נעלה יותר, שהכח שבכאו\"א מישראל על זה הוא ע\"י שבכל ראש השנה, התחלת ירחא דשבועתא, נמשכת מחדש השבועה שמשביעין את כאו\"א מישראל תהי צדיק. ויש לומר, דע\"י שאמר אדמו\"רהזקן את הדרוש משביעין אותו תהי צדיק בראש השנה, אמירת תורה (תורה אור), המשכת השבועה בראש השנה היא בגילוי עוד יותר.\nח) <b>ואולי</b> יש להוסיף, דזה שארז\"ל שהטעם על זה שהאדם נברא בסוף הוא כדי שיכנס לסעודה מיד, הכוונה בזה היא, לא רק להעולם שהאדם צריך לעשותו דירה לו ית', אלא גם להנתינת כח להאדם, משביעין אותו מלשון שובע (ענין סעודה), שיוכל לעשות את העולם דירה לו ית'. ועפ\"ז יש לומר, דזה שהאדם הוא קדם למעשה בראשית והכל נברא בשבילו, נכלל בזה גם השבועה. דהכוונה בהשבועה, המשכת בחינת עתיק [וי\"ל יתירה מזו, גם הכוונה בבחינת עתיק עצמה], היא בשביל עבודת האדם. וע\"י שהאדם יקיים את השבועה, נעשה בה עילוי, שנשלמת כוונת השבועה.\nט) <b>והנה</b> זה שנת\"ל (סעיף ז) שבראש השנה נמשכת נתינת כח להאדם לפעול בהעולם ולעשותו דירה לו ית', יש לקשר עם המבואר בכ\"מ<sup data-n=\"184\">54</sup>, שבתחלת הבריאה, המשכת הרצון והתענוג בבריאת העולמות היתה מצד עצמו, כי חפץ חסד הוא<sup data-n=\"185\">55</sup>, והמשכת הרצון והתענוג בבריאת העולם עכשיו היא ע\"י עבודת האדם, דיש לומר, דחילוק זה הוא לא רק באופן ההמשכה (אם ההמשכה היא מצד עצמה או שההמשכה היא ע\"י עבודת האדם) אלא גם בהרצון והתענוג עצמם. דהרצון והתענוג שבבריאת העולמות שמצד חפץ חסד הוא <i>בבריאת העולמות</i>, שעי\"ז מתגלה חסדו ית'<sup data-n=\"186\">56</sup>, והרצון והתענוג שבבריאת העולמות שע\"י עבודת האדם הוא זה שנתאוה הקב\"ה להיות לו ית' דירה בתחתונים<sup data-n=\"187\">57</sup> ושעשיית הדירה תהי' ע\"י עבודת האדם. וע\"י גילוי תענוג זה בבריאת העולמות, שהכוונה דבריאת העולמות היא בשביל ישראל, יש כח בהאדם (אתם קרויין אדם) לפעול בהבריאה ולעשות דירה לו ית'. דזה שנת\"ל שהנתינת כח להאדם לפעול בהבריאה הוא גילוי שרש הנשמה (ענין השבועה), הוא בנוגע <i>להאדם</i>. והפעולה שנעשית <i>בהעולם</i> ע\"י עבודת האדם (שע\"י עבודת האדם נעשה העולם דירה לו ית') הוא ע\"י גילוי כוונת הבריאה, שבריאת העולם היא בשביל ישראל.\nיו\"ד) <b>ועפ\"ז</b> יש לבאר שגם בראש השנה שחל להיות בשבת ישנה מעלת העבודה<sup data-n=\"188\">58</sup>, כי הכוונה בהמשכת התענוג [וגם בהתענוג עצמו] היא בשביל האדם, שע\"י התענוג תהי' נתינת כח לאדם לעשות את העולם דירה לו ית' (וע\"ד שנת\"ל סעיף ח בענין השבועה), דהנתינת כח להאדם הוא דוקא כשהמשכת התענוג הוא בגילוי. וכיון שגם בראש השנה שחל להיות בשבת גילוי התענוג הוא ע\"י אמירת פסוקי שופרות (כמבואר לעיל סעיף ב מהמשך תרס\"ו), נמצא, שגם העבודה דאמירת פסוקי שופרות היא בנוגע לענין עיקרי.<b>ויש</b> להוסיף, שזה שע\"י מצות תקיעת שופר נעשית רק ההמשכה, והגילוי הוא ע\"י התורה (אמירת פסוקי שופרות), הוא, מפני ששרש התורה הוא למעלה משרש המצוות. ויש לקשר זה עם המבואר בהמשך הנ\"ל<sup data-n=\"189\">59</sup>, דיש עוד מעלה באמירת פסוקי שופרות, דההמשכה שע\"י תקיעת שופר היא רק האור והגילוי שנמשך מהעצמות, וע\"י אמירת הפסוקים נמשך העלם העצמי עצמו, בדוגמת העלי' שיהי' לעתיד. ועפ\"ז מובן עוד יותר שגם בראש השנה שחל להיות בשבת ישנה מעלת העבודה, כי ע\"י העבודה דאמירת פסוקי שופרות גם ההמשכה עצמה היא המשכה נעלית יותר.\n<b>וכיון</b> ששבת הו\"ע המנוחה והתענוג, גם העבודה בראש השנה שחל להיות בשבת, ועד\"ז העבודה דערב ראש השנה, היא מתוך מנוחה ותענוג, וזה פועל גם על כל השנה, שתהי' שנה של מנוחה ותענוג, ועד לאמיתית ענין המנוחה – יום שכולו שבת ומנוחה לחיי העולמים<sup data-n=\"190\">60</sup>, ובקרוב ממש בעגלא דידן.\n**********",[["130","*","יצא לאור ב<b>קונטרס כ\"ט אלול – תשמ\"ט</b> [יום הולדת המאתיים דכ\"ק אדמו\"ר הצמח צדק]<b> ראש השנה – תש\"נ</b>, \"לקראת ערב ראש השנה . . יום מלאת מאתיים שנה להולדת אדמו\"ר ה\"צמח צדק\" (כ\"ט אלול ה'תקמ\"ט – כ\"ט אלול ה'תשמ\"ט), ולקראת ראש השנה הבעל\"ט (שחל להיות בשבת) – הננו מוציאים לאור את המאמר ד\"ה יו\"ט של ר\"ה שחל להיות בשבת . . שבו מדובר גם ע\"ד הדרוש משביעין אותו תהי צדיק שאמר אדמו\"ר הזקן בר\"ה תק\"ן, בקשר עם לידת הצמח צדק . . <i>ערב כ\"ט אלול ה'תשמ\"ט</i>\"."],["131","1","משנה ר\"ה רפ\"ד (כט, ב)."],["132","2","שם."],["133","3","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380943\" data-slug=\"likkutei-torah\" data-id=\"4001380943\">לקו\"ת</a> דרושים לר\"ה ד\"ה להבין המשנה (נו, א ואילך). ד\"ה הנ\"ל בסידור (עם דא\"ח) שער התקיעות (רמ, ג ואילך). המשך יו\"ט של ר\"ה תרס\"ו בתחלתו. תש\"ג. <i>ועוד</i>."],["134","4","המשך תרס\"ו שם. וראה לקו\"ת שם \"ובפרט מצות שופר ולולב כו' שנוגעים עד רום המעלות\"."],["135","5","ראה שו\"ע אדה\"ז או\"ח הל' שבת סשמ\"ה סי\"א. וש\"נ. ולהעיר מהמשך יו\"ט של ר\"ה ה'תש\"ג בתחלתו \"איך דחו כו' שלא לבוא לידי חשש איסור <i>שבות</i>\"."],["136","6","בלקו\"ת שם ובהמשך תרס\"ו שם \"<i>והלא</i> החשש הוא להדיוטים כו'\". ובהמשך ר\"ה ה'תש\"ג \"<i>ועוד זאת</i> שהחשש הוא להדיוטים כו'\". וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071052\" data-slug=\"likkutei-sichot\" data-id=\"1300071052\">לקו\"ש ח\"ז ע' 52</a>. ואכ\"מ."],["137","7","כ\"ה הלשון במקומות שבהערה הקודמת. ויש לומר: הדיוטים – שאין יודעים דיני תקיעת שופר, וקלי הדעת – שלכן יש לחשוש שיעבירו ד' אמות ברשות הרבים."],["138","8","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380947\" data-slug=\"likkutei-torah\" data-id=\"4001380947\">לקו\"ת שם נז, א</a> ואילך. סידור שם רמג, א ואילך. <i>ועוד</i>."],["139","9","ראה אוה\"ת נצבים ע' א'תלח \"בשבת אין צריך <i>כ\"כ</i> לתקיעת שופר\"."],["140","10","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380945\" data-slug=\"likkutei-torah\" data-id=\"4001380945\">לקו\"ת שם נו, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380908\" data-slug=\"likkutei-torah\" data-id=\"4001380908\">וראה גם ד</a>\"ה זה היום ה'תשמ\"א ס\"ג (לקמן ע' לא), דזהו הטעם על זה שכ\"ה באלול הוא בחינת \"כה\" וראש השנה (יום ברוא אדם הראשון) הוא בחינת \"זה\" (זה היום) (לקו\"ת נצבים מז, ב-ג). וראה גם ד\"ה זה היום דליל ערב ר\"ה ה'תשמ\"ב ס\"ה (לקמן ע' מד ואילך). <i>וש\"נ</i>."],["141","11","ביצה יז, א."],["142","12","בסיומו – ע' תקמו."],["143","13","משלי ו, כג."],["144","14","נדה ל, ב."],["145","15","\"היום יום\" ו אדר שני."],["146","16","הצ\"צ נולד בכ\"ט אלול תקמ\"ט, ערב ר\"ה תק\"ן (\"היום יום\" כט אלול, ערב ר\"ה. וראה בארוכה \"התמים\" חוברת ג' ע' כה [קכט, ב]), והדרוש משביעין אותו אמר אדמו\"ר הזקן בר\"ה הראשון לחייו (דהצ\"צ) ר\"ה תק\"ן."],["147","17","להעיר שבספ\"ג דתניא [סיום וחותם הדרוש, דהכל הולך אחר החיתום (ברכות יב, א)] מדובר בענין הדעת – ענינו של הצ\"צ (ראה סה\"ש ה'תש\"ב ריש ע' 19. ה'תש\"ה ע' 60)."],["148","18","נצבים מז, ב."],["149","19","יבמות סא, רע\"א."],["150","20","בראשית ב, ז."],["151","21","לקו\"ת שם מז, א."],["152","22","ויק\"ר פכ\"ט, ט."],["153","23","אמור כג, כד."],["154","24","\"קיצורים והערות\" לתניא ע' נח. אוה\"ת דרושים לר\"ה ע' א'שיב."],["155","25","ויק\"ר שם, ח."],["156","26","ד\"ה ועשית חג שבועות תרח\"צ (סה\"מ תרח\"צ ע' רלה ואילך)."],["157","27","ב\"הגהות וביאורים\" לתניא פ\"א, נדפסו ב\"קיצורים והערות\" לתניא ע' מח ואילך. ד\"ה תניא בספ\"ג דנדה משביעין אותו וד\"ה ועשית חג שבועות להצ\"צ, קטעים מהם נעתקו בליקוט פירושים וכו' לתניא שם."],["158","28","בלקו\"ת שמע\"צ (פג, ג) \"נגד חכמתו ורצונו\". וי\"ל שהכוונה בזה שמוסיף \"ורצונו\" היא, דפעולת השבועה היא לא רק שע\"י השכל לא יהי' שינוי בהרצון, אלא שגם אם יהי' שינוי גם בהרצון (שבגילוי) יעשה נגד רצונו."],["159","29","בזהר שבהערה הבאה (הובא בלקו\"ת שם) הובא הפסוק בי נשבעתי שנאמר לאברהם אבינו (וירא כב, טז). וב\"קיצורים והערות\" לתניא שבהערה 36 מובא זה גם בנוגע להפסוק בי נשבעתי שבישעי' (מה, כג) שממנו למדין בגמ' נדה שם שמשביעין אותו כו'."],["160","30","\"קיצורים והערות\" שם ס\"ע נב ואילך, מזח\"ג קל, א. וראה גם אוה\"ת דרושים לר\"ה ע' א'שיא."],["161","31","ראה ע\"ח שער מב (שער דרושי אבי\"ע) פ\"א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380276\" data-slug=\"likkutei-torah\" data-id=\"4001380276\">לקו\"ת בחוקותי מו, ג</a>. ובכ\"מ."],["162","32","בהבא לקמן ראה \"קיצורים והערות\" שם ע' מח ואילך. ד\"ה ועשית חג שבועות להצ\"צ הנ\"ל. קונטרס ומעין מי\"ד פ\"א."],["163","33","ראה בארוכה סה\"מ ה'תש\"ד ע' 130."],["164","34","ב\"קיצורים והערות\" שם ע' מח. וראה גם ד\"ה ועשית חג שבועות להצ\"צ (ליקוט פירושים וכו' ע' יט)."],["165","35","ישעי' מה, כג."],["166","36","\"קיצורים והערות\" שם ס\"ע מח. שם ס\"ע סו."],["167","37","שם ס\"ע סו ואילך."],["168","38","המשך והחרים תרל\"א ע' יט. המשך תרס\"ו ע' שכה. ובכ\"מ."],["169","39","קונטרס ומעין שם. ד\"ה הנ\"ל תרח\"צ (סה\"מ שם ע' רמ)."],["170","40","פל\"ז (מח, ב)."],["171","41","\"קיצורים והערות\" שם ע' נה."],["172","42","ראה זח\"ג קעח, ב. תו\"א ר\"פ לך לך. ובכ\"מ."],["173","43","בראשית ב, י."],["174","44","\"קיצורים והערות\" שם ע' סג."],["175","45","בהבא לקמן, ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380653\" data-slug=\"likkutei-torah\" data-id=\"4001380653\">לקו\"ת מטות פב, ד</a>. שמע\"צ פו, ג. אוה\"ת לתהלים (יהל אור) ע' תקפא."],["176","46","ברכות סא, א."],["177","47","סנהדרין לח, א."],["178","48","תפלת מוסף דר\"ה, מר\"ה כז, א."],["179","49","ויק\"ר רפכ\"ט. פסיקתא דר\"כ פיסקא כג (בחודש השביעי). יל\"ש עה\"פ (פינחס כט, א) ובחודש השביעי (רמז תשפב). תוד\"ה לתקופות – ר\"ה ח, א. וראה פרקי דר\"א רפ\"ח ובהגהות הרד\"ל שם."],["180","50","בהבא לקמן – ראה ד\"ה זה היום דליל ערב ר\"ה ה'תשמ\"ב ס\"ב (לקמן ע' מא) ואילך."],["181","51","זהר ח\"א רכא, ב. ח\"ג קז, ב. תקו\"ז תנ\"ו (צ, ב). וראה אוה\"ת וארא ס\"ע רלו ואילך."],["182","52","תהלים צה, ו."],["183","53","שם צג, א. פרקי דר\"א פי\"א."],["184","54","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380945\" data-slug=\"likkutei-torah\" data-id=\"4001380945\">לקו\"ת</a> דרושים לר\"ה ד\"ה להבין המשנה (נו, ג). וראה גם שם נח, ב. סידור (עם דא\"ח) שער התקיעות רמא, ד. אוה\"ת נצבים ע' א'רמב. שם ע' א'רנג. ועוד."],["185","55","מיכה ז, יח."],["186","56","להעיר משעהיוה\"א פ\"ד."],["187","57","ראה תנחומא נשא טז. בחוקותי ג. ב\"ר ספ\"ג. במדב\"ר פי\"ג, ו. תניא רפל\"ו."],["188","58","עוד ביאור בזה – ראה שיחת ש\"פ נצבים וילך תשמ\"ט (התוועדויות תשמ\"ט ח\"ד ע' 341 ואילך)."],["189","59","בסיומו – ע' תקמו-ז."],["190","60","סיום וחותם מסכת תמיד."]]],[1500360005,"<h3>בס\"ד. יום ב' דראש השנה ה'תש\"מ<sup data-n=\"191\">*</sup></h3>\n– הנחה –\n<b>וביום</b> שמחתכם ובמועדיכם ובראשי חדשיכם ותקעתם בחצוצרות גו' והיו לכם לזכרון לפני אלקיכם<sup data-n=\"192\">1</sup>, אני ה' אלקיכם. ואיתא בגמרא<sup data-n=\"193\">2</sup> ומה תלמוד לומר אני ה' אלקיכם זה בנה אב לכל מקום שנאמר בו זכרונות יהיו מלכיות עמהן (דאני ה' אלקיכם הוא מלכיות<sup data-n=\"194\">3</sup> ומזה שאומר אני ה' אלקיכם גבי והיו לכם לזכרון גו' למדים שבכ\"מ שנאמר בו זכרונות צ\"ל גם מלכיות). ומזה למדים<sup data-n=\"195\">4</sup> שבר\"ה צ\"ל מלכיות זכרונות ושופרות, ותקעתם גו' שופרות, והיו לכם לזכרון גו' זכרונות, אני ה' אלקיכם מלכיות. והנה ג' ענינים אלו (מלכיות זכרונות ושופרות) הם לא רק בדיבור, אמירת פסוקי מלכיות זכרונות ושופרות, וכמרז\"ל<sup data-n=\"196\">5</sup> אמרו לפני בר\"ה מלכיות זכרונות ושופרות, אלא גם במעשה בפועל, וכמו שמבאר במרז\"ל הנ\"ל מלכיות כדי שתמליכוני כו' (שתמליכוני בפועל) זכרונות כדי שיעלה זכרוניכם (שיעלה זכרוניכם בפועל) ובמה בשופר ע\"י תקיעת שופר במעשה בפועל<sup data-n=\"197\">6</sup>. והנה ברכות (ברכות מלכיות זכרונות ושופרות) מעכבות זו את זו<sup data-n=\"198\">7</sup>, משא\"כ ברכות ותקיעות אינן מעכבות זו את זו<sup data-n=\"199\">8</sup>. ומבואר בדרושי רבותינו נשיאינו ד\"ה זה (וביום שמחתכם)<sup data-n=\"200\">9</sup> לפי שברכות ותקיעות הם שני ענינים שונים, ברכות דיבור ותקיעות מעשה. וצריך להבין למה צריך בר\"ה לב' הענינים<sup data-n=\"201\">10</sup>. ובפרט שפשטות לשון רז\"ל ובמה <i>בשופר</i> פירושה היא <i>תקיעת</i> שופר<sup data-n=\"202\">11</sup>, שענין תמליכוני עליכם ויעלה זכרוניכם לפני לטובה נעשה ע\"י תק\"ש שהוא העיקר. וכדמוכח גם ממרז\"ל<sup data-n=\"203\">12</sup> שמצות היום בשופר היינו שכל הענינים דיום זה (ר\"ה) נמשכים ע\"י תק\"ש. וכמובן גם ממ\"ש הרמב\"ם<sup data-n=\"204\">13</sup> אע\"פ שתקיעת שופר בר\"ה גזירת הכתוב רמז יש בו כלומר עורו כו' ומבואר בדרושי רבותינו נשיאינו<sup data-n=\"205\">14</sup>שבאריכות לשונו של הרמב\"ם מרומזים ג' הענינים דמלכיות זכרונות ושופרות, שמזה מובן, שכל ג' ענינים אלו נמשכים ע\"י תק\"ש, והרמז (הכללי) בשופר עורו כו' הו\"ע התשובה (כמבואר ברמב\"ם שם), היינו דהמצוה דתק\"ש שייכת לכללות הענין דר\"ה (מצות היום בשופר), כי בר\"ה חוזרים כל הדברים לקדמותם וצריך לעורר המשכה חדשה מעצמותו ומהותו, ולהמשיך זה בכל סדר ההשתלשלות עד בעשי'. והמשכה זו היא ע\"י שופר, כי שופר רומז לענין התשובה כנ\"ל שעיקר התשובה הוא התאחדות עם המקור, קדמותם, וישנו באופן מלמטלמ\"ע ומלמעלמ\"ט כמ\"ש<sup data-n=\"206\">15</sup> והרוח תשוב אל האלקים אשר נתנה, כמבואר בלקו\"ת ריש פרשה זו (פרשת האזינו), ולכן עי\"ז מעוררים המשכה חדשה מעצמותו ומהותו, וע\"י העשי' (תקיעת שופר במעשה) ממשיכים<sup data-n=\"207\">16</sup> זה עד בעשי'<sup data-n=\"208\">17</sup>.\nב) <b>והנה</b> לא זו בלבד שצריך לעשי' גשמית (ואין מספיק ענין התשובה ברוחניות וגם לא אמירת הפסוקים), אלא שבזה גופא אין מספיק שיהי' קלא פנימאה של האדם וצריך לתקוע בקול שופר של בהמה דוקא<sup data-n=\"209\">18</sup>, ביעל פשוט או בזכרים כפופים, כב' הדיעות שבזה דאלו ואלו דברי אלקים חיים<sup data-n=\"210\">19</sup>. וגם עכשיו, שתוקעין (בר\"ה) בזכרים כפופים, יש ב' ענינים אלו בעבודה הרוחנית. של יעל פשוט כי כמה דפשיט איניש דעתי' טפי מעלי<sup data-n=\"211\">20</sup> ומבואר בחסידות<sup data-n=\"212\">21</sup> שהוא מה שהאדם צריך להפשיט את עצמו מכל רצונותיו. ואין הכוונה לרצונות הבלתי רצויים, כי מאי קמ\"ל, וענין זה (שלא יהיו אצלו רצונות בלתי רצויים) כבר נעשה ע\"י העבודה בחודש אלול לפני ר\"ה. וענין דפשיט איניש דעתי' שבר\"ה הוא שיפשוט את עצמו מכל ציור גם מציור דקדושה. כי ההמשכה דר\"ה היא ממה שלמעלה מגדר מקום ומגדר ציור, ולכן צריך להיות העבודה דפשיט, וע\"י הפשטות שבאדם הוא ממשיך הפשטות שלמעלה, ועד מבחי' תכלית הפשיטות. ותוקעין בשל זכרים כפופים כי כמה דכייף איניש דעתי' טפי מעלי<sup data-n=\"211\">20</sup> ומבואר בחסידות<sup data-n=\"212\">21</sup> שהוא העבודה דאתכפיא (שיש בזה מעלה גם על העבודה דהפשטת הרצונות<sup data-n=\"213\">22</sup>), שעבודה זו היא ע\"י בחי' זכר (זכרים כפופים), איש דרכו לכבוש<sup data-n=\"214\">23</sup>.\nג) <b>וזהו</b> מצות היום בשופר, שע\"י העבודה דשופר בב' האופנים דפשיט ודכייף [שבכל אחד מהם יש מעלה מיוחדת] ממשיכים אור חדש, וכמבוארבאגה\"ק<sup data-n=\"215\">24</sup> שבכל ר\"ה נמשך אור חדש שלא הי' מעולם, ועי\"ז נעשה חידוש בכל סדר ההשתלשלות, ועד שנעשה חידוש גם בחיצוניות העולמות. ועם היות שעיקר החידוש שבר\"ה הוא בפנימיות העולמות, הנה עי\"ז נעשה חידוש גם בחיצוניות העולמות, כמבואר בסידור<sup data-n=\"216\">25</sup> בד\"ה להבין ענין תק\"ש ע\"פ כוונת הבעש\"ט ז\"ל. וכל זה נעשה ע\"י ישראל עם קרובו, בנים אתם לה' אלקיכם<sup data-n=\"217\">26</sup>, כמו שמבאר הרב המגיד בלקו\"א ואו\"ת בתחלתם בענין במי נמלך בנשמותיהן של צדיקים<sup data-n=\"218\">27</sup>, שעלה לפניו ית' התענוג שיתענג בעבודתם של ישראל, וזה החליט את הרצון, ומבחי' רצון המוחלט נמשך לרצון הגלוי, ואח\"כ נמשך בכל סדר ההשתלשלות עד בעוה\"ז התחתון שאין תחתון למטה ממנו, שעי\"ז דוקא נשלמה הכוונה דדירה לו ית' בתחתונים<sup data-n=\"219\">28</sup>. וזהו אמרו לפני מלכיות כדי שתמליכוני עליכם כו' ובמה בשופר, שפירושו תקיעת שופר במעשה, דמצות היום בשופר, אלא שנכלל בזה (בהמשך להתחלת המאמר אמרו לפני כו' ושופרות) גם אמירת פסוקי שופרות&lt;11&gt; [ובפרט שעפ\"ז יש להתאים גירסתנו בגמרא להגירסא<sup data-n=\"220\">29</sup> אמרו לפני מלכיות כדי כו' זכרונות כדי כו' שופרות כדי כו' וי\"ג לאח\"ז<sup data-n=\"221\">30</sup> ובמה בשופר].\nד) <b>והנה</b> פסוק זה (וביום שמחתכם גו' ותקעתם בחצוצרות גו') הוא המשך וסיום הענין דלפנ\"ז<sup data-n=\"222\">31</sup> עשה לך שתי חצוצרות גו', וידועה תורת הרב המגיד<sup data-n=\"223\">32</sup> שתי חצוצרות שתי חצאי צורות, היינו שהקב\"ה וכנס\"י הם [כביכול, ואולי גם בלי כביכול] שתי חצאי צורות. ומזה מובן פירוש הכתוב ותקעתם בחצוצרות גו' והיו לכם לזכרון לפני אלקיכם אני ה' אלקיכם, שענין מלכיות (אני ה' אלקיכם) וזכרונות (והיו לכם לזכרון) שנעשה ע\"י ותקעתם בחצוצרות, בחצוצרות וקול שופר הריעו לפני המלך הוי'<sup data-n=\"224\">33</sup> [שבמקדש (לפני אלקיכם, לפני המלך הוי') היו שניהם (אלא שמצות היום בשופר, כמבואר במשנה&lt;12&gt;), וע\"י החלונות שקופים אטומים שהיו בביהמ\"ק<sup data-n=\"225\">34</sup>, נמשך זה (ככל הענינים שבביהמ\"ק) גם בגבולין ועד בכל העולם כולו. ואפילו בזמן הגלות], הוא מפני שהקב\"ה וישראל הם שתי חצאי צורות<sup data-n=\"226\">35</sup>. והעניןהוא, דנפש השנית בישראל היא חלק אלוקה ממעל ממש<sup data-n=\"227\">36</sup>, וידוע<sup data-n=\"228\">37</sup> שיש בזה ב' קצוות. כי ממש קאי על חלק אלוקה ממעל, היינו שנפש השנית שבישראל היא חלק ממש מעצומ\"ה, וידוע מאמר הבעש\"ט<sup data-n=\"229\">38</sup> העצם כשאתה תופס בחלקו אתה תופס בכולו, ותיבת ממש מורה גם על קצה הכי תחתון, ממש מה שנתפס בחוש המישוש. וזהו מה שנפש השנית שבישראל היא חלק אלוקה ממעל ממש, שגם כשהיא מלובשת בגוף ממש מלשון מישוש, גם אז היא חלק ממש ממהו\"ע ית', חד ממש עם עצומ\"ה, וכתורת הרב המגיד (שהובא לעיל) שהם שתי חצאי צורות. והנה מכיון שאתם קרויין אדם<sup data-n=\"230\">39</sup> על שם אדמה לעליון<sup data-n=\"231\">40</sup>, מובן שענין שתי חצאי צורות הוא גם בהנשמה עצמה. דהנה ידוע<sup data-n=\"232\">41</sup> שבכל נשמה יש ב' דרגות כלליות, חלק הנשמה שלמעלה (בחי' מזל) ראש שבנשמה, וחלק הנשמה שבגוף (כחות הגלויים) רגל שבנשמה. וב' בחי' אלו הם השתי חצאי צורות שבכל נשמה פרטית<sup data-n=\"233\">42</sup>. וענין ותקעתם בחצוצרות גו' והיו לכם לזכרון לפני אלקיכם גו' הוא שצריך לחבר ב' חצאי צורות שלו<sup data-n=\"234\">43</sup> ולהעמידם (אַוועקשטעלן זיי) לפני ה' אלקיכם, וע\"י החיבור דב' חצאי צורות אלו (ראש ורגל) שבכל נשמה פרטית, עי\"ז נעשה גם החיבור דראש ורגל שבכללות ישראל והעלאתם לפני ה' אלקיכם, אתם נצבים היום (ר\"ה<sup data-n=\"235\">44</sup>) כולכם לפני ה' אלקיכם ראשיכם גו' עד חוטב עציך ושואב מימיך, שכל ישראל [הראש דישראל (ראשיכם) והרגל דישראל (חוטב עציך ושואב מימיך)] מתחברים יחד והם נצבים ומתעלים לפני ה' אלקיכם<sup data-n=\"236\">45</sup>, והם נעשים עמו דבר אחד כמו שממשיך בכתוב<sup data-n=\"237\">46</sup> לעברך בברית גו' שענין הברית הוא שהם נעשים לדבר אחד<sup data-n=\"238\">47</sup>.\nה) <b>וזהו</b> וביום שמחתכם גו' ותקעתם בחצוצרות גו' אני ה' אלקיכם, ותקעתם הו\"ע תקיעת שופר, דמצות היום (דר\"ה) הוא בשופר, וכדאיתא במשנה&lt;12&gt; שופר מאריך וחצוצרות מקצרות שמצות היום בשופר. ועי\"ז נמשך ונתגלה גם הענין דחצוצרות<sup data-n=\"239\">48</sup> שהקב\"ה וישראל הם ב' חצאי צורות, היינו מה שישראל הם מושרשים בעצמותו ית' והם המחליטים את הרצון (כנ\"ל בענין במי נמלך בנשמותיהן של צדיקים), ומרצון המוחלט נמשך לרצון הגלוי וכו' עד שנמשך למטה בעוה\"ז, שזהוהעיקר. והיינו שההמשכה בכל הדרגות, עונג רצון מוחין מדות ומלכות וכו' הוא ממוצע שעי\"ז יומשך אח\"כ בעוה\"ז. וכמבואר בתניא קדישא<sup data-n=\"240\">49</sup> שבכל סדר ההשתלשלות הוא ירידה מאור פניו ית', ותכלית הכוונה הוא עוה\"ז התחתון שאין תחתון למטה ממנו, בירא עמיקתא, שבו דוקא (בעוה\"ז התחתון) נברא האדם וניתנה בו הנשמה חלק אלוקה ממעל ממש, וע\"י עבודתו בתומ\"צ (לעבדה ולשמרה<sup data-n=\"241\">50</sup>) נשלמה הכוונה דדירה בתחתונים, דירה לעצמותו ומהותו<sup data-n=\"242\">51</sup>, שיהי' אלה תולדות פרץ תולדות מלא<sup data-n=\"243\">52</sup>, שהוא למעלה יותר גם מכמו שהי' בתחלת הבריאה דעולם על מילואו נברא<sup data-n=\"244\">53</sup>, פרץ הוליד גו' את דוד<sup data-n=\"245\">54</sup>, דוד מלכא משיחא, שיבנה ביהמ\"ק<sup data-n=\"246\">55</sup> ויהי' ותקעתם בחצוצרות גו' לפני אלקיכם, בחצוצרות וקול שופר הריעו לפני המלך ה', כפשוטו (בביהמ\"ק) למטה מעשרה טפחים. כי ע\"י העבודה שבמשך זמן הגלות דתקעו בחודש שופר, שפרו מעשיכם<sup data-n=\"247\">56</sup>, ובאופן של חידוש כדיוק הכתוב תקעו <i>בחודש</i> שופר (ולא תקעו שופר בחודש) כידוע פירוש הבעש\"ט<sup data-n=\"248\">57</sup> בזה, עי\"ז נעשה הענין דעשה לך שתי חצוצרות גו' למקרא העדה ולמסע את המחנות&lt;31&gt; לאסף את כל ישראל יחד ולמסע ולהליכה מחיל אל חיל, מבירא עמיקתא עד לאיגרא רמה, והענין דכי<sup data-n=\"249\">58</sup> תבואו מלחמה מלחמה עם נה\"ב<sup data-n=\"250\">59</sup> ונושעתם ע\"י אתכפיא ואתהפכא, ועי\"ז יהי' ותקעתם בחצוצרות לפני אלקיכם בביהמ\"ק השלישי שיבנה בקרוב ממש ע\"י משיח צדקנו, וכל זה באופן דוביום שמחתכם, ושמחת עולם על ראשם<sup data-n=\"251\">60</sup>, במהרה בימינו ממש.\n**********",[["191","*","יצא לאור בשעתו, \"<i>וא\"ו תשרי</i>,<i> ה'תש\"מ</i>\"."],["192","1","בהעלותך יו\"ד, יו\"ד."],["193","2","ר\"ה לב, א."],["194","3","ראה פירש\"י ר\"ה שם. וכ\"ה בספרי ופירש\"י בהעלותך שם."],["195","4","ספרי שם."],["196","5","ר\"ה טז, א. לד, ב."],["197","6","בד\"ה וביום שמחתכם תרפ\"ז [וכ\"ה בד\"ה זה תרנ\"ו]: ומ\"ש במה בשופר היינו פסוקי שופרות שז\"ע שופר בדיבור וצ\"ל במעשה ג\"כ. ואולי הכוונה ד\"ובמה בשופר\" כולל <i>גם</i> פסוקי שופרות (כתירוץ השני בריטב\"א ר\"ה טז, א). ולהעיר משו\"ע אדה\"ז ר\"ס תקצ\"א: וע\"י מה ע\"י שופר לפיכך אומר כו' פסוקי שופרות."],["198","7","ר\"ה לד, ב. או\"ח סתקצ\"ג."],["199","8","או\"ח שם."],["200","9","תרנ\"ו, תרפ\"ז."],["201","10","וכמו שמדייק בד\"ה זה תרנ\"ו, תרפ\"ז."],["202","11","ראה לעיל הערה 6."],["203","12","ר\"ה כו, ב (במשנה)."],["204","13","הל' תשובה פ\"ג ה\"ד."],["205","14","המשך תרס\"ו בתחלתו. ד\"ה שופר של ר\"ה תש\"ב פ\"ג."],["206","15","קהלת יב, ז."],["207","16","להעיר מ<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380956\" data-slug=\"likkutei-torah\" data-id=\"4001380956\">לקו\"ת ר\"ה נט, ב</a> (ועד\"ז בעט\"ר שער ר\"ה פ\"ט): ולכן צריך לתקוע . . דוקא בשופר גשמי . . ועי\"ז . . שיהיו השפעותם בגשמיות."],["208","17","ומה שצריך גם לאמירת הפסוקים – ראה ד\"ה יו\"ט של ר\"ה (דערב ר\"ה שנה זו), <i>וש\"נ</i>."],["209","18","ראה לקו\"ת שם: השפעת חיים גשמיים היינו בחי' בהמיות ונעשה ג\"כ ע\"י התקיעה . . בקרן הכבשים שהיא בהמיות."],["210","19","עירובין יג, ב."],["211","20","ר\"ה כו, ב."],["212","21","ד\"ה אני לדודי תרצ\"ג (נדפס בסה\"מ קונטרסים ח\"ג) פ\"ז."],["213","22","להעיר גם מ<a class=\"ft-cite\" href=\"#/read/torah-or/3901370403\" data-slug=\"torah-or\" data-id=\"3901370403\">תו\"א פט, ד</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370512\" data-slug=\"torah-or\" data-id=\"3901370512\">קיד, ד</a>."],["214","23","יבמות סה, ב. וש\"נ."],["215","24","סי\"ד."],["216","25","רמו, ג."],["217","26","ראה יד, א."],["218","27","ב\"ר פ\"ח, ז. רות רבה פ\"ב, ג."],["219","28","<a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא פל\"ו</a>."],["220","29","תוספתא ר\"ה פ\"א, יא."],["221","30","שלטי הגבורים ר\"ה טז, א. וי\"ל <i>שמפרש</i> גירסת הרי\"ף שהיא כבש\"ס ולא דגריס כן בש\"ס."],["222","31","בהעלותך יו\"ד, ב."],["223","32","או\"ת מה, ד ואילך. הובא ונתבאר באוה\"ת לתהלים (יהל אור) ס\"ע שנז ואילך. ובארוכה – בהמשך תער\"ב פשפ\"ד ואילך."],["224","33","תהלים צח, ז. וראה ר\"ה כז, א."],["225","34","מלכים א ו, ד. וראה מנחות פו, ב ובפירש\"י שם."],["226","35","באו\"ת להה\"מ שם, הענין דשתי חצאי צורות הוא עה\"פ עשה לך שתי חצוצרות. ובד\"ה וביום שמחתכם תרפ\"ז [וראה גם אוה\"ת לתהלים שם ע' שסב. ד\"ה שופר של ר\"ה תרצ\"ט בתחלתו ובסיומו] הובא זה גם לענין ותקעתם בחצוצרות."],["227","36","<a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא רפ\"ב</a>."],["228","37","ראה ליקוט מ\"מ ופירושים לתניא שם (ע' סז)."],["229","38","המשך תרס\"ו ע' תקכב. סה\"ש תש\"א ס\"ע 32. וש\"נ."],["230","39","יבמות סא, א."],["231","40","של\"ה כ, ב. שא, ב. ובכ\"מ."],["232","41","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380969\" data-slug=\"likkutei-torah\" data-id=\"4001380969\">לקו\"ת ר\"ה סב, ג</a>. ד\"ה וביום שמחתכם תרנ\"ו, תרפ\"ז. <i>ובכ\"מ</i>."],["233","42","ד\"ה וביום שמחתכם תרפ\"ז."],["234","43","ד\"ה הנ\"ל בסופו. וראה גם ד\"ה שופר של ר\"ה תרצ\"ט בתחלתו ובסופו."],["235","44","לקו\"ת ר\"פ נצבים."],["236","45","נצבים כט, ט-י. לקו\"ת שם."],["237","46","נצבים שם, יא."],["238","47","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380896\" data-slug=\"likkutei-torah\" data-id=\"4001380896\">לקו\"ת שם מד, ב</a>. וראה בארוכה ד\"ה אתם נצבים דש\"פ נצבים-וילך תשל\"ט (לקמן ח\"ד ע' ערב ואילך)."],["239","48","ראה ד\"ה וביו\"ש תרפ\"ז בתחלתו: דענין החצוצרות הוא ע\"י השופר דוקא. ושם בסופו (וראה גם אוה\"ת לתהלים ע' שסב), דשופר הוא למעלה מחצוצרות."],["240","49","פל\"ו."],["241","50","בראשית ב, טו. ובתיב\"ע שם: למהוי פלח באורייתא ולמנטר פקודהא."],["242","51","אוה\"ת בלק ע' תתקצז, המשך תרס\"ו ס\"ע ג. ע' תמה. ובכ\"מ."],["243","52","רות ד, יח. ב\"ר פי\"ב, ו."],["244","53","ראה ב\"ר פי\"ד, ז. פי\"ג, ג."],["245","54","רות ד, יח-כב."],["246","55","רמב\"ם הל' מלכים ספי\"א."],["247","56","תהלים פא, ד. ויק\"ר פכ\"ט, ו."],["248","57","כתר שם טוב סרנ\"ו (לה, א)."],["249","58","בהעלותך יו\"ד, ט."],["250","59","אוה\"ת בהעלותך ס\"ע שע."],["251","60","ישעי' לה, י. נא, יא."]]],[1500360006,"<h3>בס\"ד. יום ב' דראש השנה ה'תשמ\"א<sup data-n=\"252\">*</sup></h3>\n<b>זה</b> היום תחלת מעשיך זכרון ליום ראשון<sup data-n=\"253\">1</sup>, וידוע דהיום (סתם) קאי על ראש השנה<sup data-n=\"254\">2</sup>, ופירוש זה היום הוא שבהיום דראש השנה נמשכת בחי' זה<sup data-n=\"255\">3</sup>, דבראש השנה מכתירים בני ישראל את הקב\"ה למלך<sup data-n=\"256\">4</sup> ופועלים ועושים גילוי מלכותו ית' בכל העולם, עד אשר וידע כל פעול כי אתה פעלתו<sup data-n=\"257\">5</sup>, שגם בחי' פעול שבעשי'<sup data-n=\"258\">6</sup> (ומכ\"ש דיצירה ודבריאה) ידע כי אתה פעלתו. וזהו זה היום, דבראש השנה נמשך אלקות בגילוי ממש, ועד ד\"זה\", כאו\"א מראה באצבעו ואומר זה<sup data-n=\"259\">7</sup>. וי\"ל דזהו גם הביאור שאומרים על היום דראש השנה זה היום תחלת מעשיך, דידוע הדיוק בזה מכ\"ק אדמו\"ר הזקן וכ\"ק אדמו\"ר האמצעי וכ\"ק אדמו\"ר הצ\"צ וכ\"ק אדמו\"ר מהר\"ש וכ\"ק אדמו\"ר (מהורש\"ב) נ\"ע וכ\"ק מו\"ח אדמו\"ר נשיא דורנו, שהרי בכ\"ה באלול נברא העולם<sup data-n=\"260\">8</sup> וראש השנה הוא יום ברוא אדם הראשון שהוא יום וא\"ו למע\"ב<sup data-n=\"261\">9</sup>, ואיך אומרים על יום זה שהוא תחלת מעשיך. וגם למה ראש השנה הוא באחד בתשרי ולא בכ\"ה באלול. ועוד שבראש השנה כל באי עולם יעברון לפניך כבני מרון<sup data-n=\"262\">10</sup>, לא רק סוג המדבר אלא גם הנבראים דסוג החי, דסוג הצומח ודסוג הדומם, ולמה ראש השנה הוא ביום ברוא האדם דוקא. והביאור בזה, דתכלית הכוונה בבריאת העולם הוא שהאדם ע\"י עבודתו ימשיך גילוי אלקות בעולם, גילוי עד ד\"זה\" (כאו\"א מראה באצבעו ואומר זה), וענין זה נתחדש ונעשה ביום ברוא האדם, דבריאת העולם בכ\"ה באלול היתה בבחי' כה, וביום ברוא אדם הראשון (ע\"י עבודתו) נתחדש ונעשה גילוי אלקות, בבחי' זה<sup data-n=\"263\">11</sup>.ב) <b>וביאור</b> ענין העילוי שנתחדש ונעשה ביום ברוא אדם הראשון יובן בהקדים מעלת דרגת העולם כמו שנברא ביום הראשון דמעשה בראשית (בכ\"ה באלול), שאז הי' העולם בדרגא נעלית (כדלקמן), שמזה יובן גודל העילוי שנתחדש ונעשה בהעולם ביום ברוא אדם הראשון. וי\"ל שזהו הטעם שבכו\"כ דרושי רבותינו נשיאינו דראש השנה (שמבואר בהם הטעם על זה שראש השנה הוא בא' בתשרי) מבוארת בהם המעלה דכ\"ה באלול, כי ע\"י הביאור במעלת כ\"ה באלול מובן יותר גודל העילוי דראש השנה.\n<b>והנה</b> ביום הראשון דמע\"ב (כ\"ה באלול) נבראו השמים והארץ וכל צבאם מאין ליש כמ\"ש<sup data-n=\"264\">12</sup> בראשית ברא אלקים את השמים ואת הארץ, שהשמים והארץ וכל צבאיהם (את השמים לרבות תולדותיהם ואת הארץ לרבות תולדותי'<sup data-n=\"265\">13</sup>) נבראו אז מאין ליש. דגם הנבראים שנתהוו בהימים דמע\"ב שלאחרי היום הראשון הרי אז היתה התגלות שלהם, יצירה ועשי', אבל בריאתם מאין ליש היתה ביום הראשון<sup data-n=\"266\">14</sup>. וגם האדם, שהמעלה דראש השנה היא (כנ\"ל) שביום זה נברא האדם, הרי כתיב בי' וייצר ה' אלקים את האדם עפר מן האדמה<sup data-n=\"267\">15</sup>, והעפר מן האדמה (שממנו נוצר גוף האדם) נתהווה ביום הראשון. ובמיוחד ע\"פ הידוע<sup data-n=\"268\">16</sup> שהכתוב בראשית גו' מדבר בהתהוות השמים והארץ הגשמיים וגם בהתהוות האצילות, בראשית חכמה, אלקים בינה, את השמים ז\"א ואת הארץ מלכות. וכל זה נתהווה ביום הראשון. וגם איתא במדרש עה\"פ ויהי ערב ויהי בוקר יום אחד<sup data-n=\"269\">17</sup>, דמ\"ש יום אחד (ולא יום ראשון) הוא לפי שבו הי' הקב\"ה יחידי בעולמו. והיינו דההתהוות דיום הראשון היתה באופן שהי' אז נראה ונגלה שהוא ית' אחד בעולמו<sup data-n=\"270\">18</sup>. וענין זה (הקב\"ה יחידי בעולמו) הי' אז מצד למעלה ומצד וכמו שנמשך למטה, והמאמר שנאמר ביום הראשון הי' ויאמר אלקים יהי אור<sup data-n=\"271\">19</sup>, שעל ידו יוכלו בנ\"י (ע\"י עבודתם) להאיר את העולם כולו ולגלות את הפנימיות שבו, אוא\"ס שלפני הבריאה והצמצום, ועד לעצמות ומהות, שבהעולם כמו שהוא מצד עצמו (גם כמו שנברא ביום הראשון) הוא בהעלם. וי\"ל דזהו שאמרו רז\"ל<sup data-n=\"272\">20</sup> אור שנברא ביום ראשון לא הי' העולם כדאי להשתמש בו, והבדילו לעצמו<sup data-n=\"273\">21</sup>,כי אור זה הוא למעלה מהעולם, ובפרט ע\"פ המבואר בכ\"מ<sup data-n=\"274\">22</sup> הפירוש (וגודל העילוי) דהבדילו לעצמו.\nג) <b>והנה</b> נוסף על כל העילויים הנ\"ל שהיו ביום הראשון דמע\"ב, הנה ידוע שבכל ו' ימי בראשית, גם ביום הששי דמע\"ב (לפני חטא עה\"ד), הי' כללות העולם בדרגת ג\"ע<sup data-n=\"275\">23</sup>. דג\"ע (גם כמו שהוא עכשיו) הוא דרגא הכי נעלית, ועאכו\"כ כמו שהי' אז. ואעפ\"כ, ע\"י בריאת האדם בראש השנה נתוסף עילוי בהעולם [ועד שע\"י עבודת אדם הראשון נתוסף עילוי גם בג\"ע כמו שהי' אז, כמ\"ש<sup data-n=\"276\">24</sup> ויניחהו בג\"ע לעבדה גו', להמשיך אוא\"ס בג\"ע<sup data-n=\"277\">25</sup>]. דהגם שעולם על מילואו נברא<sup data-n=\"278\">26</sup> וכמ\"ש<sup data-n=\"279\">27</sup> אלה תולדות השמים והארץ בהבראם תולדות מלא<sup data-n=\"280\">28</sup>, הרי שלימות זו דעולם היא כמו שהעולם הוא מצד הבריאה, וכדיוק לשון הכתוב אלה תולדות (מלא) גו' <i>בהבראם</i>, וכן בלשון חז\"ל עולם על מילואו <i>נברא</i>, והשלימות דעולם כמו שהוא מצד הבריאה (מלמעלה) הוא במדידה והגבלה. וע\"י עבודת האדם נמשך אור שלמעלה ממדידת והגבלת העולם, אלה תולדות פרץ<sup data-n=\"281\">29</sup> תולדות מלא<sup data-n=\"280\">28</sup>, שפורצים<sup data-n=\"282\">30</sup> כל המדידות וההגבלות דעולם, גם המדידות וההגבלות דעולם כמו שהי' ביום הראשון דמע\"ב, שבו הי' הקב\"ה יחידי בעולמו.\n<b>וזהו</b> מה שראש השנה הוא ביום ברוא אדם הראשון דוקא, כי ענין ראש השנה הוא המשכת בחי' זה (כנ\"ל בפירוש זה היום), היינו<sup data-n=\"283\">31</sup> המשכת וגילוי עצמות אוא\"ס שלמעלה מגדר שייכות לעולמות. וזה היום תחלת מעשיך, שהגילוי דבחי' זה נמשך גם במעשיך, דגם בהעולם שמצד עצמו הוא בבחי' כה יהי' בו גילוי בחי' זה (ועד שגם בחי' פעול (שבעשי') ידע כי אתה פעלתו, כנ\"ל). ולכן ראש השנה הוא ביום ברוא אדם הראשון דוקא, כי כח זה (להמשיך גילוי עצמות אוא\"ס שלמעלה מהעולמות, ושהמשכה זו תהי' בעולם) הוא בישראל דוקא, אתם קרויים אדם<sup data-n=\"284\">32</sup>, על שם אדם הראשון<sup data-n=\"285\">33</sup>.\nד) <b>ויש</b> לומר שהכח שיש בישראל להמשיך גילוי בחי' זו, הוא מצד שרש נשמתם [שהרי בריאת האדם ביום ששי למע\"ב (ראש השנה) היא שאז הי' ויפחבאפיו נשמת חיים<sup data-n=\"286\">34</sup>. משא\"כ גופו של אדם הראשון שנוצר מעפר מן האדמה<sup data-n=\"286\">34</sup> שנבראה כבר (כנ\"ל) ביום הראשון<sup data-n=\"287\">35</sup>]. והענין הוא, דהנה כתיב<sup data-n=\"286\">34</sup> ויפח באפיו נשמת חיים, ומבאר רבינו הזקן<sup data-n=\"288\">36</sup> כמ\"ש בזהר<sup data-n=\"289\">37</sup> מאן דנפח מתוכי' נפח, ומפרש מתוכיותו ומפנימיותו, היינו ד(שרש) הנשמה הוא בעצמותו ית'. והגם שממשיך שם, דכמו שהבן נמשך ממוח האב כך כביכול נשמת כל איש ישראל נמשכה ממחשבתו וחכמתו ית', הנה זה שהנשמה היא בבחי' מחשבתו וחכמתו ית' הוא כמו שהיא באה בהמשכה, אבל שרשה (האמיתי) הוא בעצמותו ית'. דכמו שהוא בהמשל דאב ובן, דשרש הבן הוא מעצמות האב ממש שלמעלה מבחי' הגילויים (דהאב), שלכן אפשר שיהי' יפה כח הבן מכח האב<sup data-n=\"290\">38</sup> כי שרש הבן הוא מעצם נפש האב ובעצם נפשו הרי האב שלם בכל כוחותיו<sup data-n=\"291\">39</sup>, עד\"ז הוא גם בנשמות ישראל, בנים אתם להוי' אלקיכם<sup data-n=\"292\">40</sup>, ששרשם הוא בעצמותו ית' (שלמעלה מבחי' הגילויים), ולכן יש בהם עילוי כביכול על בחי' הגילויים שלמעלה, בדוגמת יפה כח הבן מכח האב. וכמרז\"ל<sup data-n=\"293\">41</sup> קוב\"ה חייך ואמר נצחוני בני נצחוני, קוב\"ה הוא אוא\"ס כמו שבא בהמשכה באופן דקדוש וברוך [קדוש הוא סוכ\"ע, שהוא קדוש ומובדל מהשתלשלות, וברוך מלשון ברכה והמשכה הוא כמו שנמשך להיות ממכ\"ע<sup data-n=\"294\">42</sup>], ומכיון ששרש הנשמות הוא בעצמותו ית' (שלמעלה גם מבחי' קדוש), לכן קוב\"ה חייך ואמר נצחוני בני נצחוני [וענין זה שייך במיוחד לראש השנה, כמאמר רז\"ל<sup data-n=\"295\">43</sup>, כשמתכנסין מלאכי השרת לפני הקב\"ה לומר אימתי ראש השנה כו' הקב\"ה אומר להם לי מה אתם שואלים, אני ואתם נלך אצל ב\"ד של מטה]. ובפרט ע\"פ תורת הרב המגיד<sup data-n=\"296\">44</sup> בפירוש מרז\"ל<sup data-n=\"297\">45</sup> ישראל עלו במחשבה, שהוא כמשל הבן שצורתו חקוקה במחשבת האב, אלא שבבני אדם שייך זה דוקא לאחרי שנולד הבן, משא\"כ אצל השי\"ת, אף קודם שנבראו ישראל הי' נחקק צורתם במחשבה, כי אצלו ית' העבר והעתיד אחד. שמזה מובן עוד יותר<sup data-n=\"298\">46</sup>, דשרש הנשמות (בנים אתם לה' אלקיכם) הוא בעצמותו ית'.ה) <b>ויש</b> לומר שזהו מ\"ש אדמו\"ר הזקן&lt;36&gt; בענין ויפח באפיו נשמת חיים, שהוא בבחי' נפיחה בכח כביכול<sup data-n=\"299\">47</sup>, דזה שצריך להיות נפיחה בכח הוא מפני ששרש הנשמה הוא בבחי' העלם העצמי, העלם שאינו במציאות, וההמשכה מבחי' העלם שאינו במציאות היא ע\"י טרחא ויגיעה דוקא. דהנה ידוע שבכדי להמשיך מהעלם שישנו במציאות אין צריך לטרחא ויגיעה. וכמו שלהבת הקשורה בגחלת, דלהיות שגם בתוך הגחלת היא במציאות אש אלא שאינה נראה ונגלה בחוץ (העלם שישנו במציאות), לכן הוצאת השלהבת מהגחלת היא בלי עמל ויגיעה. משא\"כ ההמשכה מבחי' העלם שאינו במציאות היא ע\"י טרחא ויגיעה דוקא. וכמו הוצאת האש מצור החלמיש, דלהיות האש שבצור הוא בבחי' העלם שאינו במציאות, לכן אי אפשר להוציא ממנו אש כ\"א ע\"י הכאה, בטרחא ויגיעה דוקא. וכמבואר כ\"ז בארוכה בדרושי כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע<sup data-n=\"300\">48</sup>. וזהו מ\"ש אדה\"ז שויפח באפיו נשמת חיים הוא בבחי' נפיחה בכח, כי שרש הנשמות הוא בבחי' העלם שאינו במציאות, בחי' צור [וכמבואר בלקו\"ת<sup data-n=\"301\">49</sup> בענין התשובה דוהרוח תשוב אל האלקים אשר נתנה<sup data-n=\"302\">50</sup>, דבחי' האלקים (אשר נתנה) שהוא שרש הנשמה (ומבחינה זו ניתנה הנשמה באופן דנתינה, דכל<sup data-n=\"303\">51</sup> הנותן בעין יפה הוא נותן<sup data-n=\"304\">52</sup>) הוא בחי' צור], ולכן ההמשכה משם היא ע\"י נפיחה בכח. ולהיות דשרש נש\"י הוא בעצמותו ית' לכן ביכלתם להמשיך בעולם גילוי עצמות אוא\"ס.\nו) <b>והנה</b> הנ\"ל הוא ביאור על זה שבכחם של ישראל להמשיך גילוי עצמות אוא\"ס. אמנם זה שממשיכים גילוי זה בעולם, חיבור בחי' זה עם בחי' כה&lt;33&gt;, י\"ל שהוא ע\"י שממשיכים גילוי נשמתם בגופם. דהנה גוף האדם (שנוצר מעפר מן האדמה שנברא ב<i>כ\"ה</i> באלול) הוא בחי' כה, וע\"י שפועל גילוי אלקות בגופו, עי\"ז הוא ממשיך גילוי אלקות גם בעולם. דבמדה שאדם מודד בה מודדין לו<sup data-n=\"305\">53</sup>, ולכן ע\"י שהאדם ממשיך הגילוי דבחי' זה בבחי' כה שבעצמו, עי\"ז נמשך הגילוי דבחי' זה גם בבחי' כה דכל העולם<sup data-n=\"306\">54</sup>. וכמו אדם הראשון שאמר לכל הבריאה בואו נשתחוה ונכרעה נברכה לפני ה' עושינו<sup data-n=\"307\">55</sup>, דזה שפעל ביטול בכל הבריאה (שחוץ ממנו) הוא ע\"י פעולת הביטול בעצמו. וכפירוש נשתחוה (ולא השתחוו), היינו<sup data-n=\"308\">56</sup> ש(גם) הואעצמו ישתחוה ויהי' בביטול. וביאור הענין (זה שהמשכת גילוי אלקות בעולם היא ע\"י קדימת ההמשכה בגוף האדם), הנה שם אדם הוא על שם אדמה לעליון<sup data-n=\"309\">57</sup>, וי\"ל דזהו בנשמת האדם וגם בגוף האדם, כמ\"ש<sup data-n=\"310\">58</sup> נעשה אדם גו' כדמותנו<sup data-n=\"311\">59</sup>. וכמו שגופו של אדם הראשון הי' יציר כפיו של הקב\"ה<sup data-n=\"312\">60</sup>, <i>עד\"ז</i> הוא גם בהנוגע להגוף דכאו\"א מישראל, שהרי אתם קרויים אדם ע\"ש אדם הראשון (כנ\"ל). וזה שכאו\"א מישראל נקרא אדם ע\"ש אדמה לעליון, בין מצד נשמתו בין מצד גופו, הו\"ע נצחי שאין שייך בו שינוי. וכמ\"ש<sup data-n=\"313\">61</sup> ואתם תהיו לי ממלכת כהנים וגוי קדוש, די\"ל שממלכת כהנים קאי על הנשמה וגוי קדוש קאי על הגוף<sup data-n=\"314\">62</sup>, ובשניהם נאמר ואתם תהיו לי, דכל מקום שנאמר לי אינו זז לעולם<sup data-n=\"315\">63</sup>. ולכן ע\"י עבודת האדם להמשיך גילוי אלקות בגופו, נמשך עי\"ז גילוי אלקות גם בעולם.\nז) <b>וזהו</b> זה היום תחלת מעשיך כו' כי חק לישראל הוא משפט לאלקי יעקב<sup data-n=\"316\">64</sup>, דמלת כי פירושה נתינת טעם על מה שקדם לומר זה היום תחלת מעשיך<sup data-n=\"317\">65</sup>. דהנה החיבור ד\"זה\" ו\"כה\" שבאדם (שעי\"ז הוא ממשיך הגילוי ד\"זה\" גם בבחי' \"כה\" דהעולם) הוא ע\"י עבודתו בלימוד התורה ובקיום המצוות. דעסק התורה שייך (בעיקר) להנשמה<sup data-n=\"318\">66</sup> (זה), וקיום המצוות שנתלבשו בדברים גשמיים שייך (בעיקר) לבירור וזיכוך הגוף<sup data-n=\"318\">66</sup>, וע\"י העבודה בעסק התורה וקיום המצוות (ועד שנעשים ענין אחד, מכיון שכל אחד מסייע להשני<sup data-n=\"319\">67</sup>), נעשה החיבור ד\"זה\" עם \"כה\". וזהו כי חק לישראל הוא משפט לאלקי יעקב, חק קאי על התורה ומשפט על המצוות (כמבואר בלקו\"ת<sup data-n=\"317\">65</sup>). דזהו חק לישראל גו' משפט לאלקי יעקב, דבתורה (חק) אומר ישראל ובמצוות (משפט) אומר יעקב, כי התורה היא הבנה והשגה, ולכן שייכת לישראל אותיות לי ראש<sup data-n=\"320\">68</sup>, ומצוות שקיומן הוא בכח המעשה של האדם שייכות ליעקב מלשון עקב<sup data-n=\"321\">69</sup>. וגם יעקב הוא על שם וידו אוחזת בעקב גו'<sup data-n=\"322\">70</sup>, וי\"ל שזהו<sup data-n=\"323\">71</sup> שהמצוות נתלבשובדברים גשמיים דעוה\"ז התחתון שאין תחתון למטה ממנו. וזהו זה היום תחלת מעשיך כו' כי חק לישראל הוא משפט לאלקי יעקב, ד\"חק לישראל גו' משפט לאלקי יעקב\" הוא נתינת טעם על זה היום תחלת מעשיך, היינו דהמשכת וגילוי עצמות אוא\"ס (\"זה\") בהעולם (\"מעשיך\") ע\"י האדם שנברא בהיום דראש השנה (\"היום\") הוא ע\"י חק לישראל גו' משפט לאלקי יעקב, לימוד התורה וקיום המצוות<sup data-n=\"324\">72</sup>.\nח) <b>וע\"פ</b> הנ\"ל יש לבאר גם מה שידוע דבראש השנה הוא בנין המלכות<sup data-n=\"325\">73</sup>, דכמו שבראש השנה בפעם הראשונה, ביום ברוא אדם הראשון, הי' (התחלת) גילוי מדת מלכותו ית' ע\"י אדם הראשון, דזהו מה שאמר אדם הראשון אז (השיר של יום ו'<sup data-n=\"326\">74</sup>) הוי' מלך גאות לבש<sup data-n=\"327\">75</sup>, עד\"ז הוא בכל שנה ושנה, שבהיום דראש השנה הוא המשכת בחינת המלכות ממקורה ע\"י ישראל שקרויין אדם ע\"ש אדם הראשון כנ\"ל<sup data-n=\"328\">76</sup>. וזהו שאומרים בהתפלות דראש השנה&lt;5&gt; מלוך על העולם כולו בכבודך כו' מלך על כל הארץ [וענין זה<sup data-n=\"329\">77</sup> אומרים מיד בתחלת ראש השנה, בתפלת ערבית], לפי שעיקר הענין דראש השנה הוא המשכת ובנין המלכות.\n<b>דהנה</b> ע\"פ המבואר בכ\"מ<sup data-n=\"330\">78</sup> משמע שהשייכות דראש השנה לענין המשכת המלכות היא לפי שבראש השנה הוא חידוש מע\"ב (שלכן נקרא תחלת מעשיך)<sup data-n=\"331\">79</sup>, החידוש דכללות העולמות והתהוותם ליש<sup data-n=\"332\">80</sup>, ולכן צריך להמשיך אז מדת המלכות, לפי שהתהוות כל העולמות היא ממדת מלכותו ית'. וביאור זה דורש תוס' ביאור, שהרי לצורך ההתהוות צ\"ל כל המדות, כמ\"ש<sup data-n=\"333\">81</sup> כי ששת ימים עשה ה' את השמים ואת הארץ וידוע<sup data-n=\"334\">82</sup> דששת ימים קאי על שש המדות שמהן נעשו השמים והארץ, דכל יומא ויומא עביד עבידתי'<sup data-n=\"335\">83</sup>. ואע\"פ שבשביל התהוות העולם צ\"ל כל המדות, בכ\"ז מדגישים בהתפלות דראש השנה המשכת המלכות דוקא. ונוסף על זה, הרי ענין המלכות שלצורך התהוות העולמות הוא (בעיקר) בחינת הדיבור דמלכות, בדבר הוי' שמים נעשו<sup data-n=\"336\">84</sup>, והם העשרה מאמרות שבהם נברא העולם<sup data-n=\"337\">85</sup>, וההדגשה בראש השנההיא (לא על ענין הדיבור דמלכות, כי אם) על ענין <i>המלוכה, מלוך</i> על העולם כולו כו' <i>מלך</i> על כל הארץ. וגם בנוגע להדיבור דמלכות, הרי רובם ככולם של המאמרות שבהם נברא העולם היו לפני יום ו' דמע\"ב [ויתירה מזו, שהתהוות הנבראים מהעשרה מאמרות היא תמיד (גם לאחרי שי\"ב) כתורת הבעש\"ט הידועה<sup data-n=\"338\">86</sup>, וכמאמר<sup data-n=\"339\">87</sup> המחדש בטובו בכל יום תמיד מעשה בראשית וידוע שזהו בכל יום תמיד דוקא, בכל רגע ורגע], ומה זה שייך לראש השנה דוקא.\n<b>ויש</b> לומר הביאור בזה, דזה שבראש השנה הוא בנין המלכות, שייך זה (בעיקר) לזה שראש השנה הוא זה היום, המשכת עצמות אוא\"ס, בחינת זה. [ויש לקשר זה גם עם הביאור (כמו שמשמע בכ\"מ) דהשייכות דראש השנה לבנין המלכות היא כי בראש השנה הוא חידוש מע\"ב. דהנה ידוע מה שמבואר בסידור (בשער התקיעות ד\"ה להבין ענין תק\"ש ע\"פ כוונת הבעש\"ט ז\"ל<sup data-n=\"340\">88</sup>), דזה שבראש השנה נעשה החידוש דכל סדר ההשתלשלות, הוא (בעיקר) בפנימיות העולמות, אלא שעי\"ז נעשה חידוש גם בחיצוניות העולמות, שלא יהי' באופן דרפיון ידים. ועפ\"ז יש לקשר שני הביאורים בענין השייכות דבנין המלכות לראש השנה (שבראש השנה הוא החידוש דמע\"ב ושבראש השנה הוא המשכת בחינת זה), כי החידוש שבפנימיות העולמות שייך להמשכת בחינת זה]. וזהו שההדגשה בראש השנה היא על ענין המלוכה שבמלכות (ולא על הדיבור דמלכות), כי הענין דבנין המלכות (המשכת המלכות משרשה) שייך להמשכת עצמות אוא\"ס. דהגם שכל הספירות המשכתם היא מעצמות אוא\"ס כמ\"ש<sup data-n=\"341\">89</sup> כי ממך הכל [ומכ\"ש הדיבור דמלכות, העשרה מאמרות שבהם נברא העולם מאין ליש, וכידוע דבריאה יש מאין היא בכח העצמות, דהוא לבדו בכחו ויכלתו לברוא יש מאין ואפס המוחלט<sup data-n=\"342\">90</sup>], אעפ\"כ, ענין ההמשכה דעצמות אוא\"ס (בחינת זה), שזהו הענין דראש השנה כנ\"ל, שייך בעיקר לבנין המלכות דוקא.\nט) <b>ויובן</b> זה ע\"פ המבואר בדרושי רבותינו נשיאינו בענין ההפרש שבין מדת המלכות לשאר המדות, די\"ל דנקודת ביאורים אלו היא כמ\"ש כ\"ק מו\"ח אדמו\"ר בד\"ה שופר של ראש השנה<sup data-n=\"343\">91</sup>, שמדת המלכות חלוקה מכל המדות בשרשה, במהותה ובאופן (במציאות) מהותה, בהתעוררותה ובאופן התעוררותה, בהתגלותה ובאופן התגלותה. החילוק בשרשה הוא, דכל המדות וספירות כלולים באריך אנפין ומדת המלכות מושרשת ברדל\"א<sup data-n=\"344\">92</sup>. החילוק במהותה ובמציאות (אופן) מהותה הוא, שכל המדות וספירות, גם כמו שהם בשרשם בבחי' אריך, הם ט' נהורין<sup data-n=\"344\">92</sup>, ומדת המלכות היא רק נקודה ובבחי' לא מציאות. החילוק בהתעוררותה ובאופןהתעוררותה ובהתגלותה הוא, דכל המדות והספירות מתעוררים גם מעצמם, ולכן אופן התעוררותם הוא גם מדבר שאינו מערכם וכן התגלותם היא גם על מה שאינו מערכם כלל, משא\"כ מדת המלכות התעוררותה היא רק ע\"י הזולת, ולכן אופן התעוררותה הוא רק ממי שבערכה, וגם התגלות המלכות הוא רק על מי שבערכה. והחילוק באופן התגלותה הוא, שכל המדות ההשפעה (והגילוי) שלהם היא בקירוב [וכמו ההשפעה דמדת החסד, שהיא מצד הרגש הקירוב דהמשפיע להמקבל, וכן הוא בההשפעה דכל המדות, ואפילו בההשפעה דמדת הגבורה, שהיא מצד הרגש השייכות והקירוב], משא\"כ מדת המלכות ההשפעה (והגילוי) שלה היא בריחוק והבדלה, רוממות והתנשאות. והנה הסיבה לכל חילוקים אלו שבין מדת המלכות לשאר המדות הוא החילוק שביניהם בשרשם. דלהיות<sup data-n=\"345\">93</sup> ששרש המלכות הוא ברדל\"א, דבחי' רדל\"א הוא לא רק רישא דלא אתיידע אלא גם רישא דלא ידע<sup data-n=\"346\">94</sup>, שאינו במהות ידוע גם לעצמו, לכן, גם כמו שבאה בבחי' המשכה (מהותה ומציאות מהותה) היא בבחי' לא מציאות<sup data-n=\"347\">95</sup>, ובכדי שתבוא בבחי' התעוררות, הוא ע\"י הזולת דוקא. ולכן גם באופן התעוררותה ובהתגלותה צריך להיות זולת השייך, שבערכה דוקא. והיינו, דכל המדות, מכיון שעצם המדה וגם התעוררותה היא מהאדם עצמו, וכמו מדת החסד והרחמים ששייכים (גם ההתעוררות שלהם) גם בלי זולת, לכן אינו מעכב בזה מה הוא הדבר שמתחסד עמו ומרחם עליו, ושייכים גם על בעלי חיים<sup data-n=\"348\">96</sup> אף שאינם בערך האדם. משא\"כ מדת המלכות, מכיון שהיא באה מהזולת דוקא, לכן צ\"ל שהזולת (המעורר את מדת המלכות, ושמדת המלכות מתגלית עליו) יהי' בערכו דוקא, דמלוכה שייכת רק על מין האדם ולא על בע\"ח, וגם צ\"ל שהזולת יהי' נפרד דוקא, אין מלך בלא עם<sup data-n=\"349\">97</sup>, משא\"כ על בנים לא שייך ענין המלוכה. וענין זה שייך גם לאופן התגלות המלכות, זה שההשפעה דמלכות היא בבחי' ריחוק דוקא<sup data-n=\"350\">98</sup>. וגם ענין זה (זה שההשפעה דמלכות היא בבחי' ריחוק והבדלה, רוממות והתנשאות) שייך לזה ששרש המלכות הוא ברדל\"א, כי ענין ההתנשאות על עם בא מצד ההתנשאות העצמית.\nיו\"ד) <b>וע\"פ</b> הנ\"ל (דענין המלוכה הוא דוקא על עם, משא\"כ על בנים) יובן, דזה שישראל הם עמו ית' יש בזה יתרון על בנים אתם, מכיון שעי\"ז דוקא(שהם עמו) הקב\"ה הוא מלך ישראל. והגם דזה שהוא מלך ישראל הוא מה שהוא מרומם ומנושא מהם (לכאורה ריחוק והבדלה), הרי ההתנשאות על עם קשורה (כנ\"ל) עם זה שהוא מרומם ומנושא בעצם. וזהו מ\"ש<sup data-n=\"351\">99</sup> ואנחנו עמך וצאן מרעיתך, ואיתא במדרש עה\"פ<sup data-n=\"352\">100</sup> דודי לי ואני לו הרועה בשושנים, הוא לי לאב ואני לו לבן הוא לי לרועה ואני לו לצאן, דמזה שבתחלה אומר הוא לי לאב ואני לו לבן ואח\"כ מוסיף הוא לי לרועה ואני לו לצאן, מובן, דענין הוא לי לרועה כו' הוא למעלה יותר מענין הוא לי לאב וכו', וכידוע<sup data-n=\"353\">101</sup> דענין הוא לי לרועה ואני לו לצאן הוא בבחינת גם<sup data-n=\"354\">102</sup> בן ואח אין לו. ומזה מובן גם בהתואר עמך (שבהמשך אחד עם וצאן מרעיתך) שהוא נעלה יותר מזה שישראל הם בניו ית'. דמכיון שאין מלך בלא עם, הרי נמצא, דזה שהקב\"ה הוא מלך ישראל<sup data-n=\"355\">103</sup> הוא דוקא מצד זה שישראל הם עמו ית'. כי ענין הרוממות וההתנשאות הוא (כנ\"ל) מצד זה שהוא מרומם ומנושא בעצם. וזהו שעיקר ההדגשה בראש השנה (ובהתפלות דראש השנה) הוא בענין המלכות, כי החידוש דראש השנה (על כ\"ה באלול), זה היום, הוא (כנ\"ל) שנש\"י [ששרשם הוא מבחי' צור, העלם שאינו במציאות] ממשיכים גילוי עצמות אוא\"ס, ושרש המלכות הוא ברדל\"א (בחי' העלם שאינו במציאות), ולמעלה יותר בבחי' רוממות העצמות.\nיא) <b>אמנם</b> עדיין צריך להבין, שהרי כל הספירות שרשם הראשון הוא ברדל\"א, דזה שכל הספירות (חוץ מספירת המלכות) כלולים באריך הוא מה שהם נמשכים אח\"כ באריך, אבל שרשם הראשון (גם דספירות אלו) הוא ברדל\"א, ולמעלה יותר עד מעצמותו ית', כמ\"ש&lt;89&gt; כי ממך הכל. ומכיון שבראש השנה חוזרים כל הדברים לקדמותם<sup data-n=\"356\">104</sup>, הרי גם כל המדות והספירות נמשכים אז מעצמותו ית', וא\"כ הרי החידוש דראש השנה הוא גם בכל המדות והספירות, ולמה מדגישים ענין המלכות דוקא.\n<b>ויש</b> לומר הביאור בזה, דההפרש בין ספירת המלכות לשאר הספירות (מה שנוגע כאן) הוא בהתכלית שלהם. דהנה ידוע<sup data-n=\"357\">105</sup> שהאצלת כל הספירות דאצילות היא בכדי שיהי' על ידם גילוי אלקות בבי\"ע עד למטה בעוה\"ז הגשמי (שנשמות ישראל כמו שהן מלובשות בגוף גשמי יהיו חד עם העצמות). שמבחינת החכמה דאצילות [שהיא עיקר האצילות] נמשך למטה ענין החכמה, ידיעת והשגת אלקות, ועד\"ז הואבכל הספירות. ובזה הוא העילוי דספירת המלכות על שאר כל הספירות, שגם בהמשכתה למטה היא באותו האופן כפי שהיא בשרשה הראשון בבחי' רדל\"א, דכל שאר הספירות, מכיון שענינם הוא שהם נהורין, גילוי [דהגם ששרשם הראשון הוא ברדל\"א, הרי לאחרי המשכתם בבחי' אריך הם נהורין וזהו ענינם], לכן, גם המשכתם למטה בבי\"ע היא בבחי' נהורין, גילוי. משא\"כ ספירת המלכות ענינה הוא בחי' נקודה ובחי' לא מציאות, וגם בהמשכתה בהדרגות שלמטה מרדל\"א [בבחי' מהותה ובבחי' מציאות מהותה ובבחי' התעוררותה ובבחי' אופן התעוררותה ובבחי' התגלותה ובבחי' אופן התגלותה, כנ\"ל] היא ע\"ד אותו האופן כמו שהיא בשרשה בבחי' רדל\"א, וגם בהמשכתה למטה מטה, בבי\"ע, היא באופן זה שנרגש בה שרשה (העצמות). דהגם שהמלכות (כמו שהיא בגילוי) היא בבחי' התנשאות על עם, הרי גם ענין ההתנשאות על עם הוא (כנ\"ל) מצד התנשאות העצמות. וזהו גם שההדגשה בראש השנה היא בענין המלכות דוקא ולא בענין הדיבור, כי הדיבור הוא בבחי' מציאות ובבחי' התחלקות (וכמבואר בסידור שער התקיעות שם<sup data-n=\"358\">106</sup> בענין ההפרש שבין קול לדיבור), משא\"כ המלכות היא בבחי' לא מציאות, והרוממות וההתנשאות (על עם) דמלכות היא מצד רוממות והתנשאות העצמות.\nיב) <b>וזהו</b> זה היום תחלת מעשיך, דהגם שבכ\"ה באלול נברא העולם וראש השנה הוא יום ו' למע\"ב, הרי כיון שתכלית כוונת הבריאה הוא כמארז\"ל<sup data-n=\"359\">107</sup> נתאוה הקב\"ה להיות לו ית' דירה בתחתונים, דירה לעצמותו ית' [וכידוע<sup data-n=\"360\">108</sup> דענין הדירה הוא מה שהעצם נמצא בהדירה], ושדירה זו תהי' בתחתונים, בעוה\"ז הגשמי שאין תחתון למטה ממנו<sup data-n=\"361\">109</sup>, לכן אומרים על היום דראש השנה, יום בריאת האדם, זה היום תחלת מעשיך, לפי שכוונה זו נשלמת ע\"י עבודתו של כאו\"א מישראל, אתם קרויים אדם&lt;32&gt;. דע\"י העבודה בלימוד התורה ובקיום המצוות (חק לישראל ומשפט לאלקי יעקב) עושים ופועלים בעולם שישוב ויהי' כמו שהי' בתחלת הבריאה (לפני הירידה שע\"י חטא עה\"ד), ויתירה מזה שיהי' בדרגא נעלית יותר מכמו שהי' קודם הבריאה, ועד שיהי' דירה לעצמותו. דע\"י העבודה דישראל, נעשה דירה לעצמותו ית' בתחתונים, בעוה\"ז הגשמי שאין תחתון למטה ממנו, בזה גופא גם בדרגות הכי תחתונות שבו, וידע כל פעול כי אתה פעלתו. דע\"י העבודה בקיום המצוות בכח המעשה של האדם, נמשך גילוי אלקות בהתחתון (כח המעשה) שבאדם, וע\"י פעולת כח המעשה של האדם בדבר הגשמי שחוץ ממנו נמשך הכח גם בדבר הגשמי, וכידוע<sup data-n=\"362\">110</sup> שהה\"מ הכיר בכלי את כח האומן, כח הפועל בנפעל (אף שעשיית הכליהיא יש מיש), ועי\"ז נעשה גם הדבר הגשמי (תחתון שבעולם) דירה לו ית', ועי\"ז נשלמת הכוונה דנתאוה הקב\"ה להיות לו ית' דירה בתחתונים, דזה שנתאוה הוא למעלה מטו\"ד, וכידוע מאמר רבינו הזקן<sup data-n=\"363\">111</sup> אויף אַ תאוה איז קיין קשיא. ועי\"ז נעשה היש הגשמי מציאות אמיתית, וכמו שמבאר כ\"ק אדמו\"ר מהר\"ש [במאמרו<sup data-n=\"364\">112</sup> שהי' אומר מזמן לזמן כדי לטהר את אויר העולם<sup data-n=\"365\">113</sup>], שמציאות העולם וכל מה שנברא בו הוא לא דמיון ואחיזת עינים כ\"א הוא מציאות באמת. ומביא ראי' על זה מפסק הלכה. והיינו, דהגם שהיש מתהווה תמיד מהאין ובטל אליו, מ\"מ הוא מציאות באמת, דמכיון שמאמיתת המצאו נמצאו כל הנמצאים<sup data-n=\"366\">114</sup>, הרי מציאותם של כל הנמצאים היא אמיתית המצאו ית', וכמו שמבאר כ\"ק אדמו\"ר האמצעי בביאורי הזהר<sup data-n=\"367\">115</sup> דאמיתית מציאותו של היש הגשמי הוא היש האמיתי.\nיג) <b>וכל</b> זה נעשה ע\"י כל פעולה טובה של כאו\"א מישראל, וכהפס\"ד<sup data-n=\"368\">116</sup> שע\"י מצוה אחת (במחשבה, ומכ\"ש בדיבור ומכ\"ש במעשה) מכריע את כל העולם כולו לכף זכות. דפס\"ד זה הוא במשך כל השנה. ועאכו\"כ בראש השנה שאז אין שייך כלל לומר שהעולם הוא שקול ח\"ו, שהרי כבר בערב ראש השנה יודעים בבירור גמור שיזכו בדין<sup data-n=\"369\">117</sup>, ועאכו\"כ בראש השנה גופא, ובפרט לאחרי תקיעת שופר, דכל שנה שהיא רשה בתחלתה מתעשרת בסופה<sup data-n=\"370\">118</sup> וידוע דרשה בתחלתה קאי על (קודם) תקיעת שופר כי שופר הוא בחי' מיצר ומן<sup data-n=\"371\">119</sup> המיצר קראתי י\"ה<sup data-n=\"372\">120</sup>, ומיד לאחרי זה מתעשרת, ענני<sup data-n=\"373\">121</sup> במרחב י\"ה, באור פניך יהלכון<sup data-n=\"373\">121</sup>, בכתיבה וחתימה טובה<sup data-n=\"374\">122</sup> בטוב הנראה והנגלה בכל המצטרך, ועאכו\"כ בענין העיקרי<sup data-n=\"375\">123</sup> – ביאת משיח צדקנו במהרה בימינו בעגלא דידן, ממש.\n**********",[["252","*","יצא לאור ב<b>קונטרס ראש השנה – תשמ\"ח</b>, \"לקראת ראש-השנה . . <i>יום ג'</i>,<i> ג' דסליחות שנת ה'תשמ\"ז</i>\"."],["253","1","תפלת מוסף דראש השנה, מר\"ה כז, א."],["254","2","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380883\" data-slug=\"likkutei-torah\" data-id=\"4001380883\">זח\"ב לב, ב</a> וברמ\"ז שם (הובא בלקו\"ת תבוא מא, ג). זח\"ג רלא, א. מג\"ע נצבים ד\"ה בעשירי (ס, ד). הגהת מהר\"י כץ בפענח רזא ס\"פ נצבים. לקו\"ת ר\"פ נצבים."],["255","3","ראה בהנסמן לקמן הערה 11."],["256","4","וכמרז\"ל (ר\"ה טז, א. לד, ב) אמרו לפני בר\"ה מלכיות . . כדי שתמליכוני עליכם."],["257","5","תפלת העמידה דראש השנה (ברכת \"אלקינו כו' מלוך כו'\")."],["258","6","סידור האריז\"ל במקומו. ועד\"ז במשנת חסידים מס' ליל ר\"ה פ\"ח מ\"ב. – הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380500\" data-slug=\"likkutei-torah\" data-id=\"4001380500\">לקו\"ת שלח מז, א</a>."],["259","7","לשון חז\"ל – תענית בסופה ובפרש\"י שם. שמו\"ר ספכ\"ג. וראה גם פרש\"י עה\"פ בשלח טו, ב. ובאוה\"ת דלקמן הערה 11 (ע' א'תלד) מביא בהמשך ל\"זה היום תחלת מעשיך\" \"ע\"ד שלע\"ל נאמר ואמר ביום ההוא הנה אלקינו זה\" – שהוא הפסוק שהובא בגמ' ובמדרש שם."],["260","8","ויק\"ר רפכ\"ט. פסיקתא דר\"כ פיסקא כג (בחודש השביעי). יל\"ש עה\"פ (פינחס כט, א) ובחודש השביעי (רמז תשפב). תוד\"ה לתקופות – ר\"ה ח, א. וראה פרקי דר\"א רפ\"ח ובהגהות הרד\"ל שם. וראה גם ר\"ן (הובא בחדא\"ג מהרש\"א) לר\"ה טז, א."],["261","9","ראה תוס' שם. רבינו בחיי עה\"פ בראשית א, יג (ד\"ה ויש לך לדעת). חדא\"ג מהרש\"א לר\"ה כז, א. וראה גם מכתב מוצש\"ק כ\"ה אלול תשמ\"ז (נדפס בלקו\"ש חל\"ד ע' 322 ואילך)."],["262","10","פיוט \"ונתנה תוקף\", מר\"ה טז, רע\"א (במשנה)."],["263","11","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380908\" data-slug=\"likkutei-torah\" data-id=\"4001380908\">לקו\"ת נצבים מז, ב</a>. אוה\"ת דרושים לר\"ה ד\"ה זה היום ע' א'תלב. שם ע' א'תלד. ובכ\"מ."],["264","12","בראשית א, א. וראה רמב\"ן עה\"פ: ואין אצלנו בלשון הקודש בהוצאת היש מאין אלא לשון ברא."],["265","13","פרש\"י עה\"פ שם, יד."],["266","14","פרש\"י שם ובפסוק כד."],["267","15","<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670057\" data-slug=\"torat-chaim\" data-id=\"2300670057\">בראשית</a> ב, ז. והיינו, דגופו של אדה\"ר לא נברא ע\"י מאמר אלקי בפ\"ע [כשאר הברואים], ועשה וייצר את האדם בהעפר שהי' מקודם (תו\"ח בראשית יט, ב)."],["268","16","ראה זח\"א לא, ב (בתוספתא). רנו, ב. וראה ד\"ה בראשית ברא תרנ\"א (סה\"מ תרנ\"א ע' פט ואילך)."],["269","17","בראשית א, ה. ב\"ר פ\"ג, ח. פרש\"י עה\"פ."],["270","18","המשך תער\"ב ח\"ב ע' תתקצח. סה\"מ תש\"ד ע' 222. ושם, שזה למעלה גם מהמציאות דאצילות."],["271","19","בראשית א, ג. וראה בהמשך תער\"ב ובסה\"מ תש\"ד שם, השייכות דאור שנברא ביום ראשון לענין \"הקב\"ה יחידי בעולמו\"."],["272","20","שמו\"ר רפל\"ה. וראה בהמצויין בהערה הבאה."],["273","21","מדרש תהלים עה\"פ תהלים כז, א. ירושלמי ברכות פ\"ח ה\"ו. ב\"ר פ\"ג, ו וביפ\"ת שם."],["274","22","ד\"ה וישב עת\"ר (סה\"מ עת\"ר ע' צד ואילך). מצה זו עזר\"ת (תש\"ז) פ\"ג (סה\"מ עזר\"ת ע' קנב ואילך. תש\"ז ע' 240 ואילך). ובכ\"מ."],["275","23","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380524\" data-slug=\"likkutei-torah\" data-id=\"4001380524\">לקו\"ת קרח נב, ג</a>. דרך מצותיך טו, סע\"א."],["276","24","בראשית ב, טו."],["277","25","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370021\" data-slug=\"torah-or\" data-id=\"3901370021\">תו\"א בראשית ה, סע\"ד</a>. ובכ\"מ."],["278","26","ראה ב\"ר פי\"ד, ז. פי\"ג, ג."],["279","27","בראשית ב, ד."],["280","28","ב\"ר פי\"ב, ו. שמו\"ר פ\"ל, ג."],["281","29","רות ד, יח."],["282","30","ראה שמו\"ר שם."],["283","31","ראה ד\"ה זה היום תרס\"ט (סה\"מ תרס\"ט ע' ה)."],["284","32","יבמות סא, רע\"א."],["285","33","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380908\" data-slug=\"likkutei-torah\" data-id=\"4001380908\">לקו\"ת נצבים מז, ב</a>."],["286","34","בראשית ב, ז."],["287","35","ראה לקו\"ת שם (מז, א), דמה שהוא ר\"ה הוא \"לא על בריאת גופו אלא על נפשו שנא' ויפח באפיו נשמת חיים\"."],["288","36","ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא רפ\"ב</a>."],["289","37","כ\"ה בתניא שם. אגה\"ת מהדו\"ק ע' תקט. אגה\"ק רסט\"ו. ובמאמרי אדה\"ז אתהלך-לאזניא ע' קה בשם <i>חז\"ל</i>. וראה הנסמן בלקוטי הגהות לתניא שם."],["290","38","ראה שבועות מח, סע\"א. וש\"נ."],["291","39","ד\"ה שמח תשמח תרנ\"ז ע' 93 (סה\"מ תרנ\"ז ע' רסט-ער). וידוע הפירוש ב\"יפה כח הבן מכח האב\", דגם זה ש\"<i>יפה</i> כח הבן\" הוא \"מכח (העצמי של) האב\" (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300231222\" data-slug=\"likkutei-sichot\" data-id=\"1300231222\">לקו\"ש חכ\"ג ע' 222</a>)."],["292","40","ראה יד, א."],["293","41","ב\"מ נט, ב."],["294","42","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380170\" data-slug=\"likkutei-torah\" data-id=\"4001380170\">לקו\"ת תזריע כב, ג</a>. ובכ\"מ."],["295","43","דב\"ר פ\"ב, יד."],["296","44","או\"ת (הוצאת קה\"ת) ב, סע\"ג. וראה המשך תער\"ב ח\"ב ע' תתקב ואילך."],["297","45","ב\"ר פ\"א, ד."],["298","46","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161500\" data-slug=\"likkutei-sichot\" data-id=\"1300161500\">לקו\"ש חט\"ז ע' 487</a>."],["299","47","ראה תניא שם: מוציא בנפיחתו בכח. אגה\"ת פ\"ד (צד, א). וראה המשך תרס\"ו ע' תצב."],["300","48","ד\"ה ואברהם זקן תרס\"ו (המשך תרס\"ו ע' פ ואילך)."],["301","49","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381011\" data-slug=\"likkutei-torah\" data-id=\"4001381011\">לקו\"ת האזינו עב, א</a>. דרושים לשמע\"צ פה, ריש ע\"ב."],["302","50","קהלת יב, ז."],["303","51","ראה ב\"ב נג, א. וש\"נ. רמב\"ם הל' מכירה פכ\"ה ה\"ד. הל' זכי' ומתנה פי\"א הכ\"ב."],["304","52","לקו\"ת האזינו שם, ב."],["305","53","סוטה ח, ב (במשנה). ושם ט, ב (במשנה): וכן לענין הטובה."],["306","54","להעיר מלקו\"ת במדבר ה, ריש ע\"ב."],["307","55","תהלים צה, ו. זהר ח\"א רכא, ב. ח\"ג קז, ב. תקו\"ז תנ\"ו (צ, ב). וראה פרקי דר\"א פי\"א. וראה אוה\"ת וארא ס\"ע רלו ואילך."],["308","56","ראה זהר ח\"א וח\"ג שם: אמר לון <i>אנא ואתון</i> בואו נשתחוה וכו'. ובפדר\"א: בואו <i>אני ואתם</i> נלך ונלביש גאות ועוז ונמליך עלינו מי שבראנו כו'."],["309","57","עש\"מ (לרמ\"ע מפאנו) מאמר אם כל חי ח\"ב סל\"ג (קצג, ב). של\"ה ג, א. כ, ב. שא, ב. ובכ\"מ. עבודת הקודש ח\"א פי\"ז ואילך. מאמרי אדהאמ\"צ דברים ח\"א ע' קכב. וש\"נ."],["310","58","בראשית א, כו. וידוע ש(\"בצלמנו\" קאי על הנשמה ו)\"כדמותנו\" קאי על הגוף – שערי אורה שבהערה הבאה. ובכ\"מ."],["311","59","שערי אורה ד\"ה רני ושמחי ספט\"ז (לא, סע\"א)."],["312","60","ראה ב\"ר פכ\"ד, ה. קה\"ר פ\"ג, יא (ב)."],["313","61","יתרו יט, ו."],["314","62","ראה בארוכה שיחת שבת תשובה ה'תשמ\"א."],["315","63","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380346\" data-slug=\"likkutei-torah\" data-id=\"4001380346\">ויק\"ר פ\"ב, ב</a>. מדרש שמואל פי\"ט. וראה לקו\"ת במדבר ט, ג."],["316","64","תפלת מוסף דר\"ה, מתהלים פא, ה."],["317","65","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380909\" data-slug=\"likkutei-torah\" data-id=\"4001380909\">לקו\"ת נצבים מז, ג</a>."],["318","66","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז (מט, א</a> ואילך). ובכ\"מ."],["319","67","ראה אגה\"ק ס\"ה (קט, א). ובכ\"מ."],["320","68","פע\"ח שכ\"ט (שער הלולב) פ\"א. שעה\"פ להאריז\"ל עה\"פ וישלח לב, כט. ספר הליקוטים להאריז\"ל עה\"פ ויחי מז, כח. שם מח, ב. ערכי הכינויים (לבעל סדה\"ד) מערכת ראש (ובדרך מצותיך טו, ב הובא בשם הזהר). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380505\" data-slug=\"likkutei-torah\" data-id=\"4001380505\">לקו\"ת שלח מח, ב</a>. מאמרי אדהאמ\"צ דברים ח\"ב ע' שצ. וש\"נ."],["321","69","בלקו\"ת נצבים שם: והוא נמשך ומתפשט עד בחי' אלקי יעקב יו\"ד עקב (ע\"ח שער ג (שער סדר אצי' למהרח\"ו) פ\"ב. פרדס שכ\"ג (שער ערכי הכינויים) בערכו) בחי' חיצוניות."],["322","70","תולדות כה, כו."],["323","71","ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450500\" data-slug=\"or-hatorah-hb\" data-id=\"8316450500\">אוה\"ת עקב ע' תק</a>."],["324","72","ראה עד\"ז לקו\"ת שם."],["325","73","ראה פע\"ח שער כד (שער ר\"ה) פ\"א ואילך. שער הכוונות שם."],["326","74","ר\"ה לא, א. תמיד בסופה."],["327","75","תהלים מזמור צג. פרקי דר\"א פי\"א."],["328","76","ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380924\" data-slug=\"likkutei-torah\" data-id=\"4001380924\">לקו\"ת נצבים נא, ב</a>."],["329","77","משא\"כ זכרונות ושופרות אומרים רק בתפלת מוסף. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300241636\" data-slug=\"likkutei-sichot\" data-id=\"1300241636\">לקו\"ש חכ\"ד ע' 621</a> הערה ד\"ה אַלגעמיינע נקודה."],["330","78","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380952\" data-slug=\"likkutei-torah\" data-id=\"4001380952\">לקו\"ת</a> דרושים לר\"ה נח, ב, דכל ראש השנה נקרא תחלת מעשיך \"שנמשך אור וחיות מחדש להתהוות העולם\", ובהמשך לזה מבאר ענין \"אמרו לפני מלכיות בראש השנה כדי שתמליכוני עליכם\", \"להיות נמשך גילוי החיות מדת מלכותו ית'\"."],["331","79","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380938\" data-slug=\"likkutei-torah\" data-id=\"4001380938\">לקו\"ת שם נד, סע\"ד</a>."],["332","80","לקו\"ת שם נג, ריש ע\"ד."],["333","81","יתרו כ, יא."],["334","82","זהר ח\"א רמז, א. ח\"ג צד, ריש ע\"ב. מאמרי אדמו\"ר האמצעי דברים ח\"א ע' רז. וש\"נ."],["335","83","זח\"ג צד, ב. וראה שו\"ת הרשב\"א ח\"א סי' תכג."],["336","84","תהלים לג, ו."],["337","85","אבות פ\"ה מ\"א."],["338","86","שער היחוד והאמונה בתחילתו."],["339","87","נוסח התפלה – סוף ברכת יוצר."],["340","88","רמו, ג."],["341","89","דברי הימים-א כט, יד."],["342","90","אגה\"ק ס\"כ (קל, ריש ע\"ב)."],["343","91","דשנת תרצ\"ט – נדפס בסה\"מ תרצ\"ט ע' 20 ואילך."],["344","92","ע\"ח שער יג (שער א\"א) פ\"ב, הובא בד\"ה עלה אלקים בתרועה תרצ\"ט (סה\"מ שם ע' 18)."],["345","93","בכמה ענינים דלקמן – ראה ד\"ה עלה אלקים בתרועה הנ\"ל (סה\"מ שם ע' 14 ואילך)."],["346","94","ראה בפי' הספרא דצניעותא להאריז\"ל בפ\"ק (דקי\"ט ע\"א), נעתק בלקו\"ת דרושים ליוה\"כ בסופן (עא, ריש ע\"ד), ד\"ה הנ\"ל (סה\"מ שם ע' 19) וז\"ל: ודע דההוא רישא דלאו רישא אשר שם חביון עוז העצמות הוא עצמו אינו משיג מה שיש בו, וזהו פי' דלא ידע ולא אתיידע מה דהוי ברישא דא כביכול כאדם שאינו משיג מהות הנשמה שבו."],["347","95","ראה סה\"מ ה'ש\"ת ע' 23, שההפרש בין כח המלוכה לשאר הכחות הוא (לא בכחות הנעלמים, כ\"א) ב<i>כחות הגלויים</i>, דההעלם של כח המלוכה (בבחינה זו) הוא העלם פנימי יותר, העלם שאינו במציאות."],["348","96","וגם <i>התעוררות</i> המדות אפשר להיות ע\"י בע\"ח (סה\"מ תרצ\"ט ריש ע' 16)."],["349","97","בחיי וישב לח, ל. שם ר\"פ בלק. כד הקמח ר\"ה (ב) ד\"ה ועוד (בהוצאת שעוועל – ע' שעט). ספר החיים (לאחי המהר\"ל) ספר גאולה וישועה פ\"ב. עמק המלך שער א (שער שעשועי המלך) רפ\"א. שעהיוה\"א רפ\"ז (פא, ב). אגה\"ק ס\"כ (קל, ב). וראה פרקי דר\"א פ\"ג. רבינו בחיי עה\"פ וירא כב, יג."],["350","98","המשך ר\"ה תרצ\"ה פי\"ט (סה\"מ קונטרסים ח\"ב שלג, א ואילך)."],["351","99","תהלים עט, יג*."],["352","100","שה\"ש ב, טז ובשהש\"ר שם."],["353","101","אוה\"ת ראה ס\"ע תשפד ואילך. סה\"מ תרכ\"ו ע' רנו. תרכ\"ז ע' רה. תר\"ל ע' רסט. ובכ\"מ."],["354","102","קהלת ד, ח."],["355","103","ישעי' מד, ו. מפסוקי מלכיות בתפלת מוסף דר\"ה."],["356","104","ראה סידור שער התקיעות רמו, ג. ובכ\"מ."],["357","105","המשך תער\"ב ח\"א פ\"ו (ע' י). ובכ\"מ.\n*) <i>להעיר שע\"פ המנהג לומר בכל יום הקאַפּיטל תהלים המתאים לשנות חייו (אגרות-קודש אדמו\"ר מהוריי\"צ ח\"א ע' לא</i>.<i> ח\"י ע' נג</i>.<i> וראה גם מאמרי אדה\"ז הקצרים ע' שמא</i>.<i> סה\"מ תשכ\"א ע' 231. סה\"מ י\"א ניסן ח\"א ע' 1 ואילך) – התחילו בי\"א ניסן העבר (תש\"מ) לומר מזמור עט שבתהלים</i>. <b>המו\"ל</b>."],["358","106","רמד, ג."],["359","107","ראה תנחומא בחוקותי ג. נשא טז. ב\"ר ספ\"ג. במדב\"ר פי\"ג, ו. ובכ\"מ."],["360","108","ד\"ה מי יתנך תקס\"ה (סה\"מ תקס\"ה ח\"א ע' תפט. ועם הגהות – ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770311\" data-slug=\"or-hatorah-hb\" data-id=\"8316770311\">אוה\"ת שה\"ש כרך ב ע' תרעט</a> ואילך). אוה\"ת בלק ע' תתקצז. סה\"מ תרס\"ב ע' שלה. תרע\"ח ע' קצג. המשך תרס\"ו ס\"ע ג. שם ע' תמה. ובכ\"מ."],["361","109","<a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא רפל\"ו</a>."],["362","110","שער האמונה לאדמו\"ר האמצעי ספכ\"ז (מח, א). וראה גם מאמרי אדהאמ\"צ במדבר ח\"א ס\"ע קעא, ובהנסמן ב\"מילואים להמראי מקומות\" שם (ע' שח)."],["363","111","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830007\" data-slug=\"or-hatorah-hb\" data-id=\"8158830007\">אוה\"ת בלק שם</a>. המשך תרס\"ו ס\"ע ז. ובכ\"מ."],["364","112","ד\"ה מי כמוכה תרכ\"ט – נדפס בסה\"מ תרכ\"ט ע' קמג ואילך (וראה שם ע' קמח)."],["365","113","\"היום יום\" כח תמוז. הוספות לסה\"מ תרנ\"ט ע' רכב. אגרות-קודש לכ\"ק אדמו\"ר מהוריי\"צ נ\"ע כרך ו ע' רסז."],["366","114","רמב\"ם ריש הל' יסוה\"ת."],["367","115","בשלח מג, ג ואילך. וכ\"ה גם בד\"ה ולקחתם לכם תרס\"א (סה\"מ תרס\"א ע' קצא ואילך). וראה גם שערי אורה ד\"ה יביאו לבוש מלכות פמ\"ה-נא. ס' מאמרי אדה\"ז על מארז\"ל ס\"ע תפג."],["368","116","רמב\"ם הל' תשובה פ\"ג ה\"ד, מקידושין מ, ריש ע\"ב."],["369","117","טור או\"ח הל' ר\"ה סתקפ\"א, מירושלמי ר\"ה פ\"א ה\"ג."],["370","118","ר\"ה טז, ב."],["371","119","תהלים קיח, ה."],["372","120","סה\"מ תרכ\"ז ע' תו."],["373","121","תהלים פט, טז. – ופסוק זה אומרים מיד לאחרי תק\"ש."],["374","122","ראה לקוטי לוי\"צ אגרות-קודש ע' רי: שאם שבפרט הכתיבה היא בר\"ה והחתימה ביוהכ\"פ כו' אך בכלל הן הכתיבה והן החתימה נעשית בר\"ה כו'. ולהעיר מר\"ה שם: <i>בר\"ה</i> . . צדיקים גמורין נכתבין <i>ונחתמין</i> לאלתר לחיים. וראה בהערות למכתב ח\"י אלול ה'תשמ\"ו בסופו (נדפס ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300291548\" data-slug=\"likkutei-sichot\" data-id=\"1300291548\">לקו\"ש חכ\"ט ע' 533</a>). וש\"נ."],["375","123","כסיום וחותם הרמב\"ם שם: וגרם . . תשועה והצלה."]]],[1500360007,"<h3>בס\"ד. ליל ערב ראש השנה ה'תשמ\"ב<sup data-n=\"376\">*</sup></h3>\n<b>זה</b> היום תחלת מעשיך זכרון ליום ראשון<sup data-n=\"377\">1</sup>, ומדייק אדמו\"ר הצ\"צ<sup data-n=\"378\">2</sup> [בעל יום ההולדת דערב ראש השנה<sup data-n=\"379\">3</sup>], דלכאורה יש כאן סתירה מרישא לסיפא, דפירוש זה היום תחלת מעשיך (תחלה ממש) הוא שבראש השנה (זה היום) הוא התחלת התהוות כל העולמות, היינו שבכל ראש השנה מתהווים כל העולמות מחדש<sup data-n=\"380\">4</sup> כמו שהי' בפעם הראשונה, ופירוש זכרון ליום ראשון הוא שראש השנה הוא רק זכרון ליום ראשון. ומבאר בזה, דבראש השנה ישנם שני הענינים, שהוא תחלת מעשיך ושהוא זכרון ליום ראשון. ומזה שבתחלה אומרים שראש השנה הוא תחלת מעשיך ואח\"כ <i>מוסיפים</i> שהוא זכרון ליום ראשון, מוכח, דזה שראש השנה הוא זכרון ליום ראשון הוא נעלה יותר<sup data-n=\"381\">5</sup> מזה שהוא תחלת מעשיך.\nב) <b>ויובן</b> זה בהקדים הביאור בזה שאומרים על היום דראש השנה זה היום תחלת מעשיך, דידועה השאלה בזה<sup data-n=\"382\">6</sup>, הרי בכ\"ה באלול נברא העולם<sup data-n=\"383\">7</sup>, וראש השנה הוא יום ברוא אדם הראשון שהוא יום וא\"ו למע\"ב שבו הי' <i>סוף וגמר</i> הבריאה, ואיך אומרים על יום זה שהוא <i>תחלת</i> מעשיך. והביאור בזה, דתכלית הכוונה דבריאת העולם הוא שיהי' בו גילוי אלקות. ועד שע\"י כל פרט ופרט שבהבריאה יתגלה כבודו של הקב\"ה, כמארז\"ל (בסיום וחותם דמס' אבות<sup data-n=\"384\">8</sup>) כל מה שברא הקב\"ה בעולמו לא בראו אלא לכבודו. וגילוי זה נעשה ע\"י עבודת האדם. ולכן אומרים על היום דראש השנה זה היום תחלת מעשיך, כי ענין זה (שיהי' גילוי אלקות בעולם), שהוא המכוון דמעשיך, הותחל ביום ברוא האדם<sup data-n=\"385\">9</sup>. דנוסף לזה שאז דוקא נעשית האפשרות שיהי' גילוי אלקות בעולם, נעשה אז כן גם בפועל, כמארז\"ל<sup data-n=\"386\">10</sup> שאדם הראשון (ביוםשנברא) הכריז לכל הברואים בואו<sup data-n=\"387\">11</sup> נשתחוה ונכרעה נברכה לפני ה' עושינו, וכולם ענו ואמרו ה'<sup data-n=\"388\">12</sup> מלך גאות לבש. ויש לומר, דזה שאומרים זה היום תחלת מעשיך (הגם שראש השנה הוא לכאורה רק התחלת המכוון דמעשיך), הוא, כי מעשה מורה על השלימות, דכמו שבאדם השלימות דכל ענין הוא כשבא בפועל דוקא, עד\"ז הוא גם למעלה [ואדרבא, מזה נשתלשל כן גם באדם התחתון<sup data-n=\"389\">13</sup>, אדם אדמה לעליון<sup data-n=\"390\">14</sup>], שהשלימות דכל סדר ההשתלשלות היא בעשי' דוקא. וזהו זה היום תחלת מעשיך, דמעשה מורה על השלימות, שהיום דראש השנה יום ברוא אדם הראשון, הוא התחלת שלימות הבריאה. ויש לומר דזהו גם הטעם על זה שראש השנה נקרא כאן (בהמשך לתחלת מעשיך) בשם זה היום, דזה היום הוא גילוי בתכלית [זה מורה על גילוי<sup data-n=\"391\">15</sup> כמו מראה באצבעו ואומר זה<sup data-n=\"392\">16</sup>, ויום מורה על גילוי<sup data-n=\"393\">17</sup> כמ\"ש<sup data-n=\"394\">18</sup> ויקרא אלקים לאור יום, וזה היום (ב' לשונות של גילוי) הוא תכלית הגילוי], וזהו זה היום תחלת מעשיך, דזה שראש השנה הוא תחלת <i>מעשיך</i>, התחלת <i>שלימות</i> הבריאה, הוא שאז התחיל ענין הגילוי (דע\"י עבודתו של אדם הראשון נעשה גילוי אלקות בעולם, כנ\"ל), ענין זה היום<sup data-n=\"395\">19</sup>.\nג) <b>וביאור</b> הענין (שראש השנה, יום ברוא אדם הראשון, הוא תחלת מעשיך) בעומק יותר, הנה ידוע שעבודת האדם בכחה לשנות גם את העבר<sup data-n=\"396\">20</sup>. ומזה מובן (במכ\"ש) בנוגע לעבודתו של אדם הראשון שהי' יציר כפיו של הקב\"ה<sup data-n=\"397\">21</sup>, שהעילוי שפעל בכל הנבראים ע\"י הכרזתו בואו נשתחוה גו' לפני ה' עושינו הוא גם בנוגע למציאותם שלפני עבודתו. דכיון<sup data-n=\"398\">22</sup> שכוונת הבריאה <i>מלכתחילה</i> היא שהאדםע\"י עבודתו ימשיך גילוי אלקות בעולם<sup data-n=\"399\">23</sup>, לכן, לאחרי שנמשך בעולם גילוי אלקות נעשה עי\"ז עילוי גם במציאות העולם שהי' לפנ\"ז, ובפרט שענינו הוא הכנה להגילוי שנמשך ע\"י עבודת האדם.\n<b>וזהו</b> מה שהיום דראש השנה, יום ברוא אדם הראשון, הוא תחלת מעשיך, דפירוש הפשוט (ואין ענין יוצא מידי פשוטו) דתחלת מעשיך הוא התחלת כל המעשים, גם המעשים שהיו בה' ימים הראשונים דמע\"ב (כולל גם הזמן דימים אלו<sup data-n=\"400\">24</sup>), כי ע\"י עבודתו של אדם הראשון נעשה עילוי וחידוש גם בהמציאות דעולם שהי' לפני זה, ולכן זה היום הוא תחלת מעשיך, ההתחלה של כל הבריאה.\n<b>וכמו</b> שבראש השנה בפעם הראשונה, ביום ברוא אדם הראשון, נעשה שלימות הבריאה (מעשיך), ובאופן של חידוש (<i>תחלת</i> מעשיך), עד\"ז הוא בראש השנה שבכל שנה ושנה, דע\"י שישראל מכתירים את הקב\"ה שיהי' מלך עליהם ועל כל העולם, נעשה שלימות וחידוש בכל הבריאה, ועד שעי\"ז נעשה שלימות וחידוש גם למעלה, כתורת הה\"מ<sup data-n=\"401\">25</sup> ואדמו\"ר הזקן<sup data-n=\"402\">26</sup> על מאמר המשנה<sup data-n=\"403\">27</sup> דע מה למעלה ממך, דכל הענינים שלעלה הם ממך.\nד) <b>ולאחרי</b> אומרו זה היום תחלת מעשיך מוסיף זכרון ליום ראשון, דזה שראש השנה הוא זכרון ליום ראשון הוא נעלה יותר מזה שהוא תחלת מעשיך. כי תחלת מעשיך הוא השלימות והחידוש דהבריאה שנעשו ע\"י עבודת האדם (כנ\"ל), דההמשכה מלמעלה שעי\"ז היא רק מבחי' שאתעדל\"ת מגעת לשם. משא\"כ ענין יום ראשון הוא (כמו שמבאר הצ\"צ בדרוש הנ\"ל<sup data-n=\"404\">28</sup>) שההמשכה אז היתה מצד עצמו, כי לא הי' עדיין מי שיעורר כמ\"ש<sup data-n=\"405\">29</sup> ואדם אין גו'<sup data-n=\"406\">30</sup> [היינו, דלא רק שלא הי' אתערותא דלתתא בפועל אלא שלא הי' שייך כלל שיהי' אתעדל\"ת], וההמשכהאז היתה מצד חסדו ית', כי<sup data-n=\"407\">31</sup> חפץ חסד הוא. והיינו, דנוסף לזה שההמשכה עכשיו (ע\"י אתעדל\"ת) היא בחי' דין ומשפט וההמשכה אז היתה מצד חסדו ית'&lt;28&gt;, עולם חסד יבנה<sup data-n=\"408\">32</sup>, הנה חסד זה (דיום ראשון) הוא למעלה לא רק מהחסד כמו שהוא במדות אלא גם למעלה משרשו כמו שהוא במוחין וכו', כי ענינו הוא (לא חסד אלא) חפץ חסד, ענין החפץ (תענוג<sup data-n=\"409\">33</sup>), אלא שהחפץ הוא שיהי' חסד, ומזה נמשך להיות עולם חסד יבנה, דמחפץ זה נבנה החסד שממנו נבנה העולם<sup data-n=\"410\">34</sup>.\n<b>ויש</b> לומר, שהטעם הפנימי על זה שיום הראשון דהבריאה נק' בשם יום ראשון הוא, כי הגילוי דחפץ חסד שהאיר ביום זה הוא אור וגילוי (יום הוא אור וגילוי) הראשון, שהוא הסיבה והשרש להמשכת מדת החסד שממנה נתהוו כל העולמות.\n<b>וזהו</b> זכרון ליום ראשון, דבכל ראש השנה, ע\"י שמזכירים אופן ההתהוות שהיתה ביום הראשון, שהאיר אז הגילוי דחפץ חסד, עי\"ז ממשיכים<sup data-n=\"411\">35</sup> גילוי זה. וזהו שהענין שראש השנה הוא זכרון ליום ראשון הוא נעלה יותר מזה שר\"ה הוא תחלת מעשיך, כי תחלת מעשיך הוא מה שנמשך ע\"י אתערותא דלתתא, ויום ראשון (הגילוי דחפץ חסד) הוא אור וגילוי הראשון שהוא השרש והסיבה לכל סדר ההשתלשלות (מעלה ומטה), והוא עצמו הוא למעלה מהגדר דמעלה ומטה (עילא ותתא).\nה) <b>והנה</b> זה שישראל ע\"י עבודתם (שמזכירים אופן ההתהוות שהיתה ביום הראשון) ממשיכים הגילוי הנ\"ל מגיע בשרשו עד בחפץ חסד מצד עצמו ואין אתעדל\"ת מגעת לשם, כי השרש דישראל הוא למעלה יותר גם מהענין דחפץ חסד. וכידוע בענין במי נמלך בנשמותיהן של צדיקים<sup data-n=\"412\">36</sup> (ועמך כולם צדיקים<sup data-n=\"413\">37</sup>), דזה שנתעורר כביכול להיות חפץ חסד הוא מצד זה שעלה במחשבה<sup data-n=\"414\">38</sup> (מחשבה עצמית, שלמעלה מהגילוי דחפץ חסד) שעתידין ישראל לקיים תומ\"צ ולעשות דירה לו ית' בתחתונים<sup data-n=\"415\">39</sup>. ולכן, ע\"י העבודה דישראל נמשך [ונעשה<sup data-n=\"416\">40</sup>] גם הגילוי דחפץ חסד. ומזה מובן, שהגילוי דחפץ חסד שנעשה עכשיו ע\"י מעשינו ועבודתינו, הוא נעלה יותר מכמו שהי' גילוי זה בתחלת הבריאה, כי ע\"י מעשינו ועבודתינו נעשה נחת רוח למעלה, נח\"ר לפני שאמרתי ונעשה רצוני<sup data-n=\"417\">41</sup>, דנח\"ר ותענוג זה (שנעשה רצוני,ע\"י ישראל) הוא בעצמותו ית' (נח\"ר <i>לפני</i>) שלמעלה מהתענוג דחפץ חסד, וע\"י שהגילוי דחפץ חסד נתעורר ונמשך ע\"י עבודת האדם, נמשך בו הנח\"ר והתענוג דנעשה רצוני<sup data-n=\"418\">42</sup>. וזהו גם הטעם (הפנימי) על זה שלפני שאומרים שראש השנה הוא זכרון ליום ראשון אומרים שהוא תחלת מעשיך, דזכרון ליום ראשון שלאחרי קדימת הענין דתחלת מעשיך (המשכת הגילוי דחפץ חסד שלאחרי קדימת העבודה) הוא נעלה יותר מכמו שהוא מצד עצמו, כמו שהי' בתחלת הבריאה.\nו) <b>והגם</b> שגם הגילוי דחפץ חסד שהי' תחלה, שרש המשכתו הוא מהתענוג עצמי בעבודתם של ישראל [וכנ\"ל, שזהו הסיבה לזה שנתעורר להיות חפץ חסד], מ\"מ, ע\"י עבודתם של ישראל בפועל, ניתוסף עילוי נעלה יותר, וכמובן מזה שבכדי שתושלם הכוונה דנתאוה הקב\"ה להיות לו ית' דירה בתחתונים<sup data-n=\"419\">43</sup> הוצרך להיות בריאת העולמות בפועל, עד לעולם הזה התחתון<sup data-n=\"420\">44</sup>, ואח\"כ הוצרך להיות מתן תורה שאז דוקא נעשה התוקף דקיום העולם כמארז\"ל<sup data-n=\"421\">45</sup> עה\"פ<sup data-n=\"422\">46</sup> ארץ יראה ושקטה, ואח\"כ צ\"ל עבודת האדם (שלאחרי מ\"ת) בפועל, לימוד התורה, ובאופן דגדול לימוד שמביא לידי מעשה<sup data-n=\"423\">47</sup> בקיום המצוות בפועל – אף שכל זה הי' בידיעתו ובמחשבתו ית' גם מקודם (ומחשבה זו היא הסיבה לזה שנתעורר להיות חפץ חסד) – כי המחשבה שהיתה מקודם היא מחשבה עצמית שבעצמותו ית' שלמעלה מגילוי, וזה שמצד מחשבה זו נעשה ההתעוררות דחפץ חסד הוא רק באופן דהבדלה [היינו, שהמחשבה נשארה בעצמותה ולא נמשכה בהענין דחפץ חסד<sup data-n=\"424\">48</sup>, והענין דחפץ חסד שנעשה עי\"ז הוא רק החפץ והתענוג בחסד, גילויים], וע\"י עבודת האדם בפועל, נעשה גילוי העצמות<sup data-n=\"425\">49</sup>, דירה לו ית', לו לעצמותו<sup data-n=\"426\">50</sup>.\nז) <b>וזהו</b><sup data-n=\"427\">51</sup> שהשלימות דעולם שתהי' לע\"ל, אלה תולדות פרץ<sup data-n=\"428\">52</sup> תולדות מלא<sup data-n=\"429\">53</sup>, תהי' נעלית יותר מהשלימות שהיתה בתחלת הבריאה, אלה תולדות השמיםוהארץ בהבראם<sup data-n=\"430\">54</sup> תולדות מלא&lt;53&gt;, עולם על מילואו נברא<sup data-n=\"431\">55</sup>, שהשלימות דעולם כמו שהוא מצד הבריאה [אלה תולדות (מלא) גו' <i>בהבראם</i>, עולם על מילואו <i>נברא</i>] היא במדידה והגבלה. דכיון שהגדר דעולם הוא מדידה והגבלה, הרי מובן, שגם השלימות שלו היא במדידה והגבלה. והגם שהבריאה היתה מצד זה שחפץ חסד הוא, שהוא למעלה מהגבלה (כנ\"ל סעיף ד), הרי הענין דחפץ חסד הוא רק הסיבה להבריאה, אבל הבריאה עצמה היתה באופן דהשתלשלות מעלה ומטה&lt;42&gt;. משא\"כ השלימות שתהי' לע\"ל, מכיון שנעשית ע\"י עבודת האדם שעי\"ז נמשך גילוי התענוג העצמי שבעצמותו ית' (שאין שייך בו שום גדר), לכן<sup data-n=\"432\">56</sup> השלימות דעולם לע\"ל תהי' למעלה ממדידה והגבלה, אלה תולדות פרץ, דענין פרץ [שנקרא כן על שם מה פרצת עליך פרץ<sup data-n=\"433\">57</sup>] הוא שפורץ כל המדידות וההגבלות.\n<b>ושלימות</b> זו שנעשית ע\"י עבודת האדם הותחלה ביום הששי למע\"ב כשנברא האדם והתחיל לעבוד את האדמה, בתחלה את האדמה שבהאדם גופא, וייצר ה' אלקים את האדם עפר מן האדמה<sup data-n=\"434\">58</sup>, ואח\"כ ועי\"ז גם את האדמה שמחוצה לו, היינו כל סדר ההשתלשלות (דהכל הי' מן העפר<sup data-n=\"435\">59</sup>), וכנ\"ל שפעל בכל הבריאה הענין דנשתחוה ונכרעה נברכה לפני ה' עושינו. ובפרט לאחרי יום הששי דמ\"ת [שאז נעשה עילוי ושלימות ביום הששי דמעשה בראשית<sup data-n=\"436\">60</sup>], שעבודת האדם והפעולה בעולם (שנעשית ע\"י עבודתו) שלאחרי מ\"ת היא באופן נעלה יותר. ובפרט בראש השנה, זה היום תחלת מעשיך, שהוא דוגמת תחלת מעשיך שנעשה ע\"י עבודת אדם הראשון בראש השנה הראשון, ועוד למעלה יותר, ובראש השנה גופא הנה בכל שנה ושנה ענין זה הוא באופן נעלה יותר, כהציווי<sup data-n=\"437\">61</sup> מעלין בקודש, ועד שבכל ראש השנה נמשך אור חדש עליון יותר שלא הי' מאיר עדיין מימי עולם אור עליון כזה<sup data-n=\"438\">62</sup>, ועד להגאולה שאז יעלה הפורץ לפנינו<sup data-n=\"439\">63</sup> ויפרוץ כל המדידות וההגבלות.\nח) <b>והנה</b> ג' ענינים הנ\"ל הנמשכים בראש השנה (תחלת מעשיך, זכרון ליום ראשון (הגילוי דחפץ חסד), והמשכת גילוי תענוג העצמי שלמעלה מחפץ חסד) הם (ע\"ד) ג' הענינים דמלכיות זכרונות ושופרות. והענין הוא, דמלכיות הם בבחי' ממכ\"ע (כמבואר בדרוש הנ\"ל דהצ\"צ<sup data-n=\"440\">64</sup>), אור שבערך העולמות שאתעדל\"ת מגעתלשם, וזהו אמרו לפני מלכיות כדי שתמליכוני עליכם<sup data-n=\"441\">65</sup>, דכמו שענין המלוכה למטה נעשה ע\"י העם כמ\"ש<sup data-n=\"442\">66</sup> שום תשים עליך מלך, עד\"ז הוא במלכותא דרקיעא<sup data-n=\"443\">67</sup>, דזה שהקב\"ה נעשה מלך הוא ע\"י שתמליכוני, שישראל מקבלים עליהם עול מלכות שמים ומבקשים מלוך כו' [דבבקשה וקבלה זו נכללת גם הבקשה שיגזור עלינו גזירות וקבלת עול מצוות<sup data-n=\"444\">68</sup>, לקיים כל מה שיגזור ויצוה בדרך קבלת עול, וכהנוסח דברכת (כל) המצוות אשר קדשנו במצותיו וצונו, שקיום המצוות הוא מצד הציווי והגזירה<sup data-n=\"445\">69</sup>], שעי\"ז נעשה הקב\"ה למלך על כל ישראל, שתמליכוני עליכם, ועל ידם גם מלך על כל הארץ. וזה שע\"י העבודה דישראל מעוררים ענין המלכות הוא, כי ענין המלכות הוא (בכללות) באור הממלא, שאתערותא דלתתא מגעת לשם. וע\"ד הענין דתחלת מעשיך. והגם שבראש השנה חוזרים כל הדברים לקדמותם, והמשכת המלכות דראש השנה היא מעצמות אוא\"ס שלמעלה מענין המלכות [וזה שבכחם של ישראל להמשיך מעצמות אוא\"ס הוא לפי שהם מושרשים בהעצמות<sup data-n=\"446\">70</sup>, וע\"ד המבואר בלקו\"ת<sup data-n=\"447\">71</sup>, דזה שביכלתם של ישראל לעורר התגלות מלכותו ית' מעצמותו ומהותו הוא מצד הברית אשר כרת ה' עמנו להיות לו לעם<sup data-n=\"448\">72</sup>, שיהיו דומים להמלך, אנשים כמותו], הנה זהו ששרש ההמשכה הוא מעצמות אוא\"ס, אבל ההמשכה עצמה היא שנמשכת ענין המלכות<sup data-n=\"449\">73</sup>, שבכללות הוא ממכ\"ע. וענין זכרונות הוא באוא\"ס הסוכ\"ע<sup data-n=\"450\">74</sup> שקדוש ומובדל מעולמות. כי ענין הזכרון אינו שייך אלא בדבר הרחוק, במקום או במעלה, ועד שאין הדבר תופס מקום לגבי'. וזהו דזכרונות הוא בעצמות אוא\"ס דכולא קמי' כלא חשיבא<sup data-n=\"451\">75</sup>. וע\"ד הענין דזכרון ליום ראשון<sup data-n=\"452\">76</sup>. אלא שאעפ\"כ גם ענין הזכרון שייך דוקא על דבר שישנו במציאות גם לפני שזוכרים עליו (אלא שהדבר הוא רחוק ממנו במקום ובמעלה). וזהו מה שזכרונות הוא בבחינת סובב, כי גם לגבי סובב יש המציאות דעולמות (ורק שהם במקום רחוק, דכלא ממש חשיבי)<sup data-n=\"453\">77</sup>.<b>וענין</b> שופרות הוא כמבואר בדרוש הנ\"ל דהצ\"צ<sup data-n=\"454\">78</sup> דקול השופר הוא קלא פנימאה שמבחי' פנימיות הלב, דמזה מובן, שההמשכה שע\"י שופר היא מפנימיות ועצמות אוא\"ס שלמעלה גם מסובב<sup data-n=\"455\">79</sup>. וכמ\"ש<sup data-n=\"456\">80</sup> לך אמר לבי בקשו פני את פניך הוי' אבקש, דע\"י בקשו פני, הצעקה דפנימיות הלב, עי\"ז את פניך הוי' אבקש, ההמשכה מפנימיות ועצמות אוא\"ס. והוא ע\"ד המשכת וגילוי תענוג העצמי שלמעלה גם מהענין דחפץ חסד. ובפרט ע\"פ הידוע<sup data-n=\"457\">81</sup> דשופר (מלשון שפרו מעשיכם<sup data-n=\"458\">82</sup>) הוא תענוג, ושבחי' התענוג דשופר הוא מקור התענוגים, ועד שעשוע המלך בעצמותו.\nט) <b>והנה</b> ג' ענינים אלו (ממלא סובב ועצמות אוא\"ס) יש כביכול דוגמתם באדם. דכיון שאדם הוא אדמה לעליון, לכן יש בו דוגמת כל הענינים שלמעלה. דכחות הפנימיים שבאדם, שהם בגילוי באברי הגוף, הם דוגמת אור הממלא שמתלבש ומשפיע בעולמות בבחי' גילוי<sup data-n=\"459\">83</sup>. וכחות המקיפים שבאדם, וכמו הרצון שפועל בכל הכחות והאברים אלא שאינו בגילוי בהם<sup data-n=\"460\">84</sup>, הם דוגמת אור הסובב<sup data-n=\"461\">85</sup> שהשפעתו בעולמות הוא בהעלם<sup data-n=\"459\">83</sup>. ועצם הנפש שלמעלה גם מכחות המקיפים הוא דוגמת עצמות אוא\"ס. ומזה מובן, שהעבודות דמלכיות וזכרונות הם בכחות (הפנימיים ומקיפים) הנפש, והעבודה דשופרות היא בעצם הנפש. וכנ\"ל, שקול השופר הוא קלא פנימאה שמפנימיות הלב. והנה הגם שענין השופר הוא צעקה פנימית שמפנימיות הלב, מ\"מ, צריכה להיות הצעקה ע\"י תקיעה בשופר גשמי דוקא, שופר של כבש ואיל, חי (שלמטה ממדבר), כמבואר בדרוש הנ\"ל דהצ\"צ<sup data-n=\"462\">86</sup>, ויתירה מזו, שקרן השופר צ\"ל תלוש (מהכבש והאיל), דומם. דמזה מובן גם בעבודה הרוחנית, שהעבודה דשופר עם היותה מפנימיות ועצמות הנפש, צריכה להיות (גם) בהדומם שבאדם. ועי\"ז דוקא מתעוררת ומתגלית הצעקה הפנימית שמפנימיות הלב. וע\"ד הידוע<sup data-n=\"463\">87</sup> בענין דצח\"מ שבאדם שדוקא הדומם שבאדם שייך להמדבר שבו, עד\"ז הוא גם בהמקיפים דאדם שלמעלה מחילוקי דרגות דצח\"מ (בדוגמת הסובב שלמעלה מחילוקי הדרגות דהשתלשלות), וגם בעצם הנפש (שלמעלה גם מכחות המקיפים), שהתעוררותם והתגלותם היא דוקא ע\"י הדומם שבאדם. ולכן צריך לתקוע בשופר גשמי דוקא, דומם, כי הגילוי דקלא פנימאה שמפנימיות הלב הוא לא בהרצון שבראש (גלגלתא), ועאכו\"כ שאינו מתגלה ומתלבש בחב\"ד שבמוחין או במדותשבלב, אלא דוקא בהדומם שבו, העבודה דקבלת עול, דומם שבנפש האדם [וע\"ד הידוע<sup data-n=\"464\">88</sup> בענין יראה תתאה שבה דוקא מתגלה בחינת יראה עילאה], ולמטה יותר – ענין המעשה (ששייך להדומם דגוף האדם), תקיעה בשופר גשמי. ועד שענין זה (תקיעת שופר במעשה) דוקא היא המצוה היחידה – מצות היום דראש השנה, כמארז\"ל<sup data-n=\"465\">89</sup> מצות היום בשופר. ובזה יובן מאמר כ\"ק מו\"ח אדמו\"ר<sup data-n=\"466\">90</sup> בשם אדמו\"ר הזקן (בקשר לראש השנה) \"מען האָט גאָר קיין השגה ניט, ווי עס איז טייער באַ השי\"ת דער גוף פון אַ אידן\", דאין הכוונה בזה <i>שאפילו</i> הגוף הוא יקר אצל השי\"ת, אלא <i>שעיקר</i> היוקר הוא בהגוף. דזהו שאומר \"מען האָט גאָר קיין השגה ניט\", כי יוקר הגוף הוא למעלה מהשגה והבנה, כי יוקר הגוף דישראל (דומם) הוא מצד העצמות<sup data-n=\"467\">91</sup>.\n<b>ויש</b> להוסיף, דכיון שנתאוה הקב\"ה להיות לו ית' דירה בתחתונים, שגם העולם הגשמי (שמחוץ להאדם) יהי' דירה לו ית', לכן אין מספיק מה שקלא פנימאה (בחינת פנימיות הלב) מתגלה על ידי הדומם (קבלת עול, ומעשה) שבאדם, אלא צריך שגילוי קול זה (קלא פנימאה, שמבחינת פנימיות הלב) יהי' על ידי שופר של בהמה, ובזה גופא, כמו שהוא נפסק ממקום חיותו, דומם, דעי\"ז דוקא פועל האדם (גם) בהעולם (ובדומם שבו) שיהי' דירה לו ית'. בדוגמת כמו שהי' בראש השנה בפעם הראשונה, שאדם הראשון פעל (גם) בהנבראים (שמחוצה לו) שיהי' בהם נשתחוה ונכרעה נברכה לפני ה' עושינו. וענין זה דשופר [תקיעת שופר בגשמיות, בשופר של בהמה, וכמו שנעשה דומם] הוא מלשון שפרו מעשיכם, פנימיות התענוג (כנ\"ל), כי עי\"ז דוקא נשלמת הכוונה דנתאוה הקב\"ה. וכ\"ה גם בפשטות הענינים שהנח\"ר שלמעלה מזה שנעשה רצוני [דנח\"ר זה הוא פנימיות התענוג, שלמעלה מהתענוג דחפץ חסד (כנ\"ל סעיף ג)] הוא מקיום המצוה כפשוטה בגשמיות (בשופר דומם של בהמה), נעשה רצוני.\nיו\"ד) <b>והנה</b> הנח\"ר והתענוג דלמעלה מזה שנעשה רצוני הוא בכל השנה, אלא שבראש השנה הוא עיקר מצות היום וכו', והעילוי שבראש השנה הוא לפי אופן העבודה והנח\"ר שעי\"ז במשך כל השנה. דכשישראל מוסיפים (בעבודתם, ובמילא) בהנח\"ר במשך כל השנה, ניתוסף גם בהנח\"ר מזה שנעשה רצוני בראש השנה. ומכיון שכל אחד ואחד מישראל פעל בודאי בשנה שעברה כל הענינים, כל ישראל בחזקת כשרות הם<sup data-n=\"468\">92</sup>, דענין החזקה הוא עמוד חזק בתורה, ובפרט לאחרי העבודה דחודש אלול, ובאלול גופא לאחרי ח\"י אלול שמכניס חיות בכל העניניםדחודש אלול<sup data-n=\"469\">93</sup> [נוסף לזה שהוא יום הבהיר שבו נולדו שני המאורות הגדולים<sup data-n=\"470\">94</sup>], שאז החזקת כשרות דכאו\"א מישראל היא ביתר שאת ויתר עוז, ומיום ליום (בהימים שמח\"י אלול ואילך) הכשרות דכאו\"א מישראל היא באופן דהולך ומוסיף ואור, ובפרט בימי הסליחות, הרי ברור שאתם נצבים היום כולכם<sup data-n=\"471\">95</sup>, כמ\"ש בהסדרה שקראו בשבת דמיני'<sup data-n=\"472\">96</sup> מתברכין כולהו יומין, וכפירוש הבעש\"ט<sup data-n=\"473\">97</sup> דהיום קאי על ראש השנה<sup data-n=\"474\">98</sup> שהוא יום הדין, ואתם (כאו\"א מישראל, כולכם) נצבים קיימים ועומדים שזוכים בדין, דענין זה (הזכי' בדין) יש כבר בערב ראש השנה, שלכן בערב ראש השנה לובשים לבנים ומתעטפים לבנים<sup data-n=\"475\">99</sup> וכו', והולכים בשמחה, ובשמחה גדולה<sup data-n=\"476\">100</sup>, להכתיר את המלך בראש השנה, כי כבר בערב ראש השנה ישנם כל ההכנות הדרושות, דשמחה פורצת כל הגדרים<sup data-n=\"477\">101</sup>. וזה נעשה גם הכנה קרובה ליעלה הפורץ לפנינו בקרוב ממש, שבהכתיבה וחתימה טובה לשנה טובה ומתוקה יהי' ויוכלל ויודגש שהשנה תהי' שנת גאולה, גאולה האמיתית והשלימה ע\"י משיח צדקנו, יעלה הפורץ לפנינו, ובמהרה בימינו ממש.\n**********",[["376","*","יצא לאור ב<b>קונטרס ראש השנה – תשמ\"ט</b>, \"לקראת ראש-השנה . . <i>ג' דסליחות</i>,<i> שנת הקהל</i>,<i> שנת תשמ\"ח</i>\"."],["377","1","תפלת מוסף דר\"ה, מר\"ה כז, א."],["378","2","בד\"ה והי' ביום ההוא יתקע בשופר גדול תר\"א, נדפס באוה\"ת ר\"ה כרך ה ע' ב'עז ואילך. וראה גם ד\"ה זה (בשינויים) ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380951\" data-slug=\"likkutei-torah\" data-id=\"4001380951\">לקו\"ת ר\"ה נח, א</a> ואילך."],["379","3","\"היום יום\" כט אלול, ערב ר\"ה. ועוד."],["380","4","כי החיות שנמשך בכל ר\"ה (כולל גם ר\"ה הראשון שבתחלת הבריאה) הוא רק על שנה אחת (<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380952\" data-slug=\"likkutei-torah\" data-id=\"4001380952\">לקו\"ת שם נח, ב</a>. אוה\"ת שם ע' ב'עט), ובכל ר\"ה חוזרים כל הדברים לקדמותם (אוה\"ת שם ע' ב'פא. ובכ\"מ. ובארוכה – סידור (עם דא\"ח) שער התקיעות רמו, א ואילך)."],["381","5","ראה אוה\"ת שם ע' ב'פו בה\"קיצורים\" ס\"א בסופו."],["382","6","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380909\" data-slug=\"likkutei-torah\" data-id=\"4001380909\">לקו\"ת נצבים מז, ג</a>. מאמרי אדהאמ\"צ דברים ח\"ג ע' תתמ. אוה\"ת נצבים ע' א'רנד. ד\"ה והענין כו' זה היום תרנ\"ד (סה\"מ תרנ\"ד ע' יג). המשך תרס\"ו ע' כ. רד\"ה זה היום תרס\"ט. המשך ר\"ה תרצ\"ה בתחלתו (סה\"מ קונטרסים ח\"ב שיח, ב). רד\"ה זה היום ה'תש\"ד. ועוד."],["383","7","ויק\"ר רפכ\"ט. פסיקתא דר\"כ פיסקא כג (בחודש השביעי). יל\"ש עה\"פ (פינחס כט, א) ובחודש השביעי (רמז תשפב). תוד\"ה לתקופות – ר\"ה ח, א. וראה פרקי דר\"א רפ\"ח ובהגהות הרד\"ל שם."],["384","8","ולהעיר שלומדים פרק זה בהשבת שלפני ראש השנה."],["385","9","ראה עד\"ז ר\"ן לר\"ה טז, א ד\"זה היום תחלת מעשיך כו'\" \"על יצירת אדם קאמרינן\"."],["386","10","זח\"א רכא, ב. ח\"ג קז, ב. תקו\"ז תנ\"ו (צ, ב). וראה אוה\"ת וארא ס\"ע רלו ואילך."],["387","11","תהלים צה, ו."],["388","12","שם צג, א. פרקי דר\"א פי\"א (הובא גם בהמשך ר\"ה הנ\"ל פי\"ז (סה\"מ קונטרסים שם שא, ריש ע\"ב))."],["389","13","ראה שיחת יום ב' דר\"ה שנה זו (ה'תשמ\"א) ס\"ח-ט (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191088\" data-slug=\"likkutei-sichot\" data-id=\"1300191088\">לקו\"ש חי\"ט ע' 88-287</a>)."],["390","14","עש\"מ (לרמ\"ע מפאנו) מאמר אם כל חי ח\"ב סל\"ג (קצג, ב). של\"ה ג, א. כ, ב. שא, ב. ובכ\"מ. מאמרי אדהאמ\"צ דברים ח\"א ע' קכב. וש\"נ."],["391","15","ראה ד\"ה זה היום תרס\"ט (סה\"מ תרס\"ט ע' ה). ובאוה\"ת דרושים לר\"ה ריש ע' א'תלב מציין לד\"ה וידבר משה אל ראשי המטות לאמר זה הדבר (אוה\"ת מטות ע' א'פב) בענין \"כל הנביאים נתנבאו בכה ומשה נתנבא בזה\", \"ושם ג\"כ ענין בכ\"ה באלול נברא העולם הבריאה בבחי' כה, ור\"ה נק' זה היום להמשיך בחי' זה\". ושם ע' א'תלד מביא בהמשך ל\"זה היום תחלת מעשיך\" \"ע\"ד שלע\"ל נאמר ואמר ביום ההוא הנה אלקינו זה\" – שהוא הפסוק שהובא בגמ' ובמדרש שבהערה הבאה."],["392","16","ל' חז\"ל – שמו\"ר ספכ\"ג. תענית בסופה ובפרש\"י שם. וראה גם פרש\"י עה\"פ בשלח טו, ב."],["393","17","ראה סה\"מ תרס\"ט שם."],["394","18","בראשית א, ה. וראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370063\" data-slug=\"torah-or\" data-id=\"3901370063\">תו\"א וירא יד, סע\"א</a>. סה\"מ ה'תש\"ח ע' 118."],["395","19","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380908\" data-slug=\"likkutei-torah\" data-id=\"4001380908\">לקו\"ת נצבים מז, ב</a>-ג ובארוכה בסה\"מ תרס\"ט בתחלתו, ד\"זה\" הוא גילוי המהות. וזהו \"זה היום\", דהעולם כמו שנברא <i>בכ\"ה</i> באלול הי' בבחי' \"כה\", ובר\"ה (יום ברוא אדה\"ר) נעשה בבחי' \"זה\". ובסה\"מ תרס\"ט שם (ע' ה) דזהו גם פירוש \"זה <i>היום</i>\", כי (גם) \"יום\" הוא גילוי."],["396","20","דנוסף לזה שביכלתו לשנות את העבר <i>שלו</i> – ד\"השב מאהבה נעקר עונו מתחלתו\" (רש\"י ד\"ה מכאן – יומא פו, סע\"א) – ביכלתו לשנות גם העבר שחוץ ממנו*, כמו \"חכם עוקר את הנדר <i>מעיקרו</i>\" (כתובות עד, ב); כשב\"ד מעברין את השנה – בתולי' חוזרין (ירושלמי נדרים פ\"ו ה\"ח. ועוד)."],["397","21","ראה ב\"ר פכ\"ד, ה. קה\"ר פ\"ג, יא (ב)."],["398","22","ראה <i>עד\"ז</i> <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061103\" data-slug=\"likkutei-sichot\" data-id=\"1300061103\">לקו\"ש ח\"ו ע' 92</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061247\" data-slug=\"likkutei-sichot\" data-id=\"1300061247\">וראה שם ע' 236</a> ובהערות שם.\n*) <i>דזה שנוגע כאן הוא שינוי העבר בהדברים שחוץ ממנו – ראה לקמן בפנים</i>,<i> דע\"י עבודת אדה\"ר נעשה שינוי בהעבר </i><b>שבעולם</b>."],["399","23","וזה שר\"ה הוא \"<i>תחלת</i> מעשיך\" – אף שזהו כוונת כל הבריאה מלכתחילה – הוא, כי מכיון שגדר העולם הוא כשמו עולם מלשון העלם והסתר (<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380463\" data-slug=\"likkutei-torah\" data-id=\"4001380463\">לקו\"ת שלח לז, ד</a>. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071124\" data-slug=\"likkutei-sichot\" data-id=\"1300071124\">לקו\"ש חל\"ד ע' 112</a> הערה 63. וש\"נ), הרי ענין זה גופא (שמציאות העולם שלפני עבודת האדם הוא הכנה להגילוי שלאח\"ז) הוא בו בהעלם, ויתירה מזו, שבהעולם מצד עצמו (לפני עבודת האדם, ומכ\"ש לפני בריאת האדם) <i>אין שייך</i> שזה יהי' בגילוי. ונמצא, שגם <i>הגילוי</i> דמציאות העולם <i>בעבר</i> שנעשה בר\"ה – הוא באופן של \"חידוש\", התחלת ענין חדש שלא הי' שייך מקודם."],["400","24","דגם \"הזמן עצמו הוא . . בחי' נברא מחודש כו'\" – סידור (עם דא\"ח) עה, סע\"ד ואילך."],["401","25","לקו\"א להה\"מ (הוצאת קה\"ת) סקצ\"ח (נ, סע\"ג). או\"ת קיב, ב (בהוצאת קה\"ת תש\"מ ואילך – סת\"פ)."],["402","26","סה\"ש ה'תש\"ג ע' 12. ה'תש\"ד ע' 23. \"היום יום\" יג אייר. וראה ד\"ה פדה בשלום ה'תשל\"ח הערה 28 (לקמן ח\"ב ע' קמד)."],["403","27","אבות פ\"ב מ\"א."],["404","28","אוה\"ת שבהערה 2 – ע' ב'פ. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380908\" data-slug=\"likkutei-torah\" data-id=\"4001380908\">לקו\"ת שם נח, ב</a>. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381176\" data-slug=\"likkutei-torah\" data-id=\"4001381176\">לקו\"ת נצבים מז, ב</a>. שה\"ש יא, סע\"ד. אוה\"ת נצבים ע' א'רמב-ג. שם ע' א'רנג-ד."],["405","29","בראשית ב, ה."],["406","30","באוה\"ת שם ד\"יום ראשון\" הוא \"ר\"ה הראשון . . יום שנברא אדה\"ר\" (ולא כ\"ה אלול). ועפ\"ז, הפירוש ד\"לא הי' עדיין במי שיהי' אתעדל\"ת כמ\"ש ואדם אין גו'\" הוא לכאורה – שלא הי' מי שיעורר הענין <i>דבריאת האדם</i>. וגם בריאת האדם (לא רק הבריאה דכ\"ה באלול) היתה מצד כי חפץ חסד הוא."],["407","31","מיכה ז, יח."],["408","32","תהלים פט, ג. וראה שעהיוה\"א פ\"ד (עט, סע\"א)."],["409","33","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380466\" data-slug=\"likkutei-torah\" data-id=\"4001380466\">לקו\"ת שלח לח, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381101\" data-slug=\"likkutei-torah\" data-id=\"4001381101\">ברכה צג, ג</a>. שה\"ש כח, ריש ע\"ד. שם לג, סע\"ד."],["410","34","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381176\" data-slug=\"likkutei-torah\" data-id=\"4001381176\">לקו\"ת שה\"ש יא, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381230\" data-slug=\"likkutei-torah\" data-id=\"4001381230\">כה, ב</a>. סה\"מ ה'תש\"ח ריש ע' 273."],["411","35","וכידוע הפירוש ב\"נזכרים ונעשים\", דע\"י ש\"נזכרים\" – עי\"ז \"נעשים\" (ראה רמ\"ז בס' תיקון שובבים. הובא ונת' בס' לב דוד (להחיד\"א) פכ\"ט)."],["412","36","ב\"ר פ\"ח, ז. רות רבא פ\"ב, א (ג)."],["413","37","ישעי' ס, כא."],["414","38","בשערי אורה שבהערה הבאה, שזהו\"ע \"ישראל עלו במחשבה\"."],["415","39","כ\"ה להדיא בשערי אורה שער הפורים ד\"ה וקבל היהודים פ\"ל (צז, ב)."],["416","40","ראה עט\"ר שער ר\"ה פ\"י (ט, ב) \"דאותו בחי' חפץ חסד שהי' בעצמותו בתחלת ברה\"ע הוא עצמו <i>שמתחדש</i> בכל ר\"ה מצד מעשה התחתונים\"."],["417","41","תו\"כ (הובא בפרש\"י) עה\"פ ויקרא א, ט. ספרי (הובא בפרש\"י) עה\"פ פינחס כח, ח."],["418","42","ראה שערי אורה שם."],["419","43","ראה תנחומא נשא טז. בחוקותי ג. ב\"ר ספ\"ג. במדב\"ר פי\"ג, ו. תניא רפל\"ו."],["420","44","ראה המשך תרס\"ו ע' ה ואילך (וראה גם שם ע' תמ), שמצד הטעמים ד\"בגין דישתמודעון לי'\" ו\"יתגלו שלימות כחותיו\" (זח\"ב מב, א. ע\"ח שער ההקדמות הקדמה ג') הי' מספיק העולמות כמו שהם בכח, דלמעלה \"כח אין חסר פועל\", ומכ\"ש שהי' מספיק ההתהוות דעולמות העליונים. וזה שנתהוו העולמות בפועל, ועד לעוה\"ז התחתון – הוא בכדי להשלים הכוונה דנתאוה כו' דירה בתחתונים."],["421","45","שבת פח, א. ע\"ז ג, א."],["422","46","תהלים עו, ט."],["423","47","קידושין מ, ב. וש\"נ. רמב\"ם הל' ת\"ת פ\"א ה\"ג. פ\"ג ה\"ג. הל' ת\"ת לאדה\"ז פ\"ד ס\"ג."],["424","48","כ\"מ מהמבואר בשערי אורה שם שע\"י מעשה התחתונים \"מעורר בבחי' עצמות אוא\"ס במדריגה היותר נעלה שלא הי' כן מצד התעוררות רצון וחפץ חסד\"."],["425","49","וכיון דזה שנתאוה כו' דירה (שהעצמות יהי' בגילוי) הוא שנתאוה בעצמותו – הרי זה (שהעצמות הוא בגילוי) נוגע כביכול גם לעצמותו, מכיון שעי\"ז דוקא נשלם זה שנתאוה."],["426","50","סה\"מ תקס\"ה ח\"א ע' תפט. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770311\" data-slug=\"or-hatorah-hb\" data-id=\"8316770311\">אוה\"ת שה\"ש כרך ב ע' תרעט</a>. בלק ע' תתקצז. סה\"מ תרס\"ב ע' שלח. תרע\"ח ע' קצג. המשך תרס\"ו ס\"ע ג. שם ע' תמה. סה\"מ תרצ\"ט ע' 48. ובכ\"מ."],["427","51","בהבא לקמן ראה גם ד\"ה זה היום דיום ב' דר\"ה שנה זו (ה'תשמ\"א) ס\"ג (לעיל ע' לא)."],["428","52","רות ד, יח."],["429","53","ב\"ר פי\"ב, ו. שמו\"ר פ\"ל, ג."],["430","54","בראשית ב, ד."],["431","55","ראה ב\"ר פי\"ד, ז. פי\"ג, ג."],["432","56","ראה שערי אורה שם, שמצד הענין דחפץ חסד – ההמשכה היא ע\"פ סדר ההשתלשלות \"לפי ערך הגבלת המקבלים\", וענין הנסים (שהמשכתם הוא למעלה מסדר ההשתלשלות) שרשו הוא מהעצמות (שלמעלה מחפץ חסד)."],["433","57","וישב לח, כט."],["434","58","בראשית ב, ו."],["435","59","קהלת ג, כ."],["436","60","ראה פרש\"י עה\"פ בראשית א, לא. פרש\"י שבת שם ד\"ה מלמד. פרש\"י ד\"ה ה' דהששי – ע\"ז שם."],["437","61","ברכות כח, א. וש\"נ."],["438","62","אגה\"ק סי\"ד."],["439","63","ע\"פ מיכה ב, יג. וראה ב\"ר פפ\"ה, יד. אגדת בראשית ס\"פ סג."],["440","64","אוה\"ת שבהערה 2 – ע' ב'פ ואילך. וראה לקו\"ת שם נח, ב ואילך."],["441","65","ר\"ה טז, סע\"א. וש\"נ."],["442","66","שופטים יז, טו."],["443","67","ראה ברכות נח, א."],["444","68","כמארז\"ל קבלו מלכותי תחלה ואח\"כ אגזור עליכם גזירות (ראה מכילתא (ויל\"ש) עה\"פ יתרו כ, ג. פרש\"י עה\"פ אחרי יח, ב. וראה המשך יו\"ט של ר\"ה ה'תש\"ג פכ\"ו (סה\"מ ה'תש\"ג ע' 69)). ולהעיר מברכות יג, א (במשנה): שיקבל עליו מלכות שמים תחלה ואח\"כ מקבל עליו עול מצוות."],["445","69","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380472\" data-slug=\"likkutei-torah\" data-id=\"4001380472\">לקו\"ת שלח מ, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380921\" data-slug=\"likkutei-torah\" data-id=\"4001380921\">נצבים נ, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380935\" data-slug=\"likkutei-torah\" data-id=\"4001380935\">דרושים לר\"ה נד, א</a>. דרך חיים (שער התפלה) פמ\"ט ואילך (נו, ד ואילך). שם ספ\"נ (נה, רע\"ג). עט\"ר דרוש לעשי\"ת נח, סע\"ב ואילך. המשך תרס\"ו ע' נו. ד\"ה אדון עולם ה'תשמ\"ג ס\"ד (לקמן ע' סא)."],["446","70","ראה בארוכה לקו\"ש ח\"ד ע' 1147."],["447","71","נצבים מד, ב."],["448","72","נצבים כט, יא-יב."],["449","73","המשך תרס\"ו ע' תקלח."],["450","74","כ\"ה להדיא בהמשך הנ\"ל ע' תקלט."],["451","75","ראה בכ\"ז אוה\"ת שבהערה 2 ע' ב'פא וב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380953\" data-slug=\"likkutei-torah\" data-id=\"4001380953\">לקו\"ת שם נח, ג</a>. המשך תרס\"ו שם."],["452","76","ראה גם המשך תרס\"ו שם, דענין זכרונות הוא \"כמו זכרון ליום ראשון\"."],["453","77","ועד\"ז הענין ד\"חפץ חסד\", שיש לו איזו שייכות לעולמות, כנ\"ל סעיף ז."],["454","78","אוה\"ת שבהערה 2 ע' ב'פא. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380954\" data-slug=\"likkutei-torah\" data-id=\"4001380954\">לקו\"ת שם נח, ד</a> ואילך. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380896\" data-slug=\"likkutei-torah\" data-id=\"4001380896\">לקו\"ת נצבים מד, ב</a> ואילך. המשך תרס\"ו בתחלתו. המשך ר\"ה ה'תש\"י סוף ס\"א ואילך. ובכ\"מ."],["455","79","המשך תרס\"ו ע' תקמ."],["456","80","תהלים כז, ח (המזמור שנוהגים לומר מר\"ח אלול עד הו\"ר). וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380897\" data-slug=\"likkutei-torah\" data-id=\"4001380897\">לקו\"ת נצבים מד, ג</a>."],["457","81","אוה\"ת ר\"ה כרך ה ע' ב'קי. וראה שם ס\"ע ב'קיב. וראה ד\"ה יו\"ט של ר\"ה ה'תשמ\"ג ס\"ג ואילך (לקמן ע' נג ואילך)."],["458","82","ויק\"ר פכ\"ט, ו. מדרש תהלים פא, ד."],["459","83","<a class=\"ft-cite\" href=\"#/read/tanya/3401310053\" data-slug=\"tanya\" data-id=\"3401310053\">תניא פמ\"ח (סז, ב</a> ואילך)."],["460","84","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380525\" data-slug=\"likkutei-torah\" data-id=\"4001380525\">לקו\"ת קרח נב, ד</a>. ספר המצוות להצ\"צ טו, א. ובכ\"מ."],["461","85","ראה גם לקו\"ת וסהמ\"צ שם."],["462","86","אוה\"ת שבהערה 2 ע' ב'פד. לקו\"ת שם נט, ב."],["463","87","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370014\" data-slug=\"torah-or\" data-id=\"3901370014\">תו\"א בראשית ד, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670169\" data-slug=\"torat-chaim\" data-id=\"2300670169\">תו\"ח בראשית כא, א</a> ואילך."],["464","88","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370512\" data-slug=\"torah-or\" data-id=\"3901370512\">תו\"א קיד, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380840\" data-slug=\"likkutei-torah\" data-id=\"4001380840\">לקו\"ת ראה לא, א</a>. ביאוה\"ז לאדהאמ\"צ פא, א-ב. ביאוה\"ז להצ\"צ ע' תכג. קונטרס העבודה פ\"ג (ע' 18)."],["465","89","ר\"ה כו, ב (במשנה). שם כז, א. רמב\"ם הל' שופר פ\"א ה\"ב."],["466","90","אגרות-קודש שלו ח\"ד ע' רל, נעתק ב\"היום יום\" כט אלול, <i>ערב ר\"ה</i>."],["467","91","ראה ספר השיחות תורת שלום ע' 120."],["468","92","רמב\"ם הל' קדה\"ח פ\"ב ה\"ב."],["469","93","ראה שיחת ח\"י אלול ה'תש\"ה (לקו\"ד כרך ג ע' 946. ספר השיחות ה'תש\"ה ע' 122). – נת' ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191263\" data-slug=\"likkutei-sichot\" data-id=\"1300191263\">לקו\"ש חי\"ט</a> שיחה לח\"י אלול (ע' 250 ואילך). חכ\"ט שיחה לח\"י אלול (ע' 161 ואילך). וראה גם לקו\"ד כרך א לד, א."],["470","94","ספר השיחות ה'תש\"ג ע' 141 ואילך. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300241178\" data-slug=\"likkutei-sichot\" data-id=\"1300241178\">לקו\"ש חכ\"ד ע' 178</a> ואילך, ובהנסמן שם."],["471","95","ר\"פ נצבים."],["472","96","זח\"ב סג, ב. שם פח, א."],["473","97","קובץ מכתבים לתהלים אהל יוסף יצחק ע' 193. \"היום יום\" כה אלול. אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ג ס\"ע תל ואילך. כתר שם טוב (הוצאת תשנ\"ט) בהוספות סי' מא."],["474","98","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380883\" data-slug=\"likkutei-torah\" data-id=\"4001380883\">רמ\"ז לזח\"ב לב, ב</a> (הובא בלקו\"ת תבוא מא, ג). וראה גם זח\"ג רלא, א. פענח רזא ס\"פ נצבים."],["475","99","טור או\"ח סתקפ\"א, מירושלמי ר\"ה פ\"א ה\"ג."],["476","100","ראה ד\"ה יו\"ט של ר\"ה ה'תש\"ג רפ\"ב, שהכתרת המלך היא \"<i>בשמחה גדולה</i>\"."],["477","101","ראה בארוכה המשך שמח תשמח ס\"ע 40 (סה\"מ תרנ\"ז ע' רכג) ואילך. ד\"ה שמח תשמח דש\"פ תצא שנה זו (ה'תשמ\"א) ס\"ה (לקמן ח\"ד ס\"ע רמב ואילך)."]]],[1500360008,"<h3>בס\"ד. ליל ערב ראש-השנה ה'תשמ\"ג<sup data-n=\"478\">*</sup></h3>\n<b>יום</b> טוב של ראש השנה שחל להיות בשבת במקדש היו תוקעין אבל לא במדינה<sup data-n=\"479\">1</sup>. וצריך להבין [כמו שמדייק אדמו\"ר הצ\"צ<sup data-n=\"480\">2</sup> במאמרו ד\"ה להבין הטעם<sup data-n=\"481\">3</sup>], הרי תקיעת שופר היא מ\"ע דאורייתא כמ\"ש<sup data-n=\"482\">4</sup> יום תרועה יהי' לכם, והיאך ביטלו<sup data-n=\"483\">5</sup> אותה משום גזירה שמא יעבירנו כו'<sup data-n=\"484\">6</sup>. וביותר יש לתמוה<sup data-n=\"485\">7</sup>, דמזה שבמקדש היו תוקעין גם בראש השנה כשחל בשבת הרי מוכח שמצות תקיעת שופר ישנה גם בפועל גם ביו\"ט של ראש השנה שחל להיות בשבת, ולמה ביטלו אותה בחו\"ל ואפילו במדינה מפני הגזירה שמא יעבירנו. וגם צריך להבין<sup data-n=\"486\">8</sup> מה שפסוקי שופרות אומרים גם בראש השנה שחל בשבת, דהגם שאמירת הפסוקים קשורה ובאה בהמשך לתקיעת שופר, ובראש השנה שחל בשבת אין תוקעין במדינה, מ\"מ אמירת הפסוקים היא גם בראש השנה שחל בשבת.\n<b>ומבאר</b> זה (במאמר הנ\"ל) ע\"פ הידוע דכל המצוות שלנו הוא (בכדי) שע\"י אתעדל\"ת אתעדל\"ע. היינו, דמה שישראל מקיימים את המצוות הוא בכדי לפעול עי\"ז המצוות שלמעלה. דהנה כל המצוות שלמעלה נעשים הם ע\"י שהאדם שלמטה מקיים את המצוות, וכמ\"ש<sup data-n=\"487\">9</sup> ועשיתם אותם, אתם כתיב, מעלה אני עליכם כאילו עשאוני<sup data-n=\"488\">10</sup>, רמ\"ח פיקודין אינון רמ\"ח אברין דמלכא<sup data-n=\"489\">11</sup>, בחינת ז\"א, והמשכת האור בהכלים דז\"א וכן הגדלת הכלים היא ע\"י קיום המצוות של האדם התחתון דוקא<sup data-n=\"490\">12</sup>, כמ\"ש אשר יעשה אותם האדם וחי בהם<sup data-n=\"491\">13</sup>, דהמצוות שלמעלה הוא דוקא עלידי אשר יעשה אותם האדם, נשמה בגוף. דכמו כן הוא במצות תקיעת שופר, שע\"י שישראל תוקעים בשופר, נעשה עי\"ז תקיעת שופר שלמעלה&lt;7&gt;.\n<b>ובזה</b> מבארים מ\"ש<sup data-n=\"492\">14</sup> תקעו בחודש שופר, שידוע דיוק הבעש\"ט בזה<sup data-n=\"493\">15</sup>, שלכאורה הול\"ל תקעו שופר בחודש, ומבאר בזה, דמ\"ש תקעו בחודש (בחודש בסמיכות לתקעו) הוא, כי בחודש קאי על תקעו, דבכל שנה צ\"ל התקיעות באופן חדש. והטעם על זה, כי בכל שנה מתחדש בחינת השופר. ומכיון שכל הענינים שלמעלה נעשים ע\"י עבודת בנ\"י, כתורת הרב המגיד<sup data-n=\"494\">16</sup> בפירוש המשנה<sup data-n=\"495\">17</sup> דע מה למעלה ממך דכל מה שלמעלה הכל הוא ממך, לכן צ\"ל התקיעת שופר דישראל באופן חדש בכדי שעי\"ז יופעל למעלה ענין חדש.\nב) <b>והנה</b> כמו שהוא במצות תקיעת שופר דראש השנה שבכל שנה שהוא באופן חדש, עד\"ז הוא בכל המצוות, כמארז\"ל<sup data-n=\"496\">18</sup> בכל יום יהיו בעיניך כחדשים, ויתירה מזו חדשים ממש<sup data-n=\"497\">19</sup>. אלא שבתקיעת שופר, מכיון שהיא מצוה כללית על כל השנה<sup data-n=\"498\">20</sup>, כידוע<sup data-n=\"499\">21</sup> הטעם על מה שנקרא בשם ראש השנה (ולא תחלת השנה) לפי שהוא הראש הכולל כל ימי השנה, ענין זה הוא ביתר שאת. ויש לומר, דענין זה (החידוש שבתקיעת שופר) הוא השרש שממנו נמשך שגם המצוות דכל השנה יהיו חדשים. דהנה מצות תקיעת שופר בראש השנה ענינה הוא שתמליכוני עליכם<sup data-n=\"500\">22</sup>, ומכיון דאופן המצוות הוא לפי האופן דתמליכוני עליכם, כמובן ממארז\"ל<sup data-n=\"501\">23</sup> קבלו מלכותי תחלה ואח\"כ אגזור עליכם גזירות, לכן ע\"י שתקיעת שופר הוא באופן חדש נעשה כן בכל המצוות. דע\"י תקעו בחודש נעשה התחדשות כביכול במדת מלכותו ית', בזה שהוא ית' מלך על ישראל (תמליכוני עליכם), ועי\"ז גם במלכותו על כל העולמות [דגם זה נעשה ע\"י ובשביל ישראל, שהקב\"ה ממלא את בקשת ישראל מלוך על העולם כולו בכבודך<sup data-n=\"502\">24</sup>, שבזה (ב\"העולם כולו\") נכללים כל העולמות כולם], שבכל ראש השנה נמשך חיות חדש בכל סדר ההשתלשלות, חיות חדש שלא הי' עדיין מעולם, כמ\"ש אדמו\"ר הזקן באגה\"ק<sup data-n=\"503\">25</sup>, וחיות זה נמשך אח\"כ גם בכל ימי השנה, על ידי י\"ב ראשי חדשים, כמבואר בארוכה בספר עטרת ראש לאדמו\"רהאמצעי<sup data-n=\"504\">26</sup>. ועד\"ז הוא גם במצוות, דענין החידוש שבמצוות (בכל יום כו' חדשים) במשך כל השנה, נמשך הוא מהחידוש דתקיעת שופר שבראש השנה.\nג) <b>ובזה</b> יובן<sup data-n=\"505\">27</sup> שבראש השנה שחל בשבת אין תוקעין במדינה, כי מה שצריך לתקוע בשופר בראש השנה הוא (כנ\"ל) בכדי לפעול עי\"ז השופר שלמעלה, ובשבת יש בחי' זו (שופר) בלי עבודת האדם<sup data-n=\"506\">28</sup>. דהנה ידוע, דביו\"ט אומרים מקדש ישראל והזמנים שישראל אינהו דקדשינהו לזמנים<sup data-n=\"507\">29</sup>, משא\"כ שבת היא מקדשא וקיימא, ואינה תלוי' בישראל שיקדשוה<sup data-n=\"508\">30</sup>. ולכן יש בשבת ריבוי ענינים שהם מן המוכן, ומהם כמה באופן דשלימות, גם בלי עבודת האדם. והנה כתיב<sup data-n=\"509\">31</sup> לעשות את השבת, דישראל עושים את השבת, וכן כתיב<sup data-n=\"510\">32</sup> זכור את יום השבת לקדשו, דישראל צריכים לקדש את השבת. והענין הוא, שבשבת יש שתי מדריגות<sup data-n=\"511\">33</sup>, מה ששבת מקדשא וקיימא מצד עצמו, ומה שישראל מוסיפים בו ע\"י עבודתם. דהנה שבת הו\"ע התענוג, ואעפ\"כ אמרו<sup data-n=\"512\">34</sup> כל המענג את השבת, שצריכים לענג את השבת, וכן כתיב<sup data-n=\"513\">35</sup> וקראת לשבת עונג, שצריך לקרוא ולהמשיך עונג בשבת, כי ע\"י העבודה דישראל ממשיכים בשבת עונג נעלה יותר. אבל יש עונג בשבת מצד עצמו, מצד זה ששבת מקדשא וקיימא, והוא עונג בשלימות. דהרי כללות ענין השבת הוא שאז נעשה שלימות בכל הבריאה, כמ\"ש<sup data-n=\"514\">36</sup> ויכולו השמים והארץ וכל צבאם, דויכולו הו\"ע השלימות כפירוש אדמו\"ר הצ\"צ<sup data-n=\"515\">37</sup>, דמזה מובן שגם התענוג דשבת (כמו שהוא מצד עצמו) הוא בשלימות. וזהו מה שבראש השנה שחל בשבת אין הכרח כ\"כ לתקוע בשופר במדינה. דהנה שופר הוא בחינת תענוג<sup data-n=\"516\">38</sup>, וכמו שמבאר בהמאמר<sup data-n=\"517\">39</sup> דשופר הוא מלשון שפרו מעשיכם<sup data-n=\"518\">40</sup> ומלשון הנותן אמרי שפר<sup data-n=\"519\">41</sup> (וכן עוד לשונות שמביא בהמאמר שם), שענינם הוא תענוג. ומכיון שכל מה שלמעלה הכל הוא ממך, לכן בכדי שיהי' בחינת התענוג (שופר) שלמעלה, נעשה זה ע\"י תקיעת שופר דישראל. דכ\"ז הוא בראש השנה שחל בחול. משא\"כ בשבת, ענין התענוג הוא מן המוכן (בליעבודת האדם), ועד שהתענוג הוא בשלימות (כנ\"ל), ולכן בראש השנה שחל בשבת המצוה דתקיעת שופר אינה בתוקף כ\"כ (עם כל השטורעם) כמו בראש השנה שחל בחול, ולכן היא נדחית מצד החשש דשמא יעבירנו כו'.\nד) <b>והנה</b> נוסף לזה שע\"י תקיעת שופר נעשה השופר (תענוג) למעלה (בז\"א וכו'), דמה שלמעלה הוא ממך, הנה ע\"י תקיעת שופר ממשיכים התענוג (הבחינה דשופר) בכל העולמות כולם, עד בעולם העשי'. וכמו שאומרים בתפלות ראש השנה וידע כל פעול כי אתה פעלתו ויבין כל יצור כי אתה יצרתו ויאמר כל אשר נשמה באפו כו', ואיתא בסידור האריז\"ל<sup data-n=\"520\">42</sup> דג' לשונות אלו קאי על ג' עולמות בי\"ע [נשמה באפו קאי בעולם הבריאה, יצור בעולם היצירה ופעול בעולם העשי'], שהם כללות כל העולמות, ולכן אומרים בראש השנה ג' לשונות אלו כי ההמשכה דראש השנה היא בכל העולמות כולם, עד בעולם העשי'. וזה שבראש השנה שחל בשבת אין תוקעין הוא לפי שגם ענין זה שנעשה ע\"י תקיעת שופר, המשכת התענוג בכל העולמות עד למטה, בשבת נעשה זה מצד שבת עצמו. כידוע שההמשכה דשבת היא בכל העולמות, גם בעשי'. וכמבואר בכמה דרושים (ומהם בהדרושים דראש השנה)<sup data-n=\"521\">43</sup> שהחיות דכל העולמות, גם דעולם העשי', בשבת הוא נעלה יותר מהחיות שבימי החול. דבימי החול החיות דעולמות הוא מאותיות הדיבור, ובשבת החיות שלהם הוא מאותיות המחשבה. הרי דשבת פועל בכל העולמות, גם בעולם הגשמי. ועד שזה פועל שינוי גם בטבע של עם הארץ<sup data-n=\"522\">44</sup> דבשבת (הרי מצד טבעו) אינו יכול לשקר<sup data-n=\"523\">45</sup>.\n<b>ומה</b> שבמקדש היו תוקעין גם בראש השנה שחל בשבת, הוא לפי שבחינת התענוג (בחינת שופר) שהמשיכו ע\"י תקיעת שופר במקדש היא נעלית יותר<sup data-n=\"524\">46</sup>. והיינו דהתענוג שממשיכים ע\"י תקיעת שופר במדינה הוא התענוג שיש בשבת מצד עצמו, מצד זה ששבת מקדשא וקיימא, ולכן בראש השנה שחל בשבת אין תוקעין במדינה, משא\"כ ע\"י תקיעת שופר במקדש ממשיכים בחינת תענוג נעלית יותר, שאינה בשבת מצד עצמו (והוא ע\"ד שנת\"ל בענין כל המענג את השבת, שיש בחינה בתענוג שאינה בשבת מצד עצמו ונעשית ע\"י העבודה דישראל), ולכן במקדש היו תוקעין בראש השנה שחל בשבת. דבחינה זו היא למעלה יותר מבחינת התענוג גם דכל המענג את השבת (העבודה דשבת)<sup data-n=\"525\">47</sup>, ונמשכת רק בראש השנה ע\"י העבודה דתקיעת שופר.ה) <b>והענין</b> הוא (כמבואר בהמאמר שם<sup data-n=\"526\">48</sup>), דהנה בתענוג שבמצוות יש שני אופנים. אופן הא' הוא התענוג מזה שקיים ציווי הקב\"ה, אשר קדשנו במצוותיו וצונו, דתענוג זה הוא בכל המצוות בשוה, דמכיון שהרצון הוא שוה בכל המצוות, במילא גם התענוג שמצד הרצון הוא בכולם בשוה. ואופן הב' הוא התענוג הפרטי שבכל מצוה, דבכל מצוה יש תענוג מיוחד. ומבאר בהמאמר, דהתענוג הפרטי שבכל מצוה הוא נעלה יותר מהתענוג שמצד הרצון שבשוה בכל המצוות. דזהו חידוש בדרוש זה. דבכ\"מ<sup data-n=\"527\">49</sup> מבואר דהכוונה הפרטית שבכל מצוה היא למטה במדריגה מהכוונה הכללית, וכאן מבאר דהתענוג הפרטי הוא נעלה יותר<sup data-n=\"528\">50</sup>. דהתענוג המלובש בהרצון (שהוא בשוה בכל המצוות) הוא בחינת גילוי התענוג, משא\"כ התענוג הפרטי שבכל מצוה שרשו הוא מבחינת מקור התענוגים שלמעלה מעלה מבחינת גילוי התענוג, ומבחינת מקור התענוגים נמשך הארה לכל בחינה כפי מדריגתה דוקא. ועפ\"ז מבאר שם<sup data-n=\"529\">51</sup> ענין השופר מה ששופר הוא מלשון תענוג (הנותן אמרי שפר), דלכאורה אינו מובן, הרי ענין התענוג הוא כשיש כמה פרטים דוקא, וכמו\"כ הוא בתענוג שבקול (ניגון וכלי זמר) שהוא דוקא כשיש הרכבה של כמה קולות, ומכיון דשופר הוא קול אחד, איך שייך שיהי' בו תענוג. ובפועל אנו רואים, דקול שופר אין בו תענוג, ואדרבה הוא מעורר חרדה כמ\"ש<sup data-n=\"530\">52</sup> אם יתקע שופר בעיר ועם לא יחרדו<sup data-n=\"531\">53</sup>, וכן במ\"ת כתיב<sup data-n=\"532\">54</sup> וקול שופר חזק מאד ויחרד כל העם אשר במחנה וכתיב<sup data-n=\"533\">55</sup> וירא העם וינועו ויעמדו מרחוק, דמצד הגילוי הכי גדול ונפלא דבקול שופר עליהם הופעת<sup data-n=\"534\">56</sup> היו בביטול (ויעמוד מרחוק), דחרדה וביטול הם היפך התענוג, והיאך אומרים דשופר הוא מלשון וענינו תענוג. והענין בזה הוא (כמבואר בהמאמר שם<sup data-n=\"529\">51</sup>), דמה ששופר הוא תענוג הוא להיותו בחינת מקור התענוגים שלמעלה מבחינת גילוי התענוג. ולכן לא ימצא בקול השופר שום הרגשת תענוג כלל (ואדרבה הוא מטיל חרדה), לפי שהוא למעלה מבחינת תענוג גלוי, כ\"א הוא מבחי' מקור התענוגים. ומבחינה זו נמשכים כל פרטי התענוגים. דזהו מה ששופר הוא מלשון שפרו מעשיכם, מעשיכם לשון רבים, דע\"י תקיעת שופר נפעל בכל מעשה ומעשה השיפור והתענוג השייך למעשה פרטי זה, כי ההמשכה מבחינת מקור התענוגים היא (כנ\"ל) באופן דהתחלקות פרטים דוקא. וזוהי ג\"כ השייכות דשופר למ\"ת, וכמו שאומרים במוסף דראש השנה אתה נגלית כו' ללמד לעמך תורה ומצוות כו' ובקול שופרעליהם הופעת, דבמ\"ת היתה המשכת העצמות, אנא נפשי כתבית יהבית<sup data-n=\"535\">57</sup>, המשכת בחינת מקור התענוגים שלמעלה מבחינת גילוי התענוג, ומזה נמשך אח\"כ התענוג בעשרת הדברות, בכל דבור בפרט (על כל דבור ודבור פרחה נשמתן<sup data-n=\"536\">58</sup>) התענוג השייך לדבור זה במיוחד, ואח\"כ נמשך זה בפרטיות יותר ללמד לעמך תורה ומצוות, בכל מצוה ומצוה בפרט.\nו) <b>ועד\"ז</b> הוא גם בענין תקיעת שופר דראש השנה, שהיא ההמשכה מבחינת מקור התענוגים (שלמעלה מבחי' גילוי התענוג). שהרי בראש השנה חוזרים כל הדברים לקדמותם וצריך לחדש כל ענין ממקורו ושרשו הראשון, עד מעצמות ומהות<sup data-n=\"537\">59</sup>. וכמו\"כ הוא גם בענין הברית וההתקשרות דהקב\"ה עם ישראל, דבכל ראש השנה נעשה הברית וההתקשרות מחדש, כמ\"ש<sup data-n=\"538\">60</sup> אתם נצבים היום (ראש השנה<sup data-n=\"539\">61</sup>) גו' לעברך בברית ה' אלקיך, דהמשכת הברית (בראש השנה) היא מהעצמות שלמעלה מכל הגילויים. וכמובן גם משני המשלים על תקיעת שופר שהובאו בהמשך וככה לאדמו\"ר מהר\"ש<sup data-n=\"540\">62</sup>, משל אחד בשם הבעש\"ט מבן מלך שע\"י שצעק בקול פשוט הכיר המלך שהוא קול בנו יחידו, ואף שאין בזה תיבות בלשון מדינת המלך, מ\"מ, הנה דוקא זה פעל חידוש הקשר בין המלך ובנו, ומשל ב' מהרה\"ג החסיד מהרלי\"צ ז\"ל מבאַרדיטשוב<sup data-n=\"541\">63</sup> (אוהב ישראל הידוע ומפורסם<sup data-n=\"542\">64</sup>) מענין לבושים פשוטים (דלבושים הם למטה מקול פשוט), דע\"י שלבש הבגדים הפשוטים דוקא, נתחדש הקשר שבין המלך לידידו. דנקודת הענין המובנת משני משלים אלו הוא, דחידוש הברית וההתקשרות שנעשה בראש השנה ע\"י תקיעת שופר אינו מצד בחי' הגילויים [שהרי בקול פשוט אין בו אפילו מלשון מדינת המלך, וכש\"כ לבושים פשוטים שהם למטה מקול], כי אם, באופן חדש שלא הי' עדיין מעולם<sup data-n=\"543\">65</sup>. וזהו ג\"כ הקשר והשייכות דתקיעת שופר בראש השנה עם קול שופר שהי' במ\"ת [כמובא באבודרהם בשם הרס\"ג בטעמי התקיעות (הענין השלישי), וכמבואר גם בהמשך הנ\"ל בהמשל דהרלי\"צ ז\"ל מבאַרדיטשוב דתקיעת שופר דראש השנה הוא אותו הלבוש שהי' במ\"ת, ויהי<sup data-n=\"544\">66</sup> קול השופר], דכשם שקול השופר דמ\"ת הוא המשכת בחי' מקור התענוגים ועד להמשכת העצמות כנ\"ל, עד\"ז הוא גם בענין תקיעת שופר דראש השנה, דענין הברית שמתחדש בראש השנה הוא מהעצמות, וכן התחדשות הרצוןלקיום העולמות ולבחינת מלוכה שע\"י תקיעת שופר (ענין תמליכוני עליכם), מכיון שכל הדברים חוזרים לקדמותם, הוא מהעצמות. וזהו גם מה שהתחלת ברכת שופרות היא בענין מ\"ת, אתה נגלית כו' על הר סיני ללמד לעמך תורה ומצוות, ומסיימים וחותמים שומע קול תרועת עמו ישראל ברחמים, ולפנ\"ז בברכת זכרונות חותמים זוכר הברית שקאי (בעיקר) על הברית דהקב\"ה וישראל, אתם נצבים היום גו' לעברך בברית ה' אלקיך, ולפנ\"ז בברכת מלכיות מסיימים מלך על כל הארץ, שזה נעשה ע\"י שתמליכוני <i>עליכם</i>, וכמו שאומרים לפנ\"ז (בהפסוקים) מלך<sup data-n=\"545\">67</sup> ישראל וגואלו.\n<b>וזהו</b><sup data-n=\"546\">68</sup> מה שבמקדש היו תוקעין גם בראש השנה שחל בשבת, דמכיון דענין תקיעת שופר בראש השנה הוא המשכת בחינת מקור התענוגים שלמעלה מבחינת גילוי (כמו קול השופר שהי' במ\"ת), דבחינה זו היא נעלית מבחינת התענוג דשבת (גם מבחינה הכי נעלית דשבת), לכן צריך לתקוע גם בראש השנה שחל בשבת. ומה שהיו תוקעין רק במקדש ולא במדינה הוא לפי שהמשכת בחינה זו (מקור התענוגים) תלוי' בתנאי המקום, ולכן דוקא בבית המקדש שהי' בו אלקות בגילוי, ועד שהגילוי שבביהמ\"ק הי' בהתלבשות<sup data-n=\"547\">69</sup> באבנים של הבית (ועד\"ז במשכן), הי' אפשר להמשיך בחינה זו. ולכן במקדש היו תוקעין גם בראש השנה שחל בשבת, כי בחינה זו (מקור התענוגים) היא נעלית יותר מבחינת שבת, ואפילו מבחינת שבת כמו שהי' במקדש ובראש השנה.\nז) <b>וכמו</b> שהי' בבית המקדש, עד\"ז הוא גם בתורה. דמיום שחרב ביהמ\"ק אין לו להקב\"ה בעולמו אלא ארבע אמות של הלכה בלבד<sup data-n=\"548\">70</sup>. ולכן אומרים פסוקי שופרות גם בראש השנה שחל בשבת גם בחו\"ל, דכיון שתורה היא בחינת מקדש (ואדם התוקע והשומע<sup data-n=\"549\">71</sup> הרי אין לך בן חורין אלא מי שעוסק בתורה<sup data-n=\"550\">72</sup> (דע\"י עסק התורה כדבעי נעשה ענין החירות בדוגמת שהי' בזמן שביהמ\"ק הי' קיים)), לכן ע\"י אמירת פסוקי שופרות דתורה עושים (דוגמת) אותו הענין שהי' נעשה ע\"י תקיעת שופר במקדש. וזה נעשה בשמחה גדולה, כמבואר בהמשך יו\"ט של ראש השנה שחל להיות בשבת לכ\"ק מו\"ח אדמו\"ר<sup data-n=\"551\">73</sup> שהכתרת המלך היא בשמחה גדולה. ובחינת התענוג שממשיכים ע\"י תקיעת שופר במקדש, ועד\"ז ע\"י פסוקי שופרות (גם בחו\"ל), היא בחינת תענוג הפשוט, ע\"ד המבואר בארוכה בהמשך יו\"ט של ראש השנה שחל להיות בשבת לכ\"ק אדמו\"ר (מהורש\"ב)<sup data-n=\"552\">74</sup> בענין התענוג שהוא דוגמתבחינת יום שכולו שבת ומנוחה לחיי העולמים<sup data-n=\"553\">75</sup>. ומכיון דכל מה שלמעלה הכל הוא ממך (כנ\"ל מתורת הה\"מ), לכן בכחו של כל אחד מישראל לעשות לא רק כל הענינים דהשתלשלות (גם ענינים הכי נעלים), אלא שבכחו לעשות גם התענוג הפשוט, ושזה יומשך גם למטה, מלוך על העולם כולו בכבודך כו' ועד שידע כל פעול כי אתה פעלתו, ועאכו\"כ שיהי' מלך ישראל (כולל) וגואלו, בגאולה האמיתית והשלימה ע\"י משיח צדקנו, שאז יתקעו גם ביו\"ט של ראש השנה שחל להיות בשבת בביהמ\"ק וביבנה<sup data-n=\"554\">76</sup> וי\"ל דגם בכל מקום ומקום (כי אז יתבטלו כל הענינים דגזירות), במהרה בימינו ממש ובשמחה גדולה.\n**********",[["478","*","מאמר זה והמשכו (ד\"ה אדון עולם – דלקמן ע' נט ואילך) יצאו לאור \"לקראת ראש-השנה [ה'תשמ\"ז] . . <i>מוצש\"ק סליחות</i>,<i> ה'תשמ\"ו</i>\"."],["479","1","משנה ר\"ה רפ\"ד (כט, ב)."],["480","2","דערב ר\"ה הוא יום הולדת שלו (\"היום יום\" כט אלול, ערב ר\"ה. ועוד)."],["481","3","נדפס באוה\"ת ר\"ה (כרך ה) ע' ב'קט ואילך. וראה גם ד\"ה להבין המשנה ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380943\" data-slug=\"likkutei-torah\" data-id=\"4001380943\">לקו\"ת ר\"ה (נו, א</a> ואילך) ובסידור (עם דא\"ח) שער התקיעות (רמ, ג ואילך). המשך יו\"ט של ר\"ה תרס\"ו. תש\"ג. <i>ועוד</i>."],["482","4","פינחס כט, א."],["483","5","כ\"ה באוה\"ת שם. וברד\"ה זה תרנ\"ט, תרס\"ה, תש\"ג ועוד: איך <i>דחו</i>. ובסידור שם: איך הי' כח ביד חכמים לעקור."],["484","6","כמסקנת הגמרא (בבלי) בר\"ה שם."],["485","7","אוה\"ת שם."],["486","8","ראה גם המשך תרס\"ו בתחלתו."],["487","9","בהר כה, יח."],["488","10","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380493\" data-slug=\"likkutei-torah\" data-id=\"4001380493\">זח\"ג קיג, א</a>. וראה הגהות הרח\"ו לזהר שם. לקו\"ת שלח מה, ב. ובכ\"מ."],["489","11","ראה תקו\"ז תיקון ל' (עד, סע\"א), הובא ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא פ\"ד</a>. רפכ\"ג. ועוד."],["490","12","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370160\" data-slug=\"torah-or\" data-id=\"3901370160\">ראה קו\"א בתניא ד</a>\"ה להבין מ\"ש בפע\"ח (קנה, ב): שכל המצוות לתקן רמ\"ח אברי ז\"א. וראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370163\" data-slug=\"torah-or\" data-id=\"3901370163\">תו\"א מקץ לד, ד</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370303\" data-slug=\"torah-or\" data-id=\"3901370303\">לה, ג</a>. יתרו סז, ד ואילך. המשך יו\"ט של ר\"ה תש\"ג פ\"ה. ובכ\"מ."],["491","13","אחרי יח, ה. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380879\" data-slug=\"likkutei-torah\" data-id=\"4001380879\">לקו\"ת תצא מ, רע\"ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381137\" data-slug=\"likkutei-torah\" data-id=\"4001381137\">שה\"ש ב, א</a>."],["492","14","תהלים פא, ד. ולהעיר, אשר מזמור זה הוא שירו של יום ר\"ה (ר\"ה ל, ב)."],["493","15","כתר שם טוב (הוצאת קה\"ת) סקי\"ט (טז, א). סרנ\"ו (לה, א)."],["494","16","לקו\"א להה\"מ (הוצאת קה\"ת) סקצ\"ח (נ, סע\"ג). או\"ת קיב, ב (בהוצאת קה\"ת תש\"מ ואילך – סת\"פ)."],["495","17","אבות פ\"ב מ\"א."],["496","18","שו\"ע (ודאדה\"ז) או\"ח סס\"א ס\"ב. וראה פרש\"י עה\"פ ואתחנן ו, ו. מספרי שם."],["497","19","פרש\"י עה\"פ תבוא כו, טז (וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300241193\" data-slug=\"likkutei-sichot\" data-id=\"1300241193\">לקו\"ש חכ\"ד ע' 193</a> הערה 40)."],["498","20","וראה גם לקמן (ס\"ע נט) ד\"ה אדון עולם ס\"ב בתחלתו."],["499","21","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380883\" data-slug=\"likkutei-torah\" data-id=\"4001380883\">לקו\"ת תבוא מא, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380907\" data-slug=\"likkutei-torah\" data-id=\"4001380907\">נצבים מז, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380951\" data-slug=\"likkutei-torah\" data-id=\"4001380951\">ר\"ה נח, א</a>. עט\"ר שער ר\"ה בתחלתו. ובכ\"מ."],["500","22","ר\"ה טז, א. לד, ב."],["501","23","ראה מכילתא (ויל\"ש) עה\"פ יתרו כ, ג. פרש\"י עה\"פ אחרי יח, ב. וראה המשך יו\"ט של ר\"ה תש\"ג פכ\"ו (סה\"מ תש\"ג ע' 69)."],["502","24","תפלת מוסף דראש השנה."],["503","25","סי' יד."],["504","26","בתחלתו (ג, ב). וראה גם לקו\"ת ר\"ה שם."],["505","27","בהבא לקמן – ראה אוה\"ת שבהערה 3."],["506","28","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380947\" data-slug=\"likkutei-torah\" data-id=\"4001380947\">לקו\"ת ר\"ה נז, א</a>. סידור (עם דא\"ח) רמג, א."],["507","29","ברכות מט, א."],["508","30","ביצה יז, א."],["509","31","תשא לא, טז."],["510","32","יתרו שם, ח."],["511","33","ד\"ה את שבתותי ה'ש\"ת פ\"ב – סה\"מ ה'ש\"ת ע' 81 ואילך (ולהעיר גם מ<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380252\" data-slug=\"likkutei-torah\" data-id=\"4001380252\">לקו\"ת בהר</a> רד\"ה את שבתותי – מא, א). וראה שם פ\"ד – ס\"ע 85 ואילך (ובכ\"מ), שבפרטיות יש ג' מדריגות בשבת."],["512","34","שבת קיח, א."],["513","35","ישעי' נח, יג."],["514","36","בראשית ב, א."],["515","37","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560084\" data-slug=\"or-hatorah-hb\" data-id=\"8316560084\">אוה\"ת</a> ד\"ה ויכולו (בראשית מב, ב ואילך. שם כרך ג תקח, ב ואילך)."],["516","38","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380946\" data-slug=\"likkutei-torah\" data-id=\"4001380946\">לקו\"ת ר\"ה נו, ד</a> ואילך. סידור (עם דא\"ח) רמב, ג ואילך."],["517","39","שבהערה 3 (ע' ב'קי)."],["518","40","ויק\"ר פכ\"ט, ו. מדרש תהלים פא, ד."],["519","41","ויחי מט, כא."],["520","42","ועד\"ז במשנת חסידים מס' ליל ר\"ה פ\"ח מ\"ב. – הובאו ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380500\" data-slug=\"likkutei-torah\" data-id=\"4001380500\">לקו\"ת שלח מז, א</a>."],["521","43","לקו\"ת דרושי ש\"ש סו, ג. המשך יו\"ט של ר\"ה תש\"ג פט\"ו. ובכ\"מ."],["522","44","ויתירה מזו, ששבת פועל שינוי (לא רק בטבע דישראל, אלא) גם בסמבטיון (ב\"ר פי\"א, ה. תנחומא תשא לג. וראה גם סנהדרין סה, ב ובפרש\"י שם ד\"ה נהר סבטיון יוכיח), גשם <i>העולם</i>."],["523","45","ירושלמי דמאי רפ\"ד. רמב\"ם הל' מעשר רפי\"ב. וראה לקו\"ש ח\"ד ע' 1038 הערה 24."],["524","46","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380948\" data-slug=\"likkutei-torah\" data-id=\"4001380948\">לקו\"ת ר\"ה נז, ב</a> ואילך. סידור (עם דא\"ח) רמג, סע\"א ואילך."],["525","47","ויתירה מזו, שהוא למעלה גם מבחינת מתנה דשבת, כמבואר באוה\"ת שבהערה 3 בסיום המאמר (ע' ב'קיד)."],["526","48","פ\"ד (ע' ב'קיא ואילך)."],["527","49","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380472\" data-slug=\"likkutei-torah\" data-id=\"4001380472\">לקו\"ת שלח מ, א</a>. עט\"ר דרוש לעשי\"ת נח, סע\"ב ואילך. המשך תרס\"ו ע' נו. ועוד."],["528","50","התיווך בזה – ראה לקמן (ע' סב ואילך) ד\"ה אדון עולם ס\"ה."],["529","51","פ\"ב ופ\"ד."],["530","52","עמוס ג, ו."],["531","53","ולהעיר, שזהו אחד מטעמי תק\"ש בר\"ה – רס\"ג, הובא באבודרהם בטעמי התקיעות (ענין השביעי). וראה טור (ונ\"כ) ר\"ס תקפא; השלמה לשו\"ע אדה\"ז או\"ח שם; אוה\"ת נצבים ע' א'רפ ואילך – בנוגע לתק\"ש בחודש אלול."],["532","54","יתרו יט, טז. – ולהעיר שזהו אחד מטעמי תק\"ש בר\"ה – רס\"ג הובא באבודרהם שם (הענין השלישי), הובא להלן בפנים."],["533","55","יתרו כ, טו."],["534","56","תפלת מוסף דר\"ה (ברכת שופרות)."],["535","57","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380507\" data-slug=\"likkutei-torah\" data-id=\"4001380507\">שבת קה, א</a> (<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316460086\" data-slug=\"or-hatorah-hb\" data-id=\"8316460086\">ע\"פ</a> גירסת העין יעקב). וראה לקו\"ת שלח מח, סע\"ד. אוה\"ת יתרו ע' תתקא ואילך."],["536","58","<a class=\"ft-cite\" href=\"#/read/tanya/3401310039\" data-slug=\"tanya\" data-id=\"3401310039\">ראה שבת פח, ב</a>. בשבת שם \"יצתה\", אבל בתניא (רפל\"ד, פל\"ו) <i>ובכ\"מ</i> הובא \"פרחה\". וראה שמו\"ר פכ\"ט, ד. שהש\"ר פ\"ה, טז (ג)."],["537","59","ראה סידור (עם דא\"ח) רמו, א-ב."],["538","60","נצבים כט, ט-יא. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380895\" data-slug=\"likkutei-torah\" data-id=\"4001380895\">לקו\"ת נצבים מד, א</a>-ב."],["539","61","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380883\" data-slug=\"likkutei-torah\" data-id=\"4001380883\">לקו\"ת</a> שם. וראה גם לקו\"ת ר\"פ תבוא (מא, ג), מרמ\"ז לזח\"ב לב, ב. וראה גם זח\"ג רלא, א. פענח רזא ס\"פ נצבים."],["540","62","תרל\"ז, פ\"ע. וראה לקמן (ע' סד ואילך) ד\"ה אדון עולם ס\"ח ואילך."],["541","63","מספר קדושת לוי (ר\"ה צו, א)."],["542","64","ראה סה\"ש ה'ש\"ת ע' 115. וראה גם לקמן (ע' סו) ד\"ה אדון עולם ס\"י."],["543","65","ראה אגה\"ק סי\"ד."],["544","66","יתרו יט, יט."],["545","67","ישעי' מד, ו."],["546","68","בהבא לקמן ראה אוה\"ת שבהערה 3 פ\"ז (ע' ב'קיד)."],["547","69","ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158670028\" data-slug=\"or-hatorah-hb\" data-id=\"8158670028\">אוה\"ת ויצא קעח, ב</a>. סה\"מ תרפ\"ז ע' פד."],["548","70","ברכות ח, א."],["549","71","ראה שו\"ע אדה\"ז או\"ח סתקפ\"ה ס\"ד: קודם שיתקע יברך כו' לשמוע קול שופר כו' לפי שהתקיעה אינה עיקר המצוה אלא שמיעת קול שופר הוא עיקר המצוה כו'."],["550","72","אבות פ\"ו מ\"ב."],["551","73","תש\"ג, רפ\"ב."],["552","74","תרס\"ו ע' תקמד-ה."],["553","75","תמיד בסופה."],["554","76","ראה משנה ר\"ה רפ\"ד (כט, ב)."]]],[1500360009,"<h3>בס\"ד. יום ב' דראש-השנה ה'תשמ\"ג<sup data-n=\"555\">*</sup></h3>\n<b>אדון</b> עולם אשר מלך בטרם כל יצור נברא<sup data-n=\"556\">1</sup>, ומדייק בזה כ\"ק מו\"ח אדמו\"ר במאמרו ד\"ה זה<sup data-n=\"557\">2</sup> [בהמשך המתחיל יו\"ט של ראש השנה שחל להיות בשבת, שבו מבאר (במאמר הראשון<sup data-n=\"558\">3</sup>) דהכתרת המלך היא בשמחה גדולה], דצריך להבין, איך תתכן המלוכה בטרם כל יצור נברא, והרי המלוכה היא על הזולת דוקא כמאמר<sup data-n=\"559\">4</sup> אין מלך בלא עם, ויתירה מזו, דמלוכה היא דוקא על מי שבערכו, היינו שהעם הוא בדומה להמלך, דלא זו בלבד שענין המלוכה (באדם) הוא דוקא על בני אדם ולא על בעלי חיים (דגם כשיהי' לאדם אלף אלפים בעלי חיים אין שייך שיהי' מלך עליהם), הנה גם בבני אדם גופא צריך שיהי' להעם איזה שייכות ודמיון להמלך, כידוע<sup data-n=\"560\">5</sup> שעם (אין מלך בלא עם) הוא מלשון עמו, ואיך יתכן ענין המלוכה בטרם כל יצור נברא. ומבאר זה בהקדים מ\"ש בשל\"ה<sup data-n=\"561\">6</sup> (ובכמה ספרים<sup data-n=\"562\">7</sup>) גודל השבח דאדון עולם, ועד שאדון עולם בגימטריא אין סוף<sup data-n=\"563\">8</sup>, דענין אין סוף הוא דרגא הכי נעלית באלקות, ויתירה מזו שהוא למעלה מענין הדרגות, דאמיתית ענין אין סוף הוא<sup data-n=\"564\">9</sup> בעצמותו ית'. ועפ\"ז מבאר ענין אדון עולם אשר מלך בטרם כל יצור נברא, דמכיון שאדון עולם הוא (בגימט') אין סוף, הרי מובן, דענין אדון עולם אשר מלך כו' הוא בחינת המלכות כמו שמושרשת כביכול בעצמותו ית' (אמיתית ענין א\"ס), ומכיון שעצמותו ית' הוא כל יכול, שייך שיהי' מלך גם בלא עם, בטרם כל יצור נברא.\nב) <b>והנה</b> מאמר זה בא, כנ\"ל, בהמשך להמאמר ד\"ה יו\"ט של ראש השנה שחל להיות בשבת, שבו מבאר בארוכה הענין דתקיעת שופר בראש השנה, שהעבודה דתקיעת שופר היא ענין כללי שכולל כל פרטי העבודות דכל השנה. כי ענין תקיעת שופר הוא כמארז\"ל<sup data-n=\"565\">10</sup> אמרו לפני בראש השנה כו' מלכיות כדי שתמליכוני עליכם כו' ובמה בשופר, ומכיון דכל הציוויים שלמעלה (מצוות) שייכים דוקא לאחרי שהוא ית' נעשה מלך, כמאמר<sup data-n=\"566\">11</sup> קבלו מלכותי תחלה ואח\"כ אגזורעליכם גזירות, הרי, שהעבודה דתקיעת שופר שענינה הוא שתמליכוני עליכם היא השורש לכל המצוות (העבודות) שבמשך כל השנה. ומבאר שם, דענין שתמליכוני עליכם שע\"י תקיעת שופר הוא המשכת הרצון למלוכה (בדוגמת הכתרת מלך בו\"ד, שבאה בשמחה גדולה ובביטול עצום אל המלך, שעי\"ז מתעורר המלך ברצון לחפוץ במלוכה). והטעם מה שעבודתם של ישראל מעוררת אצלו ית' הרצון למלוכה הוא לפי שגם לפנ\"ז יש לו רצון לזה, אלא שרצון זה הוא בהעלם, והעבודה דישראל ממשיכה את הרצון מההעלם אל הגילוי. והסיבה לזה שיש רצון נעלם למלוכה היא, לפי שענין הרצון למלוכה ישנו גם לפנ\"ז (לפני הרצון הנעלם), והוא הרצון המוחלט בעצמותו. ובאמת לא יתכן לומר על זה דהרצון למלוכה יש גם מקודם (כמו שאומרים בנוגע לרצון הנעלם, דגם טרם שנתעורר ברצון הגלוי יש כבר הרצון בהעלם), כי בעצמותו ית' אין שייך לומר שיש שם איזה ענין שהוא בהעלם, והכל שם הוא בבחינת אחדות הפשוטה בתכלית הפשיטות. וענין תמליכוני עליכם שע\"י תקיעת שופר הוא לא רק להמשיך הרצון למלוכה מההעלם אל הגילוי, מבחינת הרצון כמו שהוא כלול בהעלם באוא\"ס שלפני הצמצום (בהבחינה דגילוי לעצמו), כי אם, שעי\"ז נמשך גם מרצון המוחלט בעצמותו, דרצון זה הוא כביכול העצמות גופא (ואין שייך לומר עליו שהוא כלול בהעלם). והמשכה זו בראש השנה היא ע\"י תמליכוני עליכם, רצון למלוכה, ומזה נמשך אח\"כ הרצון דמצוות (גזירות), דעיקר ענין המצוות הוא הרצון למעלה. וכמבואר בכ\"מ<sup data-n=\"567\">12</sup>, דמה שקיום המצוות צריך להיות דוקא בפרטיות ובדיוק (כפי שנצטוינו), הוא, כי ברצון נוגע שכל פרט ופרט יהי' כפי הרצון.\nג) <b>ומבאר</b> בהמאמר (ד\"ה אדון עולם<sup data-n=\"568\">13</sup>), דע\"י מעשה המצוות נעשה בנין הכלים דז\"א, וגם המשכת האור בהכלים דז\"א. וענין זה שייך גם ל(התחלת ההמשך) יו\"ט של ראש השנה שחל להיות בשבת במקדש היו תוקעין אבל לא במדינה<sup data-n=\"569\">14</sup>, כמ\"ש בהמאמר דאדמו\"ר הצ\"צ<sup data-n=\"570\">15</sup> (שעליו מיוסד המאמר שנאמר בערב ראש השנה) הטעם על מה שבראש השנה שחל להיות בשבת אין תוקעין במדינה, כי המצוות שלנו הוא (בכדי) שע\"י אתעדל\"ת אתעדל\"ע, שע\"י עשיית המצוות דהאדם נעשים המצוות שלמעלה (רמ\"ח פיקודין אינון רמ\"ח אברין דמלכא<sup data-n=\"571\">16</sup>). דכמו\"כ הוא גם במצות תקיעת שופר שענינה הוא בכדי לעשות עי\"ז בחינת השופר שלמעלה, ולכן בראש השנה שחל בשבת אין תוקעין (במדינה), כי בשבת יש בחינת השופר שלמעלה (בחינת התענוג) גם בלי עבודת האדם, מצד השבת, ושבת הרי מקדשא וקיימא<sup data-n=\"572\">17</sup>. ומה שבמקדש היו תוקעין גם בראש השנה שחל בשבת הוא לפי שבמקדש, שזה שער השמים<sup data-n=\"573\">18</sup>, הי' נתינת כח לעשות בחינה נעלית יותר בתענוג(כמשנ\"ת בארוכה בהמאמר דערב ראש השנה). וענין זה, דהמצוות (הענינים) שלמעלה נעשים דוקא ע\"י קיום המצוות דהאדם, הוא בכל הבחינות וכל הפרצופים דכל סדר ההשתלשלות, כתורת הרב המגיד<sup data-n=\"574\">19</sup> בפירוש המשנה<sup data-n=\"575\">20</sup> דע מה למעלה ממך דכל מה שלמעלה הוא ממך. דבחינת התענוג (שופר) שלמעלה נעשית (כנ\"ל) על ידי קיום מצות תקיעת שופר, ובחינת המוחין שלמעלה (שהו\"ע התפילין, כידוע<sup data-n=\"576\">21</sup> דד' הפרשיות הם בחינת ד' מוחין) נעשית ע\"י קיום מצות תפילין, דעל ידי שהאדם מניח תפילין עושה שהקב\"ה מניח תפילין<sup data-n=\"577\">22</sup>, וכן הוא גם בהמדות (דז\"א), דעל ידי שהאדם שלמטה מקיים מצות ואהבת את הוי' אלקיך ומצות את הוי' אלקיך תירא<sup data-n=\"578\">23</sup> (דאהוי\"ר הם השרש לכל המצוות<sup data-n=\"579\">24</sup>) נעשה עי\"ז הבנין דז\"א, וכן הוא גם בבחינת המלכות, דבנין עולם הדיבור (מלכות) נעשה ע\"י הדיבור של אדם התחתון בדברי תורה ודברי תפלה. וזהו תוכן הענין דקיום המצוות (לפי המבואר במאמרים אלו), כי הבחינות שלמעלה הם (בכלל) במספר רמ\"ח (רמ\"ח אברין דמלכא), ובנין כל הבחינות שלמעלה הוא על ידי קיום רמ\"ח מצוות עשה (דהאדם), וכמ\"ש<sup data-n=\"580\">25</sup> ועשיתם אותם, אתם כתיב, מעלה אני עליכם כאילו עשאוני<sup data-n=\"581\">26</sup>.\nד) <b>וצריך</b> להבין, הרי ידוע<sup data-n=\"582\">27</sup> שהעילוי בקיום המצוות הוא כשהקיום הוא מפני שזהו <i>ציווי</i> הקב\"ה (וכנוסח ברכת המצוות אשר קדשנו במצותיו וצונו) ולא מצד הטעם<sup data-n=\"583\">28</sup> והסגולה שבהם, כולל גם הטעם שע\"י קיום המצוות נעשים המצוות שלמעלה. ויש לומר הביאור בזה, דבמצוות (הרצון והציווי דלמעלה שבנ\"י יקיימו מצוות) יש שני ענינים. הסיבה והטעם על הציווי, ומזה נעשה מציאות המצוה (הציווי), שהוא מסובב מהטעם. ואח\"כ (לאחרי הציווי דלמעלה) באה עשיית המצוה ע\"י האדם שמקיים אותם. ובזה שני אופנים כלליים. אופן הא' שמקיימה לתכלית הציווי (שיושלם הטעם דהציווי), ואופן הב' הוא שמקיימה באופן נעלה יותר, דקיום המצוה שלו הוא באופן שעי\"ז הוא עושה כביכול רצון חדש, שלמעלה באין ערוך מהרצון המסובב מהטעם. דלהיות שישראל מושרשים בעצמות (בעל הרצון), ישראל ומלכא בלחודוהי<sup data-n=\"584\">29</sup>, לכן כשישראל מקיים מצוה, ביכלתו לעשות רצון חדש שלא הי'לפני זה. ויש לומר דעד\"ז הם שני הפירושים במאמר רז\"ל<sup data-n=\"585\">30</sup> נחת רוח לפני שאמרתי ונעשה רצוני<sup data-n=\"586\">31</sup>. פירוש הא' הוא, שע\"י קיום המצוה נתקיים הרצון (הציווי) שהי' בתחילה. ופירוש הב' בנעשה רצוני הוא, דע\"י קיום המצוה דישראל (כאופן הב') נעשה (נתחדש) רצון חדש שלא הי' לפנ\"ז (ע\"ד המבואר בכ\"מ<sup data-n=\"587\">32</sup> בפירוש עושין רצונו של מקום<sup data-n=\"588\">33</sup>, דפירוש עושין הוא שעושים רצון חדש). ועפ\"ז יש לומר, דמ\"ש בדרושים הנ\"ל דענין המצוות הוא בכדי לעשות עי\"ז המצוות דלמעלה, זהו באופן הא' דקיום המצוות, בבחי' מקיימים הרצון המסובב מהטעם, שיהי' הבנין דכל סדר ההשתלשלות, רמ\"ח אברין דמלכא [ובזה גופא שני ענינים, א', הטעם והסיבה (דהרצון) – שיתהוו המצוות (הבחינות) למעלה. ב', המסובב – הרצון שישראל יקיימו המצוות למטה]. אבל עשיית המצוות מצד שישראל מושרשים בעצמות הוא לעשות רצון חדש. וזהו מה שמבואר בריבוי דרושים&lt;27&gt; שהעילוי בקיום המצוות הוא כשהקיום הוא מפני שזהו רצון (ציווי) הקב\"ה, ולא מצד הטעם (כולל גם הטעם מה שע\"י קיום המצוות נעשים המצוות שלמעלה), כי רצון זה הוא רצון שלמעלה מהטעם. ועשיית המצוות (מצד רצון זה) הוא לא בכדי לפעול ענינים למעלה, כי אם, מצוה מלשון צוותא וחיבור<sup data-n=\"589\">34</sup>, היחוד דישראל עם בעל הרצון, ועד להיחוד עם העצמות. וע\"ד מאמר אדמו\"ר הזקן<sup data-n=\"590\">35</sup> איך וויל זע גאָר ניסט איך וויל ניט דיין ג\"ע איך וויל ניט דיין עוה\"ב כו' איך וויל מער ניט אז דיך אַליין.\nה) <b>ועפ\"ז</b> יובן גם מה שמבואר בדרוש הנ\"ל דאדמו\"ר הצ\"צ<sup data-n=\"591\">36</sup>, דהתענוג הפרטי שבכל מצוה, מה שבכל מצוה יש תענוג מיוחד, הוא נעלה יותר מהתענוג והרצון הכללי שבכל המצוות בשוה, ושרשו הוא מבחי' מקור התענוגים (שלמעלה מבחינת גילוי התענוג), דלכאורה אינו מובן איך זה מתאים עם המבואר בריבוי דרושים&lt;27&gt; שהכוונה הכללית שבכל המצוות בשוה (וצונו) היא נעלית יותר מהכוונה הפרטית דכל מצוה בפרט. ויש לומר הביאור בזה, דבדרוש הנ\"ל דאדמו\"ר הצ\"צ מדובר בענין הרצון במצוות כמו שהוא מסובב מהטעם, בכדי שיתהוו המצוות שלמעלה. ומה שמבואר שם דבמצוות יש שתי בחינות, ענין הכללי שבכל המצוות בשוה, וענין הפרטי שבכל מצוה בפרט, הנה שתי הבחינות הן בהרצון שמצד הטעם. שבתחלת המשכתו הוא רצון כללי שייעשו הענינים למעלה ע\"י קיום המצוות דהאדם, ומזה נמשך אח\"כ (למטה יותר) רצון פרטי לכל מצוה ומצוה בפרט, בכדי שע\"י קיומה תיעשה אותה המצוה דלמעלה שבדוגמתה (ע\"י שופר דלמטה, שופר שלמעלה. וכן בשאר המצוות). ולכן אומר שם דיש מעלה בתענוג וכוונה הפרטית(ועד דשרש התענוג הפרטי דוקא הוא בבחינת מקור התענוגים), כי הכוונה ברצון זה היא לעשות המצוות (פרטי ענינים) שלמעלה, וזה נעשה דוקא ע\"י הפעולה הפרטית דכל מצוה. ומה שמבואר בריבוי דרושים דהכוונה הכללית שבכל המצוות בשוה היא נעלית יותר, הוא, כי שם מדובר בהרצון שישראל מחדשים ועושים ע\"י עבודתם, ומצד רצון זה, אופן קיום המצוות הוא לעשות רצון, כוונה כללית.\nו) <b>והנה</b> שני האופנים הנ\"ל בקיום המצוות [מפני ובאופן הציווי דלמעלה, והחידוש שנעשה ע\"י ישראל] הם, כמובן, גם במצות תקיעת שופר. דהגם שגם ענין הפרטי דשופר (שמצד הציווי) הוא למעלה ממדידה והגבלה. דאף שגם במצות תקיעת שופר יש שיעור ומדה (כברוב המצוות<sup data-n=\"592\">37</sup>) בנוגע למספר הקולות ואופני הקולות<sup data-n=\"593\">38</sup> וכיו\"ב, הרי ענינה (התוכן והכוונה) דמצוה זו הוא העבודה שלמעלה ממדידה והגבלה, וכידוע<sup data-n=\"594\">39</sup> שענין תקיעת שופר הוא הצעקה מעומקא דלבא שלמעלה ממדידת והגבלת השכל, בחינת בכל מאדך. ועד\"ז (ובמכ\"ש) הוא בבחינת השופר שלמעלה (שנעשה ע\"י תקיעת שופר דהאדם), שהוא למעלה ממדידה והגבלה, שהרי השופר שלמעלה הוא בחינת מקור התענוגים שלמעלה מתענוג פרטי כמבואר בארוכה בדרוש הנ\"ל דאדמו\"ר הצ\"צ. ונמצא, דהגם שהענין דתקיעת שופר כמו שהוא מצד הציווי מלמעלה הוא בבחינת בלי גבול [והציווי מלמעלה הוא האתעדל\"ע והנתינת כח על זה שהעבודה דתקיעת שופר תהי' באופן דבכל מאדך], אעפ\"כ, מכיון שישראל מושרשים בעצמות, יש ביכולתם לעשות רצון וענין חדש, המשכת רצון המוחלט בעצמותו שהוא כמובן למעלה גם מבחי' מקור התענוגים הנ\"ל. וכנ\"ל (בתחלת המאמר) דענין תמליכוני עליכם שע\"י תקיעת שופר היא ההמשכה (גם) מרצון המוחלט בעצמותו.\nז) <b>ויש</b> לומר שזהו ג\"כ זה שתקיעת שופר מתחיל בקול פשוט דוקא כמבואר בארוכה בסידור ד\"ה להבין ענין תקיעת שופר ע\"פ כוונת הבעש\"ט ז\"ל, דקול פשוט זה מעורר הפשטות (והפשיטות) דישראל, והפשטות דישראל הוא חד עם פשיטות העצמות<sup data-n=\"595\">40</sup>. וי\"ל שזהו ג\"כ מהטעמים דגודל ההשתדלות דהבעש\"ט [ועוד לפני התגלותו כבעש\"ט] שאנשים פשוטים וגם קטנים וקטנות יאמרו ברוך השם וכיו\"ב [וסיפור פרט זה (דהנהגת הבעש\"ט) נמסר לנו ע\"י רבותינו נשיאינו<sup data-n=\"596\">41</sup>, היינו שזוהי הוראה ונתינת כח לכאו\"א], כי כאשר איש פשוט אומר ברוך השם וכיו\"ב, כוונתו בזה היא להעצמות<sup data-n=\"597\">42</sup> (כידוע<sup data-n=\"598\">43</sup> דמה ששם שמים שגור בפי כל הוא העצמות).ועד\"ז הוא גם בקיום המצוות, דקיום המצוות דאיש פשוט הוא לא מפני שע\"י קיומו המצוות נעשים הענינים למעלה, דאיש פשוט אינו יודע (עדיין) מה למעלה ומה למטה ומה בד' סטרין, אלא מפני הציווי, אשר קדשנו במצוותיו וצונו. וזהו\"ע קול פשוט דתקיעת שופר, דלאחרי כל ההשגות בהעילוי שנעשה ע\"י קיום המצוות, דע\"י קיום המצוות דהאדם נעשים המצוות שלמעלה, וכמו במצות תקיעת שופר דעי\"ז נעשה שופר שלמעלה, הנה תכלית השלימות הוא לקיים המצוה בפשטות [וי\"ל שהוא ע\"ד נעוץ תחלתן בסופן<sup data-n=\"599\">44</sup>. דכמו שתחילת העבודה (לפני ששייך לכוונות) היא בפשטות, עד\"ז הוא גם בגמר וחותם (שלימות) העבודה], ועי\"ז דוקא ממשיכים ונעשים דבר אחד עם פשיטות העצמות.\nח) <b>ועפ\"ז</b> יובן גם מה שמבואר בדרושי אדמו\"ר מהר\"ש<sup data-n=\"600\">45</sup> (שענינו הוא מלכתחילה אַריבער<sup data-n=\"601\">46</sup>) שני משלים על תקיעת שופר. משל א' בשם הבעש\"ט ז\"ל מבן מלך שהלך בדרך רחוקה וכו' ועד ששכח גם לשון מדינתו והתחיל לצעוק בקול פשוט (בהמשל שם אומר הלשון בקול גדול, אבל בהנמשל אומר הלשון בקול פשוט<sup data-n=\"602\">47</sup>) שאביו יכירו בטביעת עין דקלא. ומשל ב' מהרה\"ג החסיד מהרלי\"צ ז\"ל מבאַרדיטשוב<sup data-n=\"603\">48</sup> מענין לבושים כשהמלך הי' ביער (שאינם בגדי מלכות כלל<sup data-n=\"604\">49</sup>), כמבואר שם בארוכה הפרטים שבזה. דלכאורה תמוה, הרי ידוע שבראש השנה צריך ליזהר מלהזכיר ענינים ותוארים בלתי רצויים, שלכן אין אומרים וידוי וכו' בראש השנה<sup data-n=\"605\">50</sup>, וצריך לדבר אז רק במעלתם ושבחם של ישראל, וכאן מבאר תקיעת שופר דראש השנה במשלים אלו שרוב הפרטים שבהם הם לכאורה ענינים דהיפך השבח<sup data-n=\"606\">51</sup> [ודייקתי מטעם זה בהמאמר דערב ראש השנה להזכיר ולדבר רק נקודת התוכן דשני משלים אלו, ולא הפרטים]. והגם שמאמר הנ\"ל (שבו נתבארו בפרטיות שני משלים אלו) נאמר בש\"פ תבוא ולא בראש השנה<sup data-n=\"607\">52</sup>, אעפ\"כ, הרי משלים אלו הם ביאור על ענין תקיעת שופר דראש השנה. וגודל התמי' שבזה, זה גופא מוכיח דכל הפרטים שבמשלים אלו הם (בפנימיות הענינים) לשבח<sup data-n=\"608\">53</sup>.<b>ויובן</b> זה ע\"פ הידוע דמה שתקיעת שופר הוא בקול פשוט דוקא הוא לפי דבראש השנה הוא לעברך בברית הוי' אלקיך<sup data-n=\"609\">54</sup>, דברית זה הוא התקשרות עצמית דהקב\"ה וישראל (העוברים ביחד בין הבתרים) להיות דבר אחד ממש<sup data-n=\"610\">55</sup>. ומכיון דהתקשרות זו היא ההתקשרות דעצם הנשמה עם העצמות, פשיטות דעצם הנשמה עם פשיטות העצמות<sup data-n=\"611\">56</sup>, לכן גם זכרון הברית וההתקשרות הוא ע\"י קול פשוט דוקא (שאינו מלובש באותיות)<sup data-n=\"612\">57</sup>, כי אותיות (גם אותיות הכי נעלות) הן הגבלה, וזכרון הברית וההתקשרות דפשיטות עצם הנשמה עם פשיטות העצמות הוא ע\"י קול פשוט דוקא. וזהו מה שהמשל על תקיעת שופר הוא מבן מלך ששכח גם הלשון, דשכחה זו היא למעליותא. דמכיון שהאותיות (הלשון) הם מגבילים, לכן בכדי לבוא ולהגיע לבחינת הפשיטות צריך לשכוח הלשון. וע\"ד ר\"ז<sup data-n=\"613\">58</sup> צם מאה<sup data-n=\"614\">59</sup> תעניתא לשכוח תלמוד בבלי בכדי שיוכל ללמוד תלמוד ירושלמי, ובדוגמת העמוד שבין געה\"ת לגעה\"ע שענינו הוא (כמבואר בתו\"א<sup data-n=\"615\">60</sup>) שכחת וביטול ההשגה וחיזו דגעה\"ת, דאז דוקא יכול לקבל הגילוי דגעה\"ע. וכמו שהוא בג\"ע שההשגה דגעה\"ת מבלבלת לההשגה דגעה\"ע, עד\"ז הוא (ובמכ\"ש) בענין גילוי בחינת הפשיטות שלמעלה מהשגה לגמרי, דכללות ענין ההשגה (גם השגה הכי נעלית) מבלבל לגילוי בחינת הפשיטות. וע\"ד המבואר בעטרת ראש<sup data-n=\"616\">61</sup> טעם המ\"ד<sup data-n=\"617\">62</sup> מצוות אין צריכות כוונה (היינו שקיום המצוות צ\"ל בקבלת עול בלא טעם וכוונה), דלכאורה יש להפליא מאי איכפת לן אם יצרף גם הכוונה<sup data-n=\"618\">63</sup>, ומבאר בזה<sup data-n=\"616\">61</sup>, שהכוונה עושה גרעון אור כביכול בגוף קבלת עול המצוות שאינה דרך עול כ\"כ. דכוונת (וטעם) המצוה, גם בדרגא הכי עליונה, היא בגדר תואר ציור והגבלה, משא\"כ המצוה שבדרך קבלת עול שרשה היא ברצון ותענוג הפשוט, והטעם מחליש כביכול את התוקף והבהירות דעצם המצוה. ומזה מובן גם בענין קול פשוט דתק\"ש, שצ\"ל שכחת וביטול הלשון, דעי\"ז דוקא מגיע לבחינת הפשיטות.\nט) <b>ועד\"ז</b> הוא גם במשל הב', מענין הלבושים, דהלבושים אף שהם לכבוד ולתפארת, כמו בגדי מלכות (וכן בגדים יקרים בכלל), הם במדידה והגבלה. דהנה (בנמשל) הלבושים הו\"ע התורה והמצוות, דמצוות הם לבושיםכמבואר בתניא<sup data-n=\"619\">64</sup>, וכמובן גם ממה שאמר הקב\"ה לאברהם אבינו בא לבוש לבושי<sup data-n=\"620\">65</sup>, וגם התורה היא לבוש כמ\"ש<sup data-n=\"621\">66</sup> לבש ה' עוז התאזר ואין עוז אלא תורה<sup data-n=\"622\">67</sup>. ובהיות שהעבודה דראש השנה היא ההתקשרות דישראל עם עצמותו ית' כמו שהוא למעלה מבחינת מלך (שהרי בראש השנה צריך <i>לעשות</i> שיהי' מלך, שתמליכוני עליכם), ומכ\"ש למעלה מענין הגזירות (שבאים לאחרי שנעשה כבר מלך), הנה בכדי להגיע לזה צריך להיות ביטול לבושי מצוות (וע\"ד שנת\"ל בענין שכחת וביטול הלשון). ולכן המשל על תקיעת שופר הוא מבגדים פשוטים דוקא, דבגדים אלו מורים על ההתקשרות עם עצמותו ית' כמו שהוא למעלה מבחינת מלך<sup data-n=\"623\">68</sup>, כמו שמאריך בהמשל דבגדים אלו הם כשהמלך הי' ביער לפני שהשיב אותו על כסא מלכותו, וגם בהנמשל מבאר דבגדים אלו הו\"ע הלבוש שהי' בזמן מ\"ת כשהמלכנו אותו ית' בשופר קודם מ\"ת עצמו, היינו לפני (למעלה) שנעשה מלך.\nי) <b>והגם</b> דהלשונות שאומר שם (בהמשל וגם בהנמשל) כפי שהם בפשטות אינם מדברים בשבחן של ישראל, הרי אומר בהמאמר שם דמשל זה הוא מהרה\"ג החסיד מהרלי\"צ ז\"ל מבאַרדיטשוב, וידוע ומפורסם בכל העולמות דהרלוי\"צ ז\"ל הי' אוהב ישראל ומליץ יושר על כאו\"א מישראל ומכריע את כאו\"א מישראל לכף זכות ובאופן דמלכתחילה אַריבער, ולכן, כשאומר בהמאמר דמשל זה הוא מהרלוי\"צ ז\"ל, מובן בפשטות דכל הלשונות שאומר שם הם למעליותא. וה\"ז שיטתו ודרכו בנוגע לבני ישראל, כידוע פירושו של הרלוי\"צ ז\"ל בהפסוקים שבתחלת ספר ישעי', שיש שם תוארים דבני ישראל שהם לכאורה כו', ומפרש הרה\"צ מבאַרדיטשוב דתוארים אלו מורים על שבחם של ישראל [וכדמוכח גם מזה שתוארים אלו נאמרו בספר ישעי', דישעי' הוא נביא הישועה, כשמו ישעי' מלשון ישועה<sup data-n=\"624\">69</sup>], ולא עוד אלא שהם שבחים נעלים ביותר שאין בתוארי שבח דוגמתם. וי\"ל, דע\"פ הידוע<sup data-n=\"625\">70</sup> בפירוש מארז\"ל<sup data-n=\"626\">71</sup> נפרעין מן האדם מדעתו ושלא מדעתו (ועד\"ז בפירוש לשון המשנה<sup data-n=\"627\">72</sup> \"דין וחשבון\"), דכאשר אדם אומר פסק דינו של אדם אחר הוא פוסק בזה גם על עצמו, הרי פסק דינו של הרה\"צ מבאַרדיטשוב בנוגע לתוארים הנ\"ל שבישעי' הוא גם פס\"ד בנוגע לתוארים הנ\"ל שבתורות ומשלים שלו.יא) <b>ובפרט</b> שכבר הי' לעולמים, ומעשה רב<sup data-n=\"628\">73</sup>, כמסופר בגמרא<sup data-n=\"629\">74</sup> שאמרו לשונות שנראים בחיצוניות כו' ובאמת כולהו ברכתא נינהו, ומה שברכו אותו בלשון כזה הוא כמ\"ש אדמו\"ר הצ\"צ<sup data-n=\"630\">75</sup> לפי שהברכה באופן זה היא מבחינת סתים, דהברכות שמבחינת סתים הם ברכות נעלות יותר וגם המשכתם למטה היא בתוקף גדול יותר (מיט אַ שטורעם). וכדאיתא בגמרא שם, שברכו אותו תוליד בנים כו' המשכת וגילוי כח הא\"ס<sup data-n=\"631\">76</sup> בדור ישרים יבורך. והנה פירוש זה (דמה שברכו בלשון כזה הוא לפי שהברכה באופן זה היא מבחינת סתים) אומר אדמו\"ר הצ\"צ שהוא \"יותר נראה כפשטן\". דלפנ\"ז מובא שם (בענין הברכות שבפרשת בחוקותי) שהו\"ע דהיפך הברכה אלא שזה קאי על הלעו\"ז. ואח\"כ מביא פירוש נעלה יותר<sup data-n=\"632\">77</sup>, דמה שהברכות נאמרו בלשון כזה הוא בכדי לחדודי. דגם לפי פירוש זה, ענין הברכה שבלשון זה אינו בפשטות ובגילוי, שהרי בכדי לעמוד על אמיתית הענין צריך לחידוד השכל. אבל לאח\"ז מסיק, דמה שהברכות נאמרו בלשון כזה אין זה גרעון ח\"ו אלא אדרבה מפני שהברכות נעלות יותר. ועל פירוש זה אומר שהוא \"יותר נראה כפשטן\", דמה שלשונות אלו ברכתא נינהו אין זה פירוש מחודד כ\"א הפירוש הפשוט, גם בעולם הפשט. ולאחר שאדמו\"ר הצ\"צ פתח את הדרך, ובפרט שלימד ונתן זה בתורה מלשון הוראה<sup data-n=\"633\">78</sup>, נעשה זה הוראה ונתינת כח לכאו\"א, לפרש ולגלות הברכה גם בלשונות וענינים שבחיצוניותם נראים כו', ואדרבה, ברכות אלו הם נעלות ביותר, וכפשטן, בטוב הנראה והנגלה. דכח זה (להמשיך כל הענינים בטוב הנראה והנגלה) הוא גם בכל ימי השנה. ובפרט בראש השנה כשמכתירים את המלך בשמחה גדולה (כמובא לעיל מכ\"ק מו\"ח אדמו\"ר), דשמחה פורצת כל הגדרים<sup data-n=\"634\">79</sup>. ועאכו\"כ ביו\"ט של ראש השנה שחל להיות בשבת, דכל ההמשכות הנעשים ע\"י תקיעת שופר נעשים הם בשבת מצ\"ע, דבשבת נמשך בחי' תענוג הפשוט, כמבואר בארוכה בהמשך יו\"ט של ראש השנה שחל להיות בשבת לכ\"ק אדמו\"ר (מהורש\"ב) נ\"ע<sup data-n=\"635\">80</sup>.\nיב) <b>וזהו</b> אדון עולם אשר מלך בטרם כל יצור נברא, ומבאר כ\"ק מו\"ח אדמו\"ר במאמרו ד\"ה זה (כמובא לעיל בהתחלת המאמר) דאדון עולם בגימט' אין סוף קאי על המלכות כמו שהוא בעצמותו ית', רצון המוחלט בעצמותו, ומבאר שם<sup data-n=\"636\">81</sup>, דברצון המוחלט בעצמותו אין שייך העלאת מ\"ן כלל. אבל אעפ\"כ, כ\"ז והמאמר ד\"ה אדון עולם בא (כנ\"ל) בהמשך להמאמר ד\"ה יו\"ט של ראש השנה שחל להיות בשבת שבו מבאר הענין דתקיעת שופר בראש השנה (העבודה שכוללתכל פרטי העבודות דכל השנה), דעבודת ישראל פועלת לא רק בנין הז\"א (וגם כל הבחינות והפרצופים דכל ההשתלשלות, כנ\"ל בארוכה), ולא רק שהיא מעוררת גם באוא\"ס שלפני הצמצום בחינת רצון הגלוי (בהבחינה דגילוי לזולתו) וגם בחינת רצון הנעלם (בהבחינה דגילוי לעצמו), אלא יתירה מזו, דמצד זה שישראל מושרשים בהעצמות, הם ממשיכים גם מבחינת רצון המוחלט בעצמותו, בחינת אדון עולם בגימ' אין סוף<sup data-n=\"637\">82</sup>. והמשכה זו היא (בעיקר) למטה בעולם העשי' הגשמיית, ובזה גופא – בענינים גשמיים, דנוסף על הדין בראש השנה בענין המשכת אלקות, משפט<sup data-n=\"638\">83</sup> לאלקי יעקב<sup data-n=\"639\">84</sup>, הנה עיקר הדין בראש השנה הוא בענין השפעות גשמיות<sup data-n=\"640\">85</sup>, וישראל זוכים בדין בב' הענינים, הן בהשפעות רוחניות והן בהשפעות גשמיות בבני חיי ומזוני רויחי, וכאמור דעיקר הענין דראש השנה היא ההמשכה בגשמיות, פועל ישועות בקרב הארץ<sup data-n=\"641\">86</sup>, דהמשכת הישועות (בכל הפירושים שבזה) תהי' באופן דפועל, דלשון פעולה מורה על פעולה גשמיית דוקא עוד יותר מלשון עשי', ובזה גופא בקרב הארץ<sup data-n=\"642\">87</sup>, בתחתון שאין תחתון למטה ממנו. ובפשטות הוא, שכאו\"א מישראל נכתב ונחתם בספרן של צדיקים גמורים<sup data-n=\"643\">88</sup>, כי ועמך כולם צדיקים<sup data-n=\"644\">89</sup> (צדיקים גמורים), לאלתר לחיים<sup data-n=\"643\">88</sup> ולאלתר לגאולה<sup data-n=\"645\">90</sup>, דכאו\"א מישראל יצא מהגלות לגאולה האמיתית והשלימה, וכמ\"ש בההפטורה דראש השנה<sup data-n=\"646\">91</sup> קהל גדול ישובו הנה, דבזה נכלל כל אחד ואחת מישראל כמבואר בארוכה בההפטורה דראש השנה, ובשמחה גדולה, וכנ\"ל שהכתרת המלך היא בשמחה גדולה, ושמחת עולם על ראשם<sup data-n=\"647\">92</sup>, בגאולה האמיתית והשלימה ע\"י משיח צדקנו, בקרוב ממש.\n**********",[["555","*","מאמר זה והקודמו (ד\"ה יום טוב של ראש השנה – דלעיל ע' נא ואילך) יצאו לאור \"לקראת ראש-השנה [ה'תשמ\"ז] . . <i>מוצש\"ק סליחות</i>,<i> ה'תשמ\"ו</i>\"."],["556","1","נוסח תפלת השחר."],["557","2","דשנת תש\"ג – נדפס בסה\"מ תש\"ג ע' 10 ואילך."],["558","3","רפ\"ב."],["559","4","בחיי עה\"פ וישב לח, ל. עמה\"מ שער שעשועי המלך בעצמותו רפ\"א. שעהיוה\"א רפ\"ז. ועוד."],["560","5","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380333\" data-slug=\"likkutei-torah\" data-id=\"4001380333\">לקו\"ת במדבר ו, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380898\" data-slug=\"likkutei-torah\" data-id=\"4001380898\">נצבים מד, ד</a>."],["561","6","בסידורו (שער השמים), ע\"פ פרדס שער עצמות וכלים פ\"ה."],["562","7","אלי' רבא סמ\"ו סקט\"ו, ממטה משה סל\"א בשם גאונים."],["563","8","של\"ה שם. הריעב\"ץ בסידורו (בית יעקב)."],["564","9","המשך תרס\"ו ע' קסז ואילך. ס\"ע קעב. ובכ\"מ."],["565","10","ר\"ה טז, א. לד, ב."],["566","11","ראה מכילתא (ויל\"ש) עה\"פ יתרו כ, ג. פרש\"י עה\"פ אחרי יח, ב. וראה המשך יו\"ט של ר\"ה תש\"ג פכ\"ו (סה\"מ תש\"ג ע' 69)."],["567","12","לקו\"ד כרך ד תשע, ב. וראה גם המשך תרס\"ו ע' תקכב."],["568","13","פ\"ה."],["569","14","משנה ר\"ה רפ\"ד (כט, ב)."],["570","15","ד\"ה להבין הטעם כו' – נדפס באוה\"ת ר\"ה (כרך ה) ע' ב'קט ואילך. וראה גם ד\"ה להבין המשנה כו' ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380943\" data-slug=\"likkutei-torah\" data-id=\"4001380943\">לקו\"ת ר\"ה (נו, א</a> ואילך) ובסידור (עם דא\"ח) שער התקיעות (רמ, ג ואילך)."],["571","16","ראה תקו\"ז תיקון ל' (עד, סע\"א), הובא ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא פ\"ד</a>. רפכ\"ג. ועוד."],["572","17","ביצה יז, א."],["573","18","ויצא כח, יז. פרש\"י עה\"פ."],["574","19","לקו\"א להה\"מ (הוצאת קה\"ת) סקצ\"ח (נ, סע\"ג). או\"ת קיב, ב (בהוצאת קה\"ת תש\"מ ואילך – סת\"פ)."],["575","20","אבות פ\"ב מ\"א."],["576","21","ראה סידור (עם דא\"ח) שער התפילין ז, סע\"א ואילך. אמ\"ב ח\"ג שער התפילין פקל\"ה ואילך (הוצאת קה\"ת תשמ\"ה קיב, א ואילך). ובכ\"מ."],["577","22","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370163\" data-slug=\"torah-or\" data-id=\"3901370163\">תו\"א מקץ לה, ג</a>. ובכ\"מ. ושם, דכ\"ה בכל המצוות, ד\"עיקר הכוונה במעשה המצוות למטה באדם הוא . . להיות הקב\"ה מקיים המצוות\"."],["578","23","ואתחנן ו, ה. שם, יג. עקב י, כ. רמב\"ם הל' יסוה\"ת רפ\"ב."],["579","24","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא פ\"ד</a>. \"פירוש\" לרמב\"ם שם."],["580","25","בהר כה, יח."],["581","26","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380493\" data-slug=\"likkutei-torah\" data-id=\"4001380493\">זח\"ג קיג, א</a>. וראה הגהות הרח\"ו לזהר שם. לקו\"ת שלח מה, ב. ובכ\"מ."],["582","27","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380472\" data-slug=\"likkutei-torah\" data-id=\"4001380472\">לקו\"ת שלח מ, א</a>. עט\"ר דרוש לעשי\"ת נח, סע\"ב ואילך. המשך תרס\"ו ע' נו. לקו\"ד שבהערה 12. בספרים שבהערה הבאה. <i>ועוד</i>."],["583","28","דעיקר ענין המצוות הוא – רצון העליון. ולכן גם המצוות ד\"משפטים\" צריך לקיימם מצד הציווי, בדרך קבלת עול (סה\"מ קונטרסים ח\"א פד, א. קפ, א. סה\"מ אידיש ע' 46. ובכ\"מ)."],["584","29","ראה זח\"ג לב, א. זח\"א רח, ב."],["585","30","תו\"כ (הובא בפרש\"י) עה\"פ ויקרא א, ט. ספרי (הובא בפרש\"י) עה\"פ פינחס כח, ח."],["586","31","ראה גם המשך וככה תרל\"ז פי\"ד."],["587","32","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380217\" data-slug=\"likkutei-torah\" data-id=\"4001380217\">לקו\"ת אמור לב, סע\"ד</a> ואילך. וראה ספר הערכים-חב\"ד ערך אהבת ה' בכל לבבך, נפשך ומאדך ס\"ו. וש\"נ."],["588","33","ברכות לה, ב."],["589","34","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380272\" data-slug=\"likkutei-torah\" data-id=\"4001380272\">לקו\"ת בחוקותי מה, ג</a>. ובכ\"מ."],["590","35","הובא בסה\"מ להצ\"צ שרש מצות התפלה פ\"מ (דרמ\"צ קלח, סע\"א)."],["591","36","פ\"ג ופ\"ד. וראה עד\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380381\" data-slug=\"likkutei-torah\" data-id=\"4001380381\">לקו\"ת במדבר יח, ב</a>."],["592","37","ראה אגה\"ק ס\"י (קטו, א)."],["593","38","ראה טושו\"ע (ודאדה\"ז) או\"ח סתק\"צ."],["594","39","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380896\" data-slug=\"likkutei-torah\" data-id=\"4001380896\">לקו\"ת נצבים מד, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380944\" data-slug=\"likkutei-torah\" data-id=\"4001380944\">ר\"ה נו, ב</a>. ובכ\"מ."],["595","40","ראה תורת הבעש\"ט (לקו\"ד כרך ג תצא, ריש ע\"ב. כתר שם טוב (הוצאת קה\"ת, תשנ\"ט) בהוספות סקנ\"ה): די פשיטות העצמות פון עצמות א\"ס ב\"ה איז זיך מתגלה אין די פשיטות פון אַ איש פשוט. וראה רשימת כ\"ק מו\"ח אדמו\"ר ד\"ה אתם נצבים תש\"ז (סה\"מ תש\"ז ע' 256 ואילך)."],["596","41","בסה\"מ אידיש ע' 138 ואילך. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071148\" data-slug=\"likkutei-sichot\" data-id=\"1300071148\">לקו\"ש ח\"ז ע' 136</a> ואילך."],["597","42","ראה גם לקו\"ד כרך ג תיג, רע\"א."],["598","43","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370064\" data-slug=\"torah-or\" data-id=\"3901370064\">תו\"א וירא יד, ב</a>. מאמרי אדה\"ז תקס\"ה ח\"א ע' יב. ענינים ע' סח. ע. סה\"מ קונטרסים ח\"ב רצו, א. ובכ\"מ."],["599","44","ספר יצירה פ\"א מ\"ז."],["600","45","המשך וככה תרל\"ז פ\"ע. ולהעיר אשר בשנה זו (תשמ\"ג) ימלאו מאה שנה להסתלקות-הילולא שלו."],["601","46","אגרות-קודש לכ\"ק אדמו\"ר מוהריי\"צ ח\"א ע' תריז. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011124\" data-slug=\"likkutei-sichot\" data-id=\"1300011124\">לקו\"ש ח\"א ע' 124</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300121194\" data-slug=\"likkutei-sichot\" data-id=\"1300121194\">חי\"ב ע' 186</a>. ועוד."],["602","47","ומסתבר שגם בהמשל הכוונה לקול <i>פשוט</i>, שהרי \"מחמת אריכות הזמן <i>שכח</i> גם <i>לשון</i> מדינתו\", והמלך מכירו (רק) ע\"י <i>קולו</i>."],["603","48","מספר קדושת לוי (ר\"ה צו, א)."],["604","49","כמובן מזה ש\"לא הכירו את המלך\". וגם הבגדים של החכם (בשעה שהוליך את המלך מהיער) הם בגדים פשוטים שאינם לכבוד ולתפארת – שהרי רק <i>לאח\"ז</i> (כשבא המלך לבית המלכות) הלבישוהו בגדים יקרים."],["605","50","שו\"ע אדה\"ז או\"ח סימן תקפד ס\"ב. ולהעיר ממנהגנו (וצע\"ק משו\"ע אדה\"ז שם ס\"ג), לדלג ב\"אבינו מלכנו\" כל ענין שיש בו הזכרת חטא ואפילו \"כתבנו בספר סליחה ומחילה\"."],["606","51","וגם לפי מ\"ש אדה\"ז בשו\"ע שם ס\"ב דבאמירת פסוקים כו' אין קפידא – אין זה דומה לנדו\"ד, <i>שמאריך</i> בהמאמר <i>ובפרטיות</i> (ולא רק הזכרה בעלמא)."],["607","52","ראה מפתח המאמרים דהמשך הנ\"ל."],["608","53","ומכיון שהמאמר נאמר בש\"פ תבוא ולא בר\"ה – מספיק מה שרק <i>בפנימיות</i> הענינים הוא לשבח. ומה שמדברים ענינים אלו במאמר זה <i>דר\"ה</i> – הרי במאמר זה מבארים <i>בגילוי</i> השבח דמשלים אלו."],["609","54","נצבים כט, יא. וקאי על מ\"ש לפנ\"ז (שם, ט) אתם נצבים היום, דקאי על ר\"ה (<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380883\" data-slug=\"likkutei-torah\" data-id=\"4001380883\">לקו\"ת</a> ר\"פ נצבים. וראה גם לקו\"ת ר\"פ תבוא (מא, ג), מרמ\"ז לזח\"ב לב, ב. וראה גם זח\"ג רלא, א. פענח רזא ס\"פ נצבים)."],["610","55","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380896\" data-slug=\"likkutei-torah\" data-id=\"4001380896\">לקו\"ת נצבים מד, ב</a>. סה\"מ תרצ\"ט ע' 25."],["611","56","ויש לומר, דזהו גם מ\"ש בהמשך וככה שם, \"שהגם שבן ואח אין לו עכ\"ז חבבן וקראן בנים\" – דלכאורה בכו\"כ מקומות מובא ענין זה (דישראל הם בנים למקום) <i>בפשטות</i>, ומדוע כאן דוקא מבאר \"שהגם שבן ואח אין לו כו'\"? ויש לומר, דכוונתו בזה היא לרמז, דמה שישראל נקראים בנים הוא (לא רק בהבחינה ד\"אב\" אלא) גם בהבחינה ד\"בן ואח אין לו\", דגם בבחינה זו \"חבבן וקראן בנים\". וראה שיחת ש\"פ נצו\"י תשמ\"ב (התוועדויות תשמ\"ב ח\"ד ס\"ע 2239 ואילך; ע' 2248 ואילך)."],["612","57","לקו\"ת שם (ס\"ג בתחלתו)."],["613","58","ב\"מ פה, א."],["614","59","וברש\"ל הגי' – \"מ' תעניות\"."],["615","60","<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670197\" data-slug=\"torat-chaim\" data-id=\"2300670197\">בראשית ז, ד</a>. ויצא כב, ד. מג\"א צב, א. צו, א. ק, ג. וראה בארוכה תו\"ח חיי שרה קמ, סע\"ב ואילך. המשך תרס\"ו ס\"ע יב ואילך."],["616","61","דרוש לעשי\"ת נט, ב."],["617","62","ברכות יג, א. עירובין צה, סע\"ב."],["618","63","לשון אדמו\"ר האמצעי בעט\"ר שם (נט, א)."],["619","64","פ\"ה."],["620","65","ב\"ר ספנ\"ח. וממה שמסיים שם \"ואברהם זקן בא בימים\" – משמע, דקאי על לבושים דמצוות (ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370074\" data-slug=\"torah-or\" data-id=\"3901370074\">תו\"א חיי שרה טז, א</a>-ב)."],["621","66","תהלים צג, א. – ולהעיר, אשר פסוק זה שייך לר\"ה – ע\"פ דרשת חז\"ל בפדר\"א פי\"א, שביום שנברא אדה\"ר, בראש השנה, המליך עליו (ועל כל הבריות) את הקב\"ה ואמר <i>ה' מלך גאות לבש</i> וגו'."],["622","67","מדרש תהלים עה\"פ תהלים ח, ג. שהש\"ר פ\"א, ד. פ\"ב, ג (ג). וראה ויק\"ר פל\"א, ה. יל\"ש בשלח רמז רמד. וראה גם מדרש תהלים עה\"פ צג, א."],["623","68","ויש לומר, שזה מרומז ב\"את בגדיו צוה והכניסם לבית <i>גנזיו</i>\". ולהעיר מהמבואר בהמשך באתי לגני ה'שי\"ת פי\"ב ואילך בענין האוצר שלמעלה."],["624","69","ראה פרש\"י ומצו\"ד עה\"פ ישעי' מט, א. זח\"ב קעט, סע\"ב. סה\"ש תש\"ג ריש ע' 140. אוה\"ת נ\"ך (כרך ב) ריש ע' א'נט. וראה גם אגה\"ק ס\"ג."],["625","70","לקו\"ש ח\"ד ע' 1207 ואילך. וש\"נ."],["626","71","אבות פ\"ג מט\"ז."],["627","72","שם מ\"א."],["628","73","ראה שבת כא, א. וש\"נ."],["629","74","מו\"ק ט, ב."],["630","75","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380283\" data-slug=\"likkutei-torah\" data-id=\"4001380283\">לקו\"ת בחוקותי מח, ב</a> בהגהה. וראה אוה\"ת בחוקותי כרך ד ע' א'קפג ואילך."],["631","76","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381288\" data-slug=\"likkutei-torah\" data-id=\"4001381288\">לקו\"ת שה\"ש מ, א</a>. ד\"ה שמח תשמח תרנ\"ז (סה\"מ תרנ\"ז ע' קעו ואילך). סה\"מ עטר\"ת ע' תיד. תרפ\"ו ס\"ע רכו ואילך."],["632","77","מחדא\"ג מהרש\"א למו\"ק שם."],["633","78","ראה רד\"ק לתהלים יט, ח. גו\"א ר\"פ בראשית. זח\"ג נג, ב."],["634","79","ראה ד\"ה שמח תשמח תרנ\"ז (סה\"מ תרנ\"ז ע' רכג ואילך)."],["635","80","תרס\"ו ע' תקמג ואילך."],["636","81","פ\"ה."],["637","82","להעיר גם ממ\"ש בסיום המאמר ד\"ה אדון עולם תש\"ג, דההפלאה (של השבח אדון עולם) היא \"בענין התפלה . . בביטול והנחת עצמותו בהקבע\"ו דר\"ה\". דמזה משמע, דענין העבודה (תפלה), ובפרט בר\"ה, שייכת גם לבחינת \"אדון עולם\"."],["638","83","תהלים פא, ה. ולהעיר אשר מזמור זה הוא שירו של יום ר\"ה (ר\"ה ל, ב)."],["639","84","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380943\" data-slug=\"likkutei-torah\" data-id=\"4001380943\">לקו\"ת ר\"ה נו, א</a>."],["640","85","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380956\" data-slug=\"likkutei-torah\" data-id=\"4001380956\">לקו\"ת שם נט, ב</a> (מהגהות מיימוני (הל' תשובה פ\"ג אות א) בשם הרמב\"ן)."],["641","86","תהלים עד, יב."],["642","87","להעיר מפרש\"י עה\"פ וארא ח, יח (ד\"ה למען תדע גו')."],["643","88","ר\"ה טז, ב."],["644","89","ישעי' ס, כא."],["645","90","בלשון כ\"ק מו\"ח אדמו\"ר ב\"קול קורא\" (נדפס ב\"הקריאה והקדושה\" (סיון, תמוז, אב – תש\"א (אגרות-קודש לכ\"ק אדמו\"ר מוהריי\"צ ח\"ה ס\"ע שסא ואילך. שם ע' שעז ואילך. שם ע' תח ואילך). תשרי תש\"ג (אגרות-קודש ח\"ו ס\"ע תל ואילך)). ואח\"כ גם בפ\"ע)."],["646","91","מירמי' לא, ח."],["647","92","ישעי' לה, י. נא, יא."]]],[1500360010,"– הנחה –\n<b>תקעו</b> בחודש שופר בכסה ליום חגינו גו'<sup data-n=\"648\">1</sup>, ומבאר בזה כ\"ק מו\"ח אדמו\"ר נשיא דורנו [במאמרו ד\"ה תקעו תש\"ז<sup data-n=\"649\">2</sup>, לפני ארבעים שנה, דאחרי ארבעים שנה קאי אינש אדעתי' דרבי'<sup data-n=\"650\">3</sup>], דארז\"ל<sup data-n=\"651\">4</sup> על הפסוק איזהו חג שהחדש מתכסה בו הוי אומר זה ראש השנה, דבכסה הוא כס ה' דה' קאי על ספירת המלכות וכס ענינו כיסוי וראש השנה נק' כסה לפי שבראש השנה ספירת המלכות מתכסית ומתעלמת בהעלם העצמי כו' (ואולי יש להוסיף הקשר לענין חג שהחדש מתכסה בו בפשטות, דחדש בפשטות היא הלבנה, ונודע שהלבנה היא ספירת המלכות), ולכן הנה עיקר עבודת ראש השנה הוא בנין ספירת המלכות כמארז\"ל<sup data-n=\"652\">5</sup> אמרו לפני מלכיות כדי שתמליכוני עליכם כו', וכדי להמשיך בחי' המלכות הוא ע\"י תקיעת שופר וכמ\"ש תקעו כו'.\n{\nb\n}והנה ידוע דיוק מורנו הבעש\"ט (בכתר שם טוב<sup data-n=\"653\">6</sup>) בפסוק זה, דהל\"ל תקעו שופר בחודש. ופירש בזה הבעש\"ט, כי יראה האדם תדיר שיהי' בחודש ר\"ל לחדש מעשים טובים שלא יהי' כמו חוק קבוע. ויש לפרש הדבר, דמכיון שפסוק זה קאי בענין עיקרי וכללי, ענין ראש השנה וענין תמליכוני עליכם, לפיכך יש בו הוראה עיקרית וכללית בעבודה הכללית דכאו\"א מישראל, שצ\"ל העבודה באופן של חידוש, שבכל פעם ובכל רגע ובכל דבר ודבר שעושה, יעשהו כמו דבר חדש ממש<sup data-n=\"654\">7</sup>. [ואולי יש להוסיף בזה עוד, דזהו גם דיוק הלשון תקעו, תקעו גם מלשון חוזק ותוקף<sup data-n=\"655\">8</sup>, שיתקע עצמו בחוזק ותוקף הכי גדול בלי שום שינויים בעבודתו, עד שתוקע עצמו באופן נצחי, דעי\"ז כל רגע מעבודתו הוא דבר חדש]. ובזה יש לבאר הקשר למ\"ש לפנ\"ז בתורת הבעש\"ט שם, דענין הנס הוא שנתחדש הדבר בפעם הראשונה וכשבא עוה\"פ ה\"ז נקרא טבע – היינו שבאמת הכל נס. ויש לקשר זה עם תורת הבעש\"ט<sup data-n=\"656\">9</sup> שכל דבר שבעולם נתחדש בכל רגע, ומה שנקרא בשם טבע הוא רק משום שההתחדשות כבר היתה לפנ\"ז (ולא נתחדש עתה בפעם הראשון). וע\"י ההתבוננות בענין זה גופא מה שבאמת הכל נס ודבר חדש ה\"ז נותן כח לכל ענין בעבודה שיעשהו באופן של דבר חדש ממש.<b>וממשיך</b> אח\"כ בהמאמר (דתש\"ז) שם, דפירוש כסה הוא (גם) לשון זמן ומועד<sup data-n=\"657\">10</sup>, דישנו זמן ומועד מוגבל להמשיך בחי' המלכות. ויש לבאר הקשר דענין זה (כסה לשון זמן ומועד) לענין ראש השנה, ע\"פ תורת הרב המגיד הידועה [שהובאה בדרוש אדמו\"ר הזקן הנדפס בסידור עם דא\"ח<sup data-n=\"658\">11</sup> שנכתב ע\"י בנו וממלא מקומו אדמו\"ר האמצעי], שהזמן הוא נברא. ומזה מובן, דכשם שבראש השנה נפעל חידוש בבריאת כל העולם, כמאמר<sup data-n=\"659\">12</sup> זה היום תחילת מעשיך זכרון ליום ראשון, עד\"ז הרי בראש השנה היא התחדשות כללות בריאת גדרי הזמן והמקום ומציאותם (שהרי זמן ומקום הם גדרי העולם<sup data-n=\"660\">13</sup>). והענין הוא, דהנה ידוע הדיוק (בלקו\"ת<sup data-n=\"661\">14</sup> וכו'), שהרי בכ\"ה אלול נברא העולם<sup data-n=\"662\">15</sup>, ובראש השנה הוא יום ו' למע\"ב, יום בריאת אדם הראשון, ומהו זה היום תחילת מעשיך זכרון ליום ראשון. ומבואר בזה<sup data-n=\"661\">14</sup>, דהגם שבריאת כל העולם כולו היתה ברגע הראשון דששת ימי בראשית, כמ\"ש<sup data-n=\"663\">16</sup> בראשית ברא אלקים את השמים ואת הארץ, וכ\"ש וק\"ו שאז נבראו גדרי הזמן והמקום ומציאותם (שהם גדרי העולם כנ\"ל), מ\"מ, שלימות הבריאה היתה דוקא ביום ו' למע\"ב, יום בריאת אדם. ולכן דוקא יום זה נקרא תחילת מעשיך וזכרון ליום ראשון. ובזה יובן גם זה שיום זה נקרא בשם כסה סתם, שהוא זמן ומועד, כי הגם שהתהוות גדרי הזמן והמקום ומציאותם היתה ברגע הראשון, מ\"מ ביום זה דוקא הוא שלימות דהתהוות גדר ומציאות הזמן (והמקום), משום שזהו יום בריאת אדם הראשון. דאדם הראשון פעל שלימות בכל הבריאה ע\"י המשכת אלקות (מלכותו ית') בבריאה<sup data-n=\"664\">17</sup>, דזהו מה שנקרא אדם ע\"ש אדמה לעליון<sup data-n=\"665\">18</sup>, שהמשיך אלקותו ית' למטה לעשות לו ית' דירה בתחתונים בגדרי הזמן ומקום.\n<b>והנה</b> כשם שהי' זה בפעם הראשונה, שאדם הראשון פעל אז שלימות בכל הבריאה, כולל בענין הזמן, עד\"ז הוא בכל שנה ושנה ע\"י עבודת כל אחד ואחד מישראל, הנקרא ג\"כ אדם ע\"ש אדמה לעליון<sup data-n=\"666\">19</sup>, והיינו שכל אחד ואחד מישראל ע\"י עבודתו ממשיך אלקותו ית' למטה. ואדרבה, לפיכך נברא האדם יחידי ללמדך שכל המקיים נפש אחת מישראל כאילו קיים עולם מלא<sup data-n=\"667\">20</sup>, היינו דזה שאדם הראשון נברא יחידי, אדמה ליחידו של עולם (בחי' יחיד שלמעלה מבחי' אחד<sup data-n=\"668\">21</sup>), בגלל נפש אחת מישראל.<b>וביאור</b> ענין (מה שהמשכת מלכותו ית' בראש השנה קשורה עם זמן מסויים דוקא ועם עבודת ישראל דוקא), דהנה ידוע<sup data-n=\"669\">22</sup> שתכלית כוונת הבריאה היא לעשות לו ית' דירה בתחתונים, היינו שהגילוי אלקות למטה (הדירה לו ית') יהי' בגדרי התחתונים דוקא, בגדרי הזמן ומקום ועשיית הדירה היא ע\"י ישראל. ומטעם זה המשכת המלכות דראש השנה היא בגדרי הזמן דוקא וע\"י עבודת ישראל דוקא<sup data-n=\"670\">23</sup>. וזהו מ\"ש<sup data-n=\"671\">24</sup> את הוי' האמרת היום גו', ומבאר בזה אדמו\"ר הצ\"צ<sup data-n=\"672\">25</sup> ואדמו\"ר מהר\"ש (בד\"ה זה דשנת תר\"ל<sup data-n=\"673\">26</sup>), לכתחילה אריבער<sup data-n=\"674\">27</sup>, שהאמרת יש בו ג' פירושים, והפירוש הראשון (העיקרי) הוא האמרת לשון שבח ותענוג, והיום קאי על ראש השנה<sup data-n=\"675\">28</sup>, והיינו, דהאמרת היום קאי על המשכת התענוג בראש השנה. וכמבואר במ\"א<sup data-n=\"676\">29</sup> שזהו גם מה ששופר דראש השנה הו\"ע התענוג, שופר מלשון שפרו מעשיכם<sup data-n=\"677\">30</sup>. דמזה מובן, שעיקר העבודה דראש השנה היא להשלים התענוג והתאוה שלמעלה לעשות לו ית' דירה בתחתונים, וזה נעשה ע\"י עבודת ישראל, האמרת דייקא.\n<b>וממשיך</b> אח\"כ בהמאמרים<sup data-n=\"678\">31</sup>, דענין בנין המלכות – שהוא בראש השנה, כמבואר בכתבי האריז\"ל<sup data-n=\"679\">32</sup> – שנעשה ע\"י העבודה דתמליכוני עליכם, הנה לזה צ\"ל הסרת כל ההעלמות וההסתרים וכו'. ויש לבאר המשך הענינים עם המבואר לפנ\"ז, דמכיון שבראש השנה המלכות מתכסית ומתעלמת, הרי העבודה דתמליכוני עליכם היא ע\"י הקדמת ביטול הכיסוי וההעלם והסתר. דזה כולל ביטול כל הענינים המבלבלים [כולל ביטול בלבולי הגוף, שתהי' רפואה קרובה ושלימה וכו'], ואדרבה שיהי' באופן דכפליים לתושי'<sup data-n=\"680\">33</sup>. והנה לאחרי הקדמת הסרת ההעלמות וההסתרים (שהו\"ע הזדככות הכלי) צריך להיות העבודה ברצון (שעי\"ז נעשה תוקף האור הרבה יותר מההמשכה שע\"י זיכוך הכלי) כמבואר בהמאמר<sup data-n=\"681\">34</sup>, די\"ל שזהו ענין קבלת מלכותו ית' בפשטות, שהיא ברצון דוקא, ומלכותו<sup data-n=\"682\">35</sup> ברצון קיבלו עליהם<sup data-n=\"683\">36</sup>. וע\"י העבודה דביטול ההעלמות והסתרים, והעבודה דמלכותו ברצון קיבלו עליהם, נעשה בנין המלכות, ועד להשלימות שבזה, יחוד הוי' ואלקים, יחוד אור ושפע, ועד שגם ההעלם דשם אלקים (בחי' המלכות) עצמו יאיר, דזהו מה שהמלכות נבנית בבחי'פרצוף, דהמעלה בבחי' פרצוף דמלכות (על הנקודה שבה) שהיא בבחי' גילוי אור, כמבואר בהמשך שם בארוכה.\n<b>וממשיך</b> שם<sup data-n=\"684\">37</sup>, דזהו גם ביאור נוסח ברכת שופרות, שומע קול תרועת עמו ישראל ברחמים. דתרועה הו\"ע שבירת החומריות והישות, שעי\"ז פועלים שהמלכות תהי' בבחי' גילוי אור. ולכן יו\"ט של ראש השנה שחל להיות בשבת (כ(יום א' ד)ראש השנה דקביעות שנה זו) אין<sup data-n=\"685\">38</sup> תוקעין, לפי שבשבת אין העבודה באופן דשבירה ובירור, דבשבת בורר אסור<sup data-n=\"686\">39</sup>. דטעם הדבר הוא משום שבשבת הוא שלימות ואמיתיות ענין הגשמיות, ובזה אי\"צ להיות עבודת הבירורים וכו'. וממשיך, ומ\"מ במקדש היו תוקעין גם בשבת, לפי שבמקדש הרי היש הוא כתיקונו, שהוא במקום היותר מובחר, והיינו שהגשמי הוא כדבעי, ולזאת במקדש היו תוקעין גם בשבת שאין זה ענין בירור אלא פעולת שלימות נעלית יותר בהגשמי השלם. ואולי יש להוסיף בזה, ע\"פ הידוע<sup data-n=\"687\">40</sup> דבקדש הקדשים מקום ארון אינו מן המדה, והיינו שהי' בזה ענין של מדידה והגבלה, מודד י' אמות לכל רוח<sup data-n=\"688\">41</sup>, ועד\"ז הארון עצמו הי' בו מדידה והגבלה, אמתיים וחצי ארכו ואמה וחצי רחבו ואמה וחצי קומתו<sup data-n=\"689\">42</sup>, וביחד עם זה אינו מן המדה, משום שהיש הוא כתקונו, שהמדידה עצמה היא בלי גבול.\n<b>ויש</b> לומר, שבפנימיות הענין הנה אותה ההמשכה שנמשכה ע\"י התקיעה במקדש (בשבת) נמשכת גם בכל מקום ובכל זמן. וע\"ד דגם כשאין תוקעין כשחל יו\"ט של ראש השנה להיות בשבת, מ\"מ נמשך ע\"י אמירת פסוקי מלכיות זכרונות ושופרות הענין שהי' נמשך בבית המקדש, והיינו שאמירת הפסוקים בכל מקום ובכל זמן ממשיכה אותה ההמשכה דבנין המלכות, וכמובן גם מזה שהפסוקים שאומרים (בכל מקום ובכל זמן) הם במספר עשר דוקא כנגד יו\"ד ספירות שמהם נעשה בנין המלכות<sup data-n=\"690\">43</sup>, והיינו שע\"י האמירה פועלים בנין שלם כו'. דעד\"ז י\"ל יתירה מזו, שבכל מקום ובכל זמן נמשכת גם ההמשכה הנ\"ל שע\"י התקיעה שבמקדש. ויש לומר הביאור בזה, דהנה ידוע מארז\"ל<sup data-n=\"691\">44</sup> ע\"פ<sup data-n=\"692\">45</sup> ושכנתי בתוכם בתוכו לא נאמר אלא בתוכם בתוך כאו\"א מישראל, ונמצא, שבכאו\"א מישראל יש בחי' מקדש הנ\"ל (שבו היו תוקעין גם בשבת). ויתר על כן דפסוק זה (ושכנתי בתוכם) נאמר (בפשטות) על המשכן שעשה משה, שמשכן זה הוא נצחי, כמו כל מעשה ידי משה שהם נצחיים<sup data-n=\"693\">46</sup>.ובפרט ע\"פ המבואר בתניא<sup data-n=\"694\">47</sup> שיש בחי' משה בקרבו של כאו\"א מישראל, שחודר בתוכו און נעמט אים דורך. ובפרט שיש בכאו\"א מישראל גם בחי' הארון הנ\"ל (אינו מן המדה) שהיא בחי' פנימיות הלב, כמבואר בלקו\"ת ובדרושי אדמו\"ר האמצעי<sup data-n=\"695\">48</sup>. ונמצא, שיש בכוחו של כאו\"א מישראל לפעול ביו\"ט של ראש השנה שחל להיות בשבת העלאת הגשמיות גם למעלה מתכלית השלימות שבו שבבית המקדש כמו ע\"י תקיעת שופר בבית המקדש. ובפרט ע\"פ המובא בהמשך המאמרים&lt;37&gt; מהזהר<sup data-n=\"696\">49</sup> שבשבת נעשה אתפשטותא דהאי נקודה, והיינו בנין שלם דספירת המלכות שתהי' בבחי' גילוי אור. ובפרט ע\"פ המבואר בהמשך הידוע<sup data-n=\"697\">50</sup>, שכל שבת הוא מעין דלע\"ל. דמכל זה מובן, שע\"י עבודת ישראל בענין תקעו בחודש שופר בכסה ליום חגינו בראש השנה, פועלים למעלה בנין המלכות בתכלית השלימות, עד שזה פועל למטה גם בעוה\"ז הגשמי, וכמבואר בהמשך המאמרים הנ\"ל&lt;37&gt;, דהעבודה האמיתית היא דגם היש הגשמי הוא בבחי' כלי לאוא\"ס, וזהו עלה אלקים בתרועה<sup data-n=\"698\">51</sup>, עליית שם אלקים, דהיינו המדידה והגבלה דעולם שנברא ע\"י שם אלקים (כמ\"ש בראשית ברא אלקים דייקא), ושיעור העלי' הוא שנכלל בשם הוי', וגם שם הוי' עולה בקול שופר שהו\"ע יחוד הוי' ואלקים, היינו פעולה חדשה בשם הוי' ובשם אלקים.\n<b>ויהי</b> רצון שכן תהי' לנו, שיומשכו כל הענינים הנ\"ל, ובזה נכלל בפשטות שתהי' כתיבה וחתימה טובה לאלתר לחיים טובים בספרן של צדיקים גמורים<sup data-n=\"699\">52</sup>, ועתיד לאתבא צדיקיא (צדיקים גמורים) בתיובתא<sup data-n=\"700\">53</sup>, בגאולה האמיתית והשלימה ע\"י משיח צדקנו, וכמבואר בהמשך שם<sup data-n=\"701\">54</sup>, דתרועה הוא יעקב ודוד, דוד מלכא משיחא, משיח צדקנו, במהרה בימינו ממש.\n**********",[["","","*) יצא לאור בשעתו, \"<i>וא\"ו תשרי ה' </i><b>ת</b><i>הא </i><b>ז</b><i>ו </i><b>ש</b><i>נת </i><b>מ</b><i>שיח</i>\"."],["648","1","תהלים פא, ד. וראה בכל זה אור התורה (יהל אור) עה\"פ. וש\"נ."],["649","2","סה\"מ תש\"ז ע' 125."],["650","3","ראה ע\"ז ה, ב."],["651","4","ר\"ה ח, סע\"א ואילך. וש\"נ."],["652","5","ר\"ה טז, א. לד, ב."],["653","6","סקי\"ט. סרנ\"ו."],["654","7","וראה גם ד\"ה יו\"ט של ראש השנה דליל ער\"ה תשמ\"ג סוף ס\"א (לעיל ע' נב)."],["655","8","ע\"ד ותקעתיו יתד במקום נאמן (ישעי' כב, כג ובמפרשים)."],["656","9","שער היחוד והאמונה בתחלתו."],["657","10","פרש\"י תהלים שם. סנהדרין צו, ב."],["658","11","שער הק\"ש – עה, סע\"ד ואילך."],["659","12","ר\"ה כז, א."],["660","13","ראה שער היחוד והאמונה פ\"ז (פב, א)."],["661","14","נצבים מז, א ואילך. נא, ב. ד\"ה זה היום תרנ\"ז, תרפ\"ד, תש\"ד, תש\"ט, ועוד."],["662","15","פדר\"א פ\"ח. ויק\"ר רפכ\"ט. תוד\"ה לתקופות – ר\"ה ח, א."],["663","16","בראשית א, א ובפרש\"י שם, יד."],["664","17","לקו\"ת נצבים שם, ב. ובכ\"מ."],["665","18","עשרה מאמרות מאמר אם כל חי ח\"ב פל\"ג. של\"ה ג, א. כ, ב. רסח, ב. שא, ב. ועוד."],["666","19","ראה לקו\"ת שם."],["667","20","סנהדרין לז, א במשנה."],["668","21","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370248\" data-slug=\"torah-or\" data-id=\"3901370248\">תו\"א נה, ב</a>. ובכ\"מ."],["669","22","<a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא פל\"ו</a>. ובכ\"מ."],["670","23","ראה סה\"מ תרס\"א בתחלתו. סה\"מ קונטרסים ח\"א קכב, א ואילך."],["671","24","תבוא כו, יז."],["672","25","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450586\" data-slug=\"or-hatorah-hb\" data-id=\"8316450586\">אוה\"ת תבוא ע' תתרנו</a> ואילך. תתרסח ואילך. תתרעט ואילך. ועוד."],["673","26","סה\"מ תר\"ל ע' רצ ואילך. וראה גם ד\"ה זה דער\"ה ש.ז."],["674","27","אגרות-קודש אדמו\"ר מהוריי\"צ ח\"א ע' תריז."],["675","28","ראה גם רמ\"ז לזח\"ב לב, ב. זח\"ג רלא, א. פענח רזא ס\"פ נצבים. לקו\"ת ר\"פ נצבים."],["676","29","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380937\" data-slug=\"likkutei-torah\" data-id=\"4001380937\">לקו\"ת ר\"ה נד, ג</a>. ובכ\"מ."],["677","30","ויק\"ר פכ\"ט, ו."],["678","31","ע' 139 ואילך."],["679","32","ראה פע\"ח שער ר\"ה. ובכ\"מ."],["680","33","ראה שמו\"ר רפמ\"ו."],["681","34","שם ע' 140."],["682","35","נוסח ברכות ק\"ש של ערבית."],["683","36","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380944\" data-slug=\"likkutei-torah\" data-id=\"4001380944\">לקו\"ת ר\"ה נו, סע\"ב</a> ואילך."],["684","37","ע' 142."],["685","38","משנה ר\"ה רפ\"ד. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380943\" data-slug=\"likkutei-torah\" data-id=\"4001380943\">לקו\"ת שם נו, א</a> ואילך. ובכ\"מ."],["686","39","ראה תו\"א ר\"פ חיי שרה. סהמ\"צ להצ\"צ צב, ב ואילך."],["687","40","יומא כא, א."],["688","41","פרש\"י שם."],["689","42","תרומה כה, י."],["690","43","לקו\"ת שם נו, ב. ובכ\"מ."],["691","44","לשון אדמו\"ר הזקן ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380389\" data-slug=\"likkutei-torah\" data-id=\"4001380389\">לקו\"ת נשא כ, סע\"ב</a> [ועד\"ז בכ\"מ]. וראה ר\"ח שער האהבה פ\"ו. של\"ה תרומה שכה, ב ואילך. אלשיך תרומה כה, ח. ובכ\"מ."],["692","45","תרומה שם."],["693","46","סוטה ט, א."],["694","47","פמ\"ב."],["695","48","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380861\" data-slug=\"likkutei-torah\" data-id=\"4001380861\">לקו\"ת נשא שם כג, סע\"ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550428\" data-slug=\"torat-chaim\" data-id=\"2300550428\">תצא לו, א</a>. תו\"ח תרומה תמח, א [בהוצאה החדשה – ח\"ב שח, א]. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161485\" data-slug=\"likkutei-sichot\" data-id=\"1300161485\">לקו\"ש חט\"ז ע' 472</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300261343\" data-slug=\"likkutei-sichot\" data-id=\"1300261343\">חכ\"ו ע' 253</a>. וש\"נ."],["696","49","ח\"ב רד, ב."],["697","50","יו\"ט של ר\"ה תרס\"ו ע' תקמג ואילך (הוצאת קה\"ת, תשל\"א ואילך)."],["698","51","תהלים מז, ו."],["699","52","ר\"ה טז, ב. וראה לקוטי לוי\"צ – אגרות-קודש ע' שי."],["700","53","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380954\" data-slug=\"likkutei-torah\" data-id=\"4001380954\">לקו\"ת ר\"ה נח, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381024\" data-slug=\"likkutei-torah\" data-id=\"4001381024\">האזינו עה, סע\"ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381308\" data-slug=\"likkutei-torah\" data-id=\"4001381308\">שמע\"צ צב, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381329\" data-slug=\"likkutei-torah\" data-id=\"4001381329\">שה\"ש מה, א</a>. נ, סע\"ב. וראה זח\"ג קנג, ב."],["701","54","שם – מסידור האריז\"ל."]]]]});
